(window.GIM_TS=window.GIM_TS||{})["Sanhedrin.8"]={"from":192,"a":[["\u0003מלכים יראו וקמו שרים וישתחוו\u0004 למען ה' אשר נאמן קדוש ישראל ויבחרך","\u0003\"\u0004(ישעיה סט, ז), משמע שתבוא הגאולה בין כה וכה, אף בלא תשובה! \u0003אמר לו ר' אליעזר: והלא כבר נאמר \"אם תשוב ישראל נאם ה' אלי תשוב\"\u0004 (ירמיה ד, א), והרי שהגאולה תלויה בתשובה! \u0003אמר לו ר' יהושע: והלא כבר נאמר \"ואשמע את האיש לבוש הבדים אשר ממעל למימי היאר וירם ימינו ושמאלו אל השמים וישבע בחי העולם כי למועד מועדים וחצי וככלות נפץ יד עם קדש תכלינה כל אלה\"\u0004 (דניאל יב, ז), משמע שיש זמן קבוע לקץ אף בלא תשובה. \u0003ושתק ר' אליעזר,\u0004 שהרי מוכח הדבר מפסוק זה.","\u0003ואמר ר' אבא: אין לך קץ,\u0004 כלומר, סימן גאולה \u0003מגולה\u0004 וברור \u0003מזה שנאמר: \"ואתם הרי ישראל ענפכם תתנו ופריכם תשאו לעמי ישראל\u0004 כי קרבו לבוא\u0003\"\u0004 (יחזקאל לו, ח), וכאשר יתקיים דבר זה שארץ ישראל תיתן פריה בעין יפה, הוא סימן שמתקרבת ביאת המשיח. \u0003ר' אליעזר אומר: אף מ\u0004סימן \u0003זה, שנאמר: \"כי לפני הימים ההם שכר האדם לא נהיה ושכר הבהמה איננה וליוצא ולבא אין שלום מן הצר\"\u0004 (זכריה ח, י), שכאשר לא ישתכר האדם ואף שכר הבהמה יהיה, הרי זה סימן לבוא המשיח בקרוב.","כיון שהוזכר הפסוק שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ליוצא ולבא אין שלום מן הצר\"? רב אמר: אף תלמידי חכמים שכתוב בהם שלום\u0004 ומובטחים בשלוה, וכעין זה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"שלום רב לאהבי תורתך\u0004 ואין למו מכשול\u0003\"\u0004 (תהלים קיט, קסה) \u0003אין שלום\u0004 להם אז \u0003מפני צר. ושמואל אמר:\u0004 הכוונה היא \u0003עד שיהיו כל השערים כולן שקולין,\u0004 שיהא דוחק, וזהו \"ליוצא ולבא אין\", שכל המחירים יהיו שווים מחוסר קונים.","\u0003אמר ר' חנינא: אין בן דוד בא עד שיתבקש\u0004 אפילו \u0003דג לחולה ולא ימצא, שנאמר\u0004 במפלת מצרים: \u0003\"אז אשקיע מימיהם ונהרותם כשמן אוליך\"\u0004 (יחזקאל לב, יד), שלא יהיו מים זורמים בנהרות, \u0003וכתב\u0004 \u0005[וכתוב]\u0006 על אחרי ענין מפלת מצרים \u0003\"ביום ההוא אצמיח קרן לבית ישראל\"\u0004 (יחזקאל כט, כא).","\u0003אמר ר' חמא בר חנינא: אין בן דוד בא עד שתכלה מלכות הזלה,\u0004 מלכות רומי הבזויה והמזלזלת, \u0003מישראל, שנאמר: \"וכרת הזלזלים במזמרות\"\u0004 (ישעיה יח, ה), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]\u0006 \u0003\"בעת ההיא יובל שי לה' צבאות עם ממשך ומורט\"\u0004 (יחזקאל כט, ז).","\u0003אמר זעירי אמר ר' חנינא: אין בן דוד בא עד שיכלו גסי הרוח מישראל, שנאמר: \"כי אז אסיר מקרבך עליזי גאותך\"\u0004 (צפניה ג, יא), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 לאחריו: \u0003\"והשארתי בקרבך עם עני ודל וחסו בשם ה' \"\u0004(צפניה ג יב).","\u0003אמר ר' שמלאי משום\u0004 (בשם) \u0003ר' אלעזר בר' שמעון: אין בן דוד בא עד שיכלו כל שופטים ושוטרים מישראל,\u0004 שלא ישאר עוד לישראל כל שלטון עצמי, \u0003שנאמר: \"ואשיבה ידי עליך ואצרף כבר סיגיך\u0004 ואסירה כל בדיליך. \u0003ואשיבה שפטיך\u0004 כבראשונה","\u0003\"\u0004(ישעיה א, כה-כו), משמע שרק אז יחזרו להיות שופטים בישראל. \u0003אמר עולא: אין ירושלים נפדית אלא בצדקה, שנאמר: \"ציון במשפט תפדה ושביה בצדקה\"\u0004 (ישעיה א, כז). \u0003אמר רב פפא: אי בטלי יהירי\u0004 \u0005[אם יתבטלו\u0006 מישראל \u0005הגאוותנים]\u0006 — \u0003בטלי אמגושי\u0004 \u0005[יבטלו האמגושים,\u0006 כמרי הפרסים\u0005],\u0006 \u0003אי בטלי דייני\u0004 \u0005[אם יבטלו הדיינים\u0006 הרעים\u0005]\u0006 — \u0003בטלי גזירפטי\u0004 \u0005[יבטלו שוטרי האומות],\u0006 ורמז לדבר במקרא: \u0003אי בטלי יהירי בטלי אמגושי\u0004 \u0005[אם יתבטלו היהירים יבטלו האמגושים],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואצרף כבר סיגיך ואסירה כל בדיליך\"\u0004 (ישעיה א, כה). \u0003ואי בטלי דייני בטלי גזירפטי\u0004 \u0005[ואם יבטלו הדיינים יבטלו שוטרי האומות],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הסיר ה' משפטיך פנה איבך\"\u0004 (צפניה ג, טו),","\u0003אמר ר' יוחנן: אם ראית דור שמתמעט והולך\u0004 בחכמה ותורה \u0003חכה לו\u0004 למשיח, \u0003שנאמר: \"ואת עם עני תושיע\"\u0004 (שמואל ב' כב, כח). \u0003אמר ר' יוחנן: אם ראית דור שצרות רבות באות עליו כנהר\u0004 — \u0003חכה לו\u0004 לגואל, \u0003שנאמר: \"כי יבא כנהר צר רוח ה' נססה בו\"\u0004 (ישעיה נט, יט), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]:\u0006 \u0003\"ובא לציון\u0004 \u0003גואל\"\u0004 (ישעיה נט, כ).","\u0003ואמר ר' יוחנן: אין בן דוד בא אלא בדור שכולו זכאי\u0004 ויבוא מפני הזכות, \u0003או כולו חייב\u0004 ויבוא כי אין עוד דרך אחרת לגאולה. ורמז לדבר במקרא: \u0003בדור שכולו זכאי\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועמך כלם צדיקים לעולם יירשו ארץ\"\u0004 (ישעיה ס, כא), או \u0003בדור שכולו חייב,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וירא כי אין איש וישתומם כי אין מפגיע\u0004 ותושע לו זרעו וצדקתו היא סמכתהו\u0003\"\u0004 (ישעיה נט, טז), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \"למעני \u0003למעני אעשה\u0004 כי איך יחל וכבודי לאחר לא אתן\" (ישעיה מח, יא).","\u0003אמר ר' אלכסנדרי: ר' יהושע בן לוי רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 לכאורה במקרא, בהבטחת הגאולה. נאמר: \"הקטן יהיה לאלף והצעיר לגוי עצום אני ה' בעתה אחישנה\" (ישעיה ס, כב), ולכאורה הדברים סותרים, שכן מצד אחד \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"בעתה\"\u0004 ומשמע שיש קץ קבוע, \u0003ו\u0004מצד אחר \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"אחישנה\",\u0004 משמע שתבוא הגאולה עוד לפני הזמן! והוא מתרץ: \u0003זכו\u0004 בתשובה ומעשים טובים — \u0003אחישנה\u0004 לפני הקץ, \u0003לא זכו\u0004 — תבוא הגאולה \u0003בעתה\u0004 הקבוע מראש.","\u0003אמר ר' אלכסנדרי, ר' יהושע בן לוי רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 במשיח: \u0003\"וארו עם ענני שמיא כבר אנש אתה...\u0004 ולה יהב שלטן ויקר ומלכו... שלטנה שלטן עלם \u0003\"\u0004\u0005[והנה עם ענני השמים כבן אדם בא... ולו נתן שלטון וכבוד ומלכות... שלטונו שלטון עולם\"]\u0006 (דניאל ז, יג-יד) \u0003ו\u0004מצד אחר \u0003כתיב\u0004 \u0005[נאמר]:\u0006 במשיח גם כן \"הנה מלכך יבוא לך צדיק ונושע הוא \u0003עני ורכב על חמור\u0004 ועל עיר בן אתונות\" (זכריה ט, ט)! וכך הוא מיישב: אם \u0003זכו\u0004 ישראל — יבוא המשיח \u0003עם ענני שמיא\u0004 בהדר ולמעלה מגדר הטבע, \u0003לא זכו\u0004 — יבוא כ\u0003עני ורוכב על חמור.\u0004","בקשר לפסוק זה מסופר \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שבור מלכא\u0004 \u0005[המלך,\u0006 מלך פרס\u0005]\u0006 \u0003לשמואל\u0004 בלגלוג: \u0003אמריתו\u0004 \u0005[אומרים אתם]\u0006 כי \u0003משיח על חמרא אתי\u0004 \u0005[חמור יבוא],\u0006 \u0003אישדר ליה סוסיא ברקא דאית\u0004 \u0005[אשלח לו\u0006 איפוא \u0005סוס רכיבה שיש]\u0006 \u0003לי. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי אית\u0004 \u0005[האם יש]\u0006 \u0003לך בר חיור גווני\u0004 \u0005[סוס זה בן אלף גוונים],\u0006 כחמורו של המשיח? שודאי גם הוא יהא למעלה מדרך הטבע.","\u0003ר' יהושע בן לוי אשכח\u0004 \u0005[מצא]\u0006 את \u0003אליהו\u0004 הנביא \u0003דהוי קיימי אפיתחא דמערתא\u0004 \u0005[\u0006כ\u0005שהיה עומד על פתח מערת\u0006 הקבורה\u0005]\u0006 של \u0003ר' שמעון בן יוחאי\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003אתינא לעלמא דאתי\u0004 \u0005[אבוא,\u0006 אזכה, \u0005לעולם הבא]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לו: \u0003אם ירצה אדון הזה.\u0004 כלומר, הקדוש ברוך הוא. \u0003אמר ר' יהושע בן לוי: שנים ראיתי,\u0004 אני ואליהו, \u0003וקול שלשה שמעתי\u0004 שאף שכינה היתה שם, וכלפיה אמר לו אליהו: \"אם ירצה אדון הזה\".","\u0003אמר ליה\u0004 \u0005[לו]\u0006 לאליהו: \u0003אימת אתי\u0004 \u0005[מתי יבוא]\u0006 ה\u0003משיח?\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זיל שייליה לדידיה\u0004 \u0005[לך שאל אותו עצמו].\u0006 שאל ר' יהושע: \u0003והיכא יתיב\u0004 \u0005[והיכן\u0006 הוא \u0005יושב]?\u0006 אמר לו אליהו: \u0003אפיתחא\u0004 \u0005[על פתח]\u0006 העיר \u0003רומי.\u0004 שאלו: \u0003ומאי סימניה\u0004 \u0005[ומה סימנו]\u0006 שאדע שמשיח הוא? ענה לו: \u0003יתיב ביני עניי\u0004 \u0005[יושב\u0006 הוא \u0005בין עניים]\u0006 \u0003סובלי חלאים\u0004 \u0003וכולן שרו ואסירי בחד זימנא\u0004 \u0005[וכולם מתירים\u0006 תחבושות \u0005וקושרים בפעם אחת],\u0006 אבל \u0003איהו שרי חד ואסיר חד\u0004 \u0005[הוא מתיר\u0006 תחבושת \u0005אחת וקושר אחת].\u0006 \u0003אמר: דילמא מבעינא\u0004 \u0005[שמא יצטרכו אותי]\u0006 לגאולה ואז ש\u0003לא איעכב\u0004 \u0005[אתעכב]\u0006 עד שאחבוש את כל פצעי.","\u0003אזל לגביה\u0004 \u0005[הלך אליו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 לו ר' יהושע למשיח: \u0003שלום עליך רבי ומורי!\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 המשיח: \u0003שלום עליך בר ליואי\u0004 \u0005[בן לוי]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע: \u0003לאימת אתי מר\u0004 \u0005[מתי יבוא אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003היום.\u0004 לאחר זמן \u0003אתא לגבי\u0004 \u0005[בא\u0006 ר' יהושע בן לוי \u0005אצל]\u0006 \u0003אליהו\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אמר לך\u0004 המשיח? ענהו ש\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שלום עליך בר ליואי. אמר ליה\u0004 \u0005[לו]:\u0006 על ידי כך \u0003אבטחך\u0004 \u0005[הבטחת]\u0006 \u0003לך ולאבוך לעלמא דאתי\u0004 \u0005[ולאביך\u0006 שאתם מגיעים \u0005לעולם הבא],\u0006 שבישרו בשלום נצחי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע בן לוי לאליהו: \u0003שקורי קא\u0004 \u0005שקר הוא]\u0006 \u0003שקר\u0004 \u0003בי\u0004 המשיח, שהרי \u0003אמר לי: היום אתינא\u0004 \u0005[אני בא],\u0006 \u0003ולא אתא\u0004 \u0005[בא],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר לך,\u0004 כלומר, הוא ציטט מן הפסוק \u0003\"היום אם בקלו תשמעו\"\u0004 (תהלים צה, ז).","\u0003שאלו תלמידיו את ר' יוסי בן קיסמא: אימתי בן דוד בא? אמר: מתיירא אני\u0004 להשיבכם \u0003שמא תבקשו ממני אות\u0004 לאמת את דברי. \u0003אמרו לו: אין אנו מבקשין ממך אות.\u0004","\u0003אמר להם: לכשיפול השער הזה\u0004 של רומי שהיה שם באותה שעה. \u0003ויבנה, ויפול ויבנה, ויפול, ואין מספיקין לבנותו\u0004 בשלישית \u0003עד שבן דוד בא. אמרו לו: רבינו, תן לנו אות! אמר להם: ו\u0004כי \u0003לא כך אמרתם לי שאין אתם מבקשין ממני אות?\u0004","\u0003אמרו לו: ואף על פי כן\u0004 רוצים אנו. \u0003אמר להם: אם כך\u0004 שיהא כדברי \u0003יהפכו מי מערת פמייס לדם. ו\u0004אכן כך אירע ש\u0003נהפכו לדם.\u0004","\u0003בשעת פטירתו אמר להן\u0004 לתלמידיו: \u0003העמיקו לי ארוני\u0004 לקוברו עמוק בקרקע."],["\u0003שאין כל דקל ודקל שבבבל שאין סוס של פרסיים נקשר בו\u0004 כשהם יוצאים מפרס וממדי ובאים לכבוש ארצות אחרות, \u0003ואין לך כל ארון וארון ש\u0004נטמן בו מת \u0003בארץ ישראל שאין סוס מדי אוכל בו תבן,\u0004 שבמלחמת גוג ומגוג יוציאו את הארונות מן הקרקע ויעשו מהם אבוסים לבהמותיהם, ואין רצוני שישתמשו בארוני למטרה זו.","\u0003אמר רב: אין בן דוד בא עד שתתפשט המלכות הרשעה\u0004 (רומי) \u0003על\u0004 כל \u0003ישראל תשעה חדשים, שנאמר: \"לכן יתנם עד עת יולדה ילדה ויתר אחיו ישובון על בני ישראל\"\u0004 (מיכה ה, ב), שכאשר יעבור זמן של עת יולדה, תשעה ירחי לידה, אז תבוא הגאולה.","\u0003אמר עולא: ייתי\u0004 \u0005[יבוא]\u0006 המשיח \u0003ולא איחמיניה\u0004 \u0005[אראנו],\u0006 כלומר, מתיירא אני מפני גודל הצרות שיהיו לפני כן, ומוטב שאני לא אהיה באותם הימים. \u0003וכן אמר רבה: ייתי\u0004 \u0005[יבוא]\u0006 המשיח \u0003ולא איחמיניה\u0004 \u0005[אראנו].\u0006 \u0003רב יוסף אמר: ייתי ואזכי דאיתיב בטולא דכופיתא דחמריה\u0004 \u0005[יבוא\u0006 המשיח, \u0005ואזכה שאשב בצל גללי חמורו],\u0006 שמקבל אני עלי את כל היסורים והביזוי לשם כך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבה: מאי טעמא\u0004 \u0005[מה טעם]\u0006 חושש אתה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום חבלו\u0004 (ייסוריו) \u0003של משיח\u0004 והצרות שיהיו עד בואו, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003שאלו תלמידיו\u0004 של ר' אלעזר את \u0003ר' אלעזר\u0004 רבם: \u0003מה יעשה אדם וינצל מחבלו של משיח\u0004 לפני שיבוא? אמר להם: \u0003יעסוק בתורה ובגמילות חסדים.\u0004 והוסיפו לשאול: \u0003ומר\u0004 \u0005[ואדוני],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003תורה\u0004 בידך, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003גמילות חסדים\u0004 בידך!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 חוששני \u0003שמא יגרום החטא\u0004 ויעכב, ולא אנצל בזכות תורה ומעשים טובים, וכדברי \u0003ר' יעקב בר אידי.\u0004 ש\u0003ר' יעקב בר אידי רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד שאמר ה' ליעקב \u0003\"והנה אנכי עמך ושמרתיך בכל אשר תלך\"\u0004 (בראשית כח, טו), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ויירא יעקב מאד ויצר לו\"\u0004 (בראשית לב, ז), ואם ה' מבטיחו, מדוע התיירא?","אלא \u0003שהיה מתיירא\u0004 \u0005[שחשש]\u0006 \u0003שמא יגרום החטא,\u0004 ובשל כך תתבטל אותה הבטחה. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \"עד יעבור עמך ה' עד יעבור עם זו קנית\" (שמות טו, טז); \u0003\"עד יעבר עמך ה' \"\u0004— \u0003זו ביאה ראשונה\u0004 לארץ בימי יהושע, \u0003\"עד יעבר עם זו קנית\"\u0004 — \u0003זו ביאה שניה\u0004 כאשר חזרו מבבל.","\u0003אמור מעתה\u0004 על פי דברים אלה כי \u0003ראויים היו ישראל לעשות להם נס בביאה שניה כ\u0004ניסי מצרים ויהושע שהיו ב\u0003ביאה ראשונה, אלא שגרם החטא\u0004 שביאתם בפעם השניה היתה בדרך הטבע ומתוך כניעה לגויים.","\u0003וכן אמר ר' יוחנן: ייתי\u0004 \u0005[יבוא]\u0006 המשיח \u0003ולא איחמיניה\u0004 \u0005[אראנו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש מאי טעמא\u0004 \u0005[מה הטעם]\u0006 חושש אתה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 על יום ה' כי \u0003\"כאשר ינוס איש מפני הארי ופגעו הדב ובא הבית וסמך ידו על הקיר ונשכו הנחש\"\u0004 (עמוס ה, יט), \u0003בא ואראך דוגמתו בעולם הזה,\u0004 שאף בימים אלה סובלים אנו מצרות גדולות כגון אלה, \u0003בזמן שאדם יוצא לשדה ופגע בו סנטר\u0004 (שומר) הדורש ממנו תשלום — \u0003דומה כמי שפגע בו ארי, נכנס לעיר פגע בו גבאי\u0004 הגובה מיסי המלך — \u0003דומה כמי שפגעו דב, נכנס לביתו ומצא בניו ובנותיו מוטלין ברעב\u0004 — \u0003דומה כמי שנשכו נחש.\u0004","אמר לו ר' יוחנן: \u0003אלא משום דכתיב\u0004 \u0005[שנאמר]\u0006 על יום ה': \u0003\"שאלו נא וראו אם ילד זכר מדוע ראיתי כל גבר ידיו על חלציו כיולדה ונהפכו כל פנים לירקון\"\u0004 (ירמיה ל, ו) —","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ראיתי כל גבר\" אמר רבא בר יצחק אמר רב: מי שכל גבורה שלו\u0004 (הקדוש ברוך הוא) אף הוא יהיה כביכול בצער כיולדה מפני צרות ישראל. \u0003ומאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ונהפכו כל פנים לירקון\"? אמר ר' יוחנן: פמליא של מעלה\u0004 (מלאכים) \u0003ופמליא של מטה\u0004 (ישראל) כולם יצטערו \u0003בשעה שאמר הקדוש ברוך הוא: הללו,\u0004 ישראל, \u0003מעשה ידי, והללו,\u0004 הגויים, \u0003מעשה ידי, היאך אאבד אלו מפני אלו?\u0004 ויהא זמן שייראה כאילו אין עוד לקדוש ברוך הוא הבדל בין ישראל והגויים, ומשום כך יש להתיירא מחבלי משיח.","\u0003אמר רב פפא: היינו דאמרי\u0004 \u0003אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי: \u0003רהיט\u0004 \u0005[רץ]\u0006 \u0003ונפל תורא\u0004 \u0005[השור],\u0006 \u0003ואזיל ושדי ליה סוסיא באורייה\u0004 \u0005[והולך ומעמיד את הסוס במקומו],\u0006 שעכשיו שאין לו שור הריהו שם במקומו סוס, אף שאינו חזק ומשובח כמוהו, וכך כביכול הקדוש ברוך הוא נותן את גדולת ישראל, כאשר חטאו, לגויים.","\u0003אמר רב גידל אמר רב: עתידין ישראל דאכלי שני\u0004 \u0005[שיאכלו\u0006 ויהנו מ\u0005שנות]\u0006 ה\u0003משיח.\u0004 \u0003אמר רב יוסף: פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003ואלא מאן אכיל להו\u0004 \u0005[מי יאכל אותם],\u0006 וכי \u0003חילק ובילק,\u0004 שני ברנשים ריקים, \u0003אכלי להו\u0004 \u0005[\u0006\u0005יאכלו אותם]?\u0006 ומסבירים שבכל זאת יש חידוש בדברי רב גידל, כי הם באו \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דבריו של \u0003ר' הילל,\u0004 ש\u0003אמר: אין משיח לישראל, שכבר אכלוהו,\u0004 כלומר, שכבר התגשמו הנבואות עליו \u0003בימי חזקיה,\u0004 וכאשר דוחים דעתו להלן בכמה ראיות אחרות.","\u0003אמר רב: לא אברי עלמא\u0004 \u0005[נברא העולם]\u0006 \u0003אלא לדוד,\u0004 כלומר, בזכות דוד נברא כל העולם. \u0003ושמואל אמר:\u0004 בזכות \u0003משה. ור' יוחנן אמר:\u0004 העולם נברא \u0003למשיח.\u0004","כיון שדובר במשיח, שואלים: \u0003מה שמו? דבי\u0004 \u0005[בני בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003\"שילה\" שמו, שנאמר: \"עד כי יבא שילה\"\u0004 (בראשית מט, י). \u0003דבי ר' ינאי אמרי\u0004 \u0005[אומרים]:\u0006 \u0003\"ינון\" שמו, שנאמר: \"יהי שמו לעולם לפני שמש ינון שמו\u0004 ויתברכו בו כל גוים יאשרוהו\u0003\"\u0004 (תהלים עב, יז). \u0003דבי\u0004 \u0005[\u0006בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' חנינה אמר: \"חנינה\" שמו, שנאמר: \"אשר לא אתן לכם חנינה\"\u0004 (ירמיה טז, יג). \u0003ויש אומרים\u0004 כי \u0003\"מנחם בן חזקיה\" שמו, שנאמר: \"כי רחק ממני מנחם משיב נפשי\"\u0004 (איכה א, טז). \u0003ורבנן אמרי\u0004 \u0005[אומרים]\u0006 \u0003\"חיוורא דבי\u0004 \u0005[המצורע של בית]\u0006 \u0003רבי\"\u0004 \u0003שמו, שנאמר: \"אכן חליינו הוא נשא ומכאבינו סבלם ואנחנו חשבנהו נגוע מכה אלהים ומענה\"\u0004 (ישעיה נג, ד).","\u0003אמר רב נחמן: אי\u0004 \u0005[אם]\u0006 \u0003מן חייא\u0004 \u0005[החיים]\u0006 בדורנו \u0003הוא\u0004 המשיח, הרי יהיה \u0003כגון אנא\u0004 \u0005[\u0006איש \u0005כמוני]\u0006 שיש לו כבר שלטון וממשלה על ישראל (מהרש\"א), \u0003שנאמר: \"והיה אדירו ממנו ומשלו מקרבו יצא\"\u0004 (ירמיה ל, כא), והוא מפרשו שהגואל יהא אדם שיש לו כבר ממשלה. \u0003אמר רב: אי\u0004 \u0005[אם]\u0006 \u0003מן חייא\u0004 \u0005[החיים]\u0006 בדורנו \u0003הוא,\u0004 הריהו \u0003כגון רבינו הקדוש\u0004 (ר' יהודה הנשיא), שהיה מופלג בקדושתו, חסידותו ותורתו. \u0003אי מן מתיא\u0004 \u0005[אם מן המתים]\u0006 \u0003הוא,\u0004 הריהו \u0003כגון דניאל איש חמודות.\u0004","\u0003אמר רב יהודה אמר רב: עתיד הקדוש ברוך הוא להעמיד להם\u0004 לישראל \u0003דוד אחר\u0004 הוא המשיח, שאף הוא יקרא \"דוד\", \u0003שנאמר: \"ועבדו את ה' אלהיהם ואת דוד מלכם אשר אקים להם\"\u0004 (ירמיה ל, ט) \u0003\"הקים\" לא נאמר אלא \"אקים\",\u0004 משמע שיקים ה' מלך חדש שיהא שמו \"דוד\". \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ודוד עבדי נשיא להם לעולם\"\u0004 (יחזקאל לז, כה), הרי שדוד המלך הוא שיהא מלך ישראל. ענה לו: \u0003כגון קיסר ופלגי\u0004 \u0005[ומשנה]\u0006 ל\u0003קיסר,\u0004 כך יהיו שניהם מושלים, המשיח ימלוך על כל ישראל ודוד המלך שבעבר היה מלך יהיה נשיא, משנה לו.","\u0003דרש ר' שמלאי: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"הוי המתאוים את יום ה' למה זה לכם יום ה' הוא חשך ולא אור\"\u0004 (עמוס ה, יח) — \u0003משל לתרנגול ועטלף שהיו מצפין לאור\u0004 היום שיבוא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003תרנגול לעטלף: אני מצפה לאורה\u0004 — \u0003ש\u0004הרי \u0003אורה שלי היא,\u0004 שכן אני פעיל וחי בשעות האור ונהנה ממנו, אבל \u0003אתה למה לך אורה?\u0004 הרי בשבילך שעות אלה הן כשעות חשיכה."],["\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ליה ההוא מינא\u0004 \u0005[לו מין אחד]\u0006 \u0003לר' אבהו:\u0004 \u0003אימתי אתי\u0004 \u0005[בא]\u0006 \u0003משיח? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לכי חפי להו חשוכא להנהו אינשי\u0004 \u0005[לכאשר יכסה החושך את האנשים הללו,\u0006 אתכם\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003מילט קא לייטת לי\u0004 \u0005[מקלל אתה אותי]\u0006 ללא סיבה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קרא כתיב\u0004 \u0005[המקרא כתוב]\u0006 ומפורש בענין זה: \u0003\"כי הנה החשך יכסה ארץ וערפל לאמים ועליך יזרח ה' וכבודו עליך יראה\"\u0004 (ישעיה ס, ב).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: ימות המשיח\u0004 יהיו \u0003ארבעים שנה, שנאמר: \"ארבעים שנה אקוט בדור\"\u0004 (תהלים צה, י), ומפרשו: ארבעים שנה אקוץ בגויים, שאז יהיו ימי תפארת המשיח (רמ\"ה). \u0003ר' אלעזר בן עזריה אומר:\u0004 ימות המשיח יהיו \u0003שבעים שנה, שנאמר: \"והיה ביום ההוא ונשכחת צר שבעים שנה כימי מלך אחד\"\u0004 (ישעיה כג, טו), \"אחד\" משמעו מיוחד, \u0003איזהו מלך מיוחד\u0004 — \u0003הוי אומר: זה\u0004 מלך ה\u0003משיח.\u0004","\u0003רבי אומר: שלשה דורות\u0004 יהיו ימי המשיח, \u0003שנאמר: \"ייראוך עם שמש ולפני ירח דור דורים\"\u0004 (תהלים עב, ה) \"דור\" ו\"דורים\" הרי שלושה דורות. \u0003ר' הילל אומר: אין להם משיח לישראל, שכבר אכלוהו,\u0004 כלומר, כבר התקיימו נבואות שנבאו עליו \u0003בימי חזקיה,\u0004 אלא הקדוש ברוך הוא עצמו יגאלם וימלוך עליהם בעצמו,","\u0003אמר רב יוסף: שרא ליה מריה\u0004 \u0005[ימחול לו אדונו,\u0006 ה'\u0005]\u0006 \u0003לר' הילל\u0004 שאמר דברים שאין בהם ממש! שהרי \u0003חזקיה אימת הוה\u0004 \u0005[מתי היה]\u0006 — \u0003בבית ראשון, ואילו זכריה\u0004 בן ברכיה הנביא \u0003קא מתנבי\u0004 \u0005[מתנבא]\u0006 \u0003בבית שני ואמר: \"גילי מאד בת ציון הריעי בת ירושל ם הנה מלכך יבוא לך צדיק ונושע הוא עני ורכב על חמור ועל עיר בן אתנות\"\u0004 (זכריה ט, ט), הרי שדורות לאחר חזקיה יש נבואה לא רק לגאולה אלא לביאת המשיח.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 \u0003ר' אליעזר אומר: ימות המשיח\u0004 יהיו \u0003ארבעים שנה.\u0004 ומהיכן אתה למד זאת? — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 במסע ישראל במדבר: \u0003\"ויענך וירעבך ויאכלך\u0004 את המן\u0003\"\u0004 (דברים ח, ג) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"שמחנו כימות עניתנו שנות ראינו רעה\"\u0004 (תהלים צ, טו).","\u0003ר' דוסא אומר:\u0004 ימות המשיח יהיו \u0003ארבע מאות שנה, כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בברית בין הבתרים: \u0003\"ועבדום וענו אתם ארבע מאות שנה\"\u0004 (בראשית טו, יג) \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"שמחנו כימות עניתנו\"\u0004 (תהלים צ, טו).","\u0003רבי אומר:\u0004 ימות המשיח יהיו \u0003שלש מאות וששים וחמש שנה, כמנין ימות החמה, שנאמר: \"כי יום נקם בלבי ושנת גאולי באה\"\u0004 (ישעיה סג, ד), שיהיו ימי הגאולה כשנה שלמה של שנים.","ואגב הבאת הפסוק שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יום נקם בלבי\"? אמר ר' יוחנן: ללבי גליתי\u0004 את יום הנקם, ואולם \u0003לאבריי\u0004 כביכול \u0003לא גליתי\u0004 שלא יצא הדבר בדיבור מפורש. \u0003ר' שמעון בן לקיש אמר: ללבי גליתי,\u0004 סוד זה, ואילו \u0003למלאכי השרת לא גליתי\u0004 אותו.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003אבימי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו: ימות המשיח לישראל\u0004 הם \u0003שבעת אלפים שנה, שנאמר: \"ומשוש חתן על כלה ישיש עליך אלהיך\"\u0004 (ישעיה סב, ה), וחתן שמח בכלה שבעה ימים, ויומו של הקדוש ברוך הוא אלף שנה.","\u0003אמר רב יהודה אמר שמואל: ימות המשיח\u0004 — \u0003כמיום שנברא העולם ועד עכשיו, שנאמר: \"\u0004למען ירבו ימיכם וימי בניכם על האדמה אשר נשבע ה' לאבותיכם לתת להם\" (דברים יא, כא), כלומר, ימשכו ימי המשיח כמו הימים שעברו מן הבריאה עד בואו \u0003\"כימי השמים על הארץ\".\u0004","\u0003רב נחמן בר יצחק אמר: כימי נח עד עכשיו,\u0004 עד שיבוא המשיח, \u0003שנאמר\u0004 בדברי ישעיה על הגאולה: \u0003\"כי מי נח זאת לי אשר נשבעתי\u0004 מעבור מי נח עוד על הארץ כן נשבעתי מקצף עליך ומגער בך\". \u0005(ישעיה נד, ט).\u0006","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: כל הנביאים כולן לא נתנבאו\u0004 בדבריהם על הגאולה ואחרית הימים, \u0003אלא לימות המשיח, אבל לעולם הבא\u0004 יהיו דברים מעל ומעבר לזה, כאמור \u0003\"עין לא ראתה אלהים זולתך יעשה למחכה לו\"\u0004 (ישעיה סד, ג). ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה\u0006 דעה זו\u0005]\u0006 על דעת \u0003שמואל,\u0004 ש\u0003אמר שמואל:\u0004 \u0003אין\u0004 הבדל \u0003בין העולם הזה לימות המשיח אלא\u0004 לענין \u0003שעבוד מלכיות בלבד\u0004 שיסור מישראל.","\u0003ו\u0004עוד \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: כל הנביאים לא נתנבאו אלא ל\u0004מתן שכרם של \u0003בעלי תשובה, אבל צדיקים גמורים\u0004 — \u0003\"עין לא ראתה אלהים זולתך\".\u0004 ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על \u0003ר' אבהו.\u0004 ש\u0003אמר ר' אבהו: מקום שבעלי תשובה עומדין שם\u0004 — \u0003צדיקים אינן עומדין שם,\u0004 שלדעתו בעלי תשובה גדולים מצדיקים, \u0003שנאמר: \"שלום שלום לרחוק ולקרוב\"\u0004 (ישעיה נז, יט), \u0003ברישא\u0004 \u0005[בתחילה]\u0006 שלום ל\u0003רחוק, והדר\u0004 \u0005[ואחר כך]\u0006 ל\u0003קרוב. מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"רחוק\"\u0004 — \u0003רחוק דמעיקרא\u0004 \u0005[שמתחילה],\u0006 שהיה רחוק מה' וחזר בתשובה. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"קרוב\"\u0004 — \u0003קרוב דמעיקרא ודהשתא\u0004 \u0005[מתחילה ועכשיו],\u0006 שהוא צדיק כל ימיו.","\u0003ור' יוחנן אמר:\u0004 \u0003\"לרחוק\"\u0004 פירושו — מי \u0003שהוא רחוק מעבירה\u0004 כל ימיו, והוא הצדיק. \u0003\"קרוב\"\u0004 — \u0003שהוא קרוב מעבירה\u0004 בזמן רשעותו \u0003ונתרחק ממנה\u0004 כשעשה תשובה.","\u0003ו\u0004עוד \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: כל הנביאים כולן לא נתנבאו אלא למשיא בתו לתלמיד חכם ולעושה פרקמטיא\u0004 (מסחר) עבור \u0003תלמיד חכם, ולמהנה תלמיד חכם מנכסיו.\u0004 שכל השכר הטוב זה יגיע לאלה שעשו טובה לתלמיד חכם, \u0003אבל תלמידי חכמים עצמן,\u0004 שכרם \u0003\"עין לא ראתה אלהים זולתך\".\u0004","ושואלים \u0003מאי\u0004 \u0005[מה]\u0006 הוא אותו דבר ש\u0003\"עין לא ראתה\"? אמר ר' יהושע בן לוי: זה יין המשומר בענביו מששת ימי בראשית,\u0004 שאיש עדיין לא טעם ממנו ואינו יודע מה רב טובו. \u0003ריש לקיש אמר: זה עדן, לא ראתה עין מעולם. ואם תאמר אדם\u0004 הראשון \u0003היכן דר\u0004 אם לא בעדן? — אינו כך, אלא דר \u0003בגן. ואם תאמר\u0004 ש\u0003גן הוא עדן\u0004 ואין הבדל ביניהם — \u0003תלמוד לומר: \"ונהר יצא מעדן להשקות את הגן\"\u0004 (בראשית ב, י), הרי ששני מקומות נבדלים הם.","ומעתה שבים אנו לביאור המשנה. שנינו בה ש\u0003האומר אין תורה מן השמים\u0004 אין לו חלק לעולם הבא. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כוונת האמור \u0003\"כי דבר ה' בזה ואת מצותו הפר הכרת תכרת\u0004 הנפש ההיא עוונה בה\u0003\"\u0004 (במדבר טו, לא) — \u0003זה האומר אין תורה מן השמים. דבר אחר: \"כי דבר ה' בזה\"\u0004 — \u0003זה אפיקורוס\u0004 המזלזל בדבר ה'.","\u0003דבר אחר: \"כי דבר ה' בזה\"\u0004 — \u0003זה המגלה פנים בתורה\u0004 שלא כהלכה, ומפרש בה פירושים של שקר. \u0003\"ואת מצותו הפר\"\u0004 — \u0003זה המפר ברית בשר,\u0004 כגון שאינו רוצה למול ערלתו. \u0003\"הכרת תכרת\"\u0004 הכוונה — \u0003\"הכרת\" בעולם הזה, \"תכרת\"\u0004 — \u0003לעולם הבא. מכאן אמר ר' אלעזר המודעי: המחלל את הקדשים,\u0004 כגון שמטמא אותם במזיד, \u0003והמבזה את המועדות\u0004 (את ימי חול המועד), \u0003והמפר בריתו של אברהם אבינו, והמגלה פנים בתורה שלא כהלכה, והמלבין פני חבירו ברבים, אף על פי שיש בידו תורה ומעשים טובים,\u0004 מכל מקום \u0003אין לו חלק לעולם הבא.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"כי דבר ה' בזה\"\u0004 — \u0003זה האומר אין תורה מן השמים. ואפילו אמר\u0004 ש\u0003כל התורה כולה מן השמים חוץ מפסוק\u0004 אחד \u0003זה שלא אמרו הקדוש ברוך הוא, אלא משה מפי עצמו\u0004 אמרו — \u0003זהו\u0004 בכלל \u0003\"כי דבר ה' בזה\". ואפילו אמר\u0004 ש\u0003כל התורה כולה מן השמים חוץ מדקדוק זה\u0004 שדקדקו בו חכמים, או חוץ \u0003מקל וחומר זה,\u0004 חוץ \u0003מגזרה שוה זו\u0004 — \u0003זה הוא \"כי דבר ה' בזה\".\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: הלומד תורה ואינו מלמדה\u0004 לאחרים — \u0003זה הוא \"דבר ה' בזה\",\u0004 שמראה שאינה חשובה בעיניו עד כדי שראויה היא שילמדה לאחרים. \u0003ר' נתן אומר: כל מי שאינו משגיח על המשנה\u0004 ואינו סבור שהיא עיקר ההלכה, בו נאמר \"כי דבר ה' בזה\". \u0003ר' נהוראי אומר: כל שאפשר\u0004 לו \u0003לעסוק בתורה ואינו עוסק\u0004 בה הריהו בכלל \"כי דבר ה' בזה\".","\u0003ר' ישמעאל אומר: זה העובד עבודה זרה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003משמעה?\u0004 כלומר, כיצד דורש הוא מכתוב זה הלכה זו דווקא? ומסבירים: \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 מה שנאמר \u0003\"כי דבר ה' בזה\"\u0004 — \u0003זה המבזה דבור שנאמר לו למשה מסיני\u0004 ושמעוהו כל ישראל: \u0003\"אנכי ה' אלהיך... לא יהיה לך אלהים אחרים\u0004 על פני","\u0003\"\u0004(שמות כ, ב-ג). אגב הזכרת חשיבות לימוד התורה מביאים ש\u0003ר' יהושע בן קרחה אומר: כל הלומד תורה ואינו חוזר עליה\u0004 הריהו \u0003דומה לאדם שזורע ואינו קוצר. ר' יהושע אומר: כל הלומד תורה ומשכחה\u0004 הריהו \u0003דומה לאשה שיולדת\u0004 ואחר כך \u0003קוברת.\u0004","\u0003ר' עקיבא אומר:\u0004"],["\u0003זמר בכל יום, זמר בכל יום,\u0004 כלומר, לעולם עליך לחזור על לימודך כזמר זה ששרים פעמים רבות. \u0003אמר רב יצחק בר אבודימי: מאי קרא\u0004 \u0005[מה\u0006 הוא \u0005הכתוב]\u0006 המרמז לכך — \u0003שנאמר: \"נפש עמל עמלה לו כי אכף עליו פיהו\"\u0004 (משלי טז, כו), שכופה (אוכף) את פיו ומעייפו בשינון ולימוד, \u0003הוא עמל\u0004 בתורה \u0003במקום\u0004 בעולם ה\u0003זה, ותורתו עומלת לו במקום אחר\u0004 לעולם הבא.","\u0003אמר ר' אלעזר: כל אדם לעמל נברא, שנאמר: \"כי אדם לעמל יולד\"\u0004 (איוב ה, ז). ואולם מכתוב זה \u0003איני יודע אם לעמל פה\u0004 של דיבורים \u0003נברא,\u0004 ו\u0003אם לעמל מלאכה נברא\u0004 — \u0003כשהוא אומר \"כי אכף עליו פיהו\"\u0004 (משלי טז, כו) \u0003הוי אומר\u0004 כי \u0003לעמל פה נברא. ועדיין איני יודע\u0004 עמל פה זה \u0003אם לעמל תורה, אם לעמל שיחה\u0004 — \u0003כשהוא אומר \"לא ימוש ספר התורה הזה מפיך\"\u0004 (יהושע א, ח) \u0003הוי אומר\u0004 כי \u0003לעמל תורה נברא. והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רבא: כולהו גופי דרופתקי נינהו\u0004 \u0005[כל הגופים כנרתיקים הם]\u0006 (ערוך) לשים בהם דברים ולהשתמש בהם, \u0003טובי לדזכי דהוי דרופתקי דאורייתא\u0004 \u0005[טוב ל\u0006זה \u0005שזכה שנעשה נרתיק לתורה].\u0006","ובכוונת הכתוב \u0003\"נאף אשה חסר לב\"\u0004 (משלי ו, לב) \u0003אמר ריש לקיש: זה הלומד תורה לפרקים,\u0004 שהוא כנואף הבא לעתים על האשה, שצריך האדם לנהוג כפי \u0003שנאמר: \"כי נעים כי תשמרם בבטנך יכנו יחדו על שפתיך\"\u0004 (משלי כב, יח), שמכאן משמע כי תמיד צריכה התורה להיות בידו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"והנפש אשר תעשה ביד רמה\u0004 מן האזרח ומן הגר את ה' הוא מגדף\u0003\"\u0004 (במדבר טו, ל) — \u0003זה מנשה בן חזקיה\u0004 מלך יהודה \u0003שהיה יושב ודורש בהגדות של דופי\u0004 ומתלוצץ על דברי תורה.","\u0003אמר: וכי לא היה לו למשה לכתוב אלא\u0004 דברים שאין בהם כל צורך ואינם מלמדים אותנו דבר, כגון \u0003\"ואחות לוטן תמנע\"\u0004 (בראשית לו, כב), או \u0003\"ותמנע היתה פילגש לאליפז\u0004 בן עשו\u0003\"\u0004 (בראשית לו,יב), או \u0003\"וילך ראובן בימי קציר חטים וימצא דודאים בשדה\"\u0004 (בראשית ל, יד). \u0003יצאה בת קול ואמרה לו: \"תשב באחיך תדבר בבן אמך תתן דפי אלה עשית והחרשתי דמית היות אהיה כמוך אוכיחך ואערכה לעיניך\"\u0004 (תהלים נ, כ-כא), כלומר, אין דברי תורה כדברים בטלים שאתה יכול לקבוע בפסקנות אם מועילים הם וחשובים, אם לא.","\u0003ועליו מפורש בקבלה\u0004 (בדברי הנביאים) \u0003\"הוי משכי העון בחבלי השוא וכעבות העגלה חטאה\"\u0004 (ישעיה ה, יח), \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003\"כעבות העגלה\"? אמר ר' אסי: יצר הרע בתחלה דומה לחוט של כוביא\u0004 (חוט של אריגה), \u0003ולבסוף\u0004 מתעבה והולך ו\u0003דומה לעבות העגלה,\u0004 כך מדברי לעג על פסוקים אחדים הגיע מנשה לעבור על כל התורה.","ושואלים: \u0003דאתן עלה, מיהת\u0004 \u0005[כשהגענו\u0006 לענין \u0005זה, על כל פנים]\u0006 באמת \u0003\"אחות לוטן תמנע\" מאי היא,\u0004 כלומר, מה מקומו של פסוק זה בתורה? ומסבירים: \u0003תמנע בת מלכים הואי\u0004 \u0005[היתה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אלוף לוטן\"\u0004 (בראשית לו, כט) \u0003\"אלוף תמנע\"\u0004 (בראשית לו, מ) \u0003וכל \"אלוף\"\u0004 — \u0003מלכותא\u0004 \u0005[מלכות]\u0006 \u0003בלא תאגא\u0004 \u0005[כתר]\u0006 \u0003היא,\u0004 שהיו אלופים אלה תקיפים ועצמאים כמלכים, אלא שלא הוכתרו בתואר זה.","\u0003בעיא לאיגיורי\u0004 \u0005[רצתה\u0006 תמנע \u0005להתגייר],\u0006 \u0003באתה אצל אברהם יצחק ויעקב ולא קבלוה, הלכה והיתה פילגש לאליפז בן עשו, אמרה: מוטב תהא שפחה לאומה זו ולא תהא גבירה לאומה אחרת.\u0004 ולבסוף \u0003נפק מינה\u0004 \u0005[יצא ממנה]\u0006 \u0003עמלק\u0004 בן אליפז ותמנע, \u0003דצערינהו\u0004 \u0005[שציער אותם]\u0006 את \u0003ישראל.\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 נענשו? — ש\u0003לא איבעי להו לרחקה\u0004 \u0005[היו צריכים להרחיקה]\u0006 אם באה להתגייר. ואם כן למדנו כמה דברים חשובים מפסוק זה.","ובענין הכתוב \u0003\"וילך ראובן בימי קציר חטים\"\u0004 (בראשית ל, יד), \u0003אמר רבא בר' יצחק אמר רב: מכאן לצדיקים שאין פושטין ידיהן בגזל\u0004 ואפילו בדבר קטן, שהרי לא לקח ראובן מן החיטים שהיו בשדה אלא מן הדודאים שהם הפקר. נאמר שם \u0003\"וימצא דודאים בשדה\"\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 ה\u0003דודאים? אמר רב:\u0004 צמח שקוראים לו \u0003יברוחי. לוי אמר: סיגלי. ר' יונתן אמר: (סיבסוך) [סביסקי].\u0004","ועוד לענין חשיבות לימוד תורה, \u0003אמר ר' אלכסנדרי: כל העוסק בתורה לשמה משים שלום בפמליא של מעלה ובפמליא של מטה, שנאמר: \"או יחזק במעזי יעשה שלום לי שלום יעשה לי\"\u0004 (ישעיה כז, ה), שהמחזיק בתורה (הקרויה \"עוז\") עושה שלום כביכול גם אצל ה'.","\u0003רב אמר: כאילו בנה פלטרין\u0004 (ארמון) \u0003של מעלה\u0004 בשמים \u0003ושל מטה, שנאמר: \"ואשם דברי בפיך ובצל ידי כסיתיך לנטע שמים וליסד ארץ\u0004 ולאמר לציון עמי אתה\u0003\"\u0004 ((ישעיה נא, טז), שהעוסק בדברי תורה כאילו עושה את השמים והארץ. \u0003ר' יוחנן אמר: אף מגין על כל העולם כולו\u0004 בזכות זה, \u0003שנאמר: \"ובצל ידי כסיתיך\",\u0004 שגורם שה' מכסה ומסוכך על העולם. \u0003ולוי אמר: אף מקרב את הגאולה, שנאמר\u0004 שם: \u0003\"ולאמר לציון עמי אתה\".\u0004","ועוד בשבח התורה, \u0003אמר ריש לקיש: כל המלמד את בן חבירו תורה, מעלה עליו הכתוב\u0004 ומחשיב לו \u0003כאילו עשאו\u0004 לאותו תלמיד, \u0003שנאמר: \"\u0004ויקח אברם את שרי אשתו... \u0003ואת הנפש אשר עשו בחרן\"\u0004 (בראשית יב, ה), ללמדנו שכל תלמידיהם שלמדו תורה נחשבו כנפשות שהם עשו. \u0003ר' אליעזר אומר: כאילו עשאן לדברי תורה\u0004 עצמם, שהוא נחשב כיוצרה של התורה, \u0003שנאמר: \"ושמרתם את דברי הברית הזאת ועשיתם אתם\"\u0004 (דברים כט, ח), ומשמע: אתם עושים, יוצרים את התורה. \u0003רבא אמר: כאילו עשאו לעצמו,\u0004 כאילו הוא יוצר את עצמו, \u0003שנאמר: \"ועשיתם אתם\"\u0004 — \u0003אל תקרי \"אתם\" אלא \"אתם\",\u0004 כלומר, אתם עושים את עצמכם.","\u0003אמר ר' אבהו: כל המעשה\u0004 (הגורם) \u0003את חבירו\u0004 לעסוק ב\u0003דבר מצוה, מעלה עליו הכתוב כאילו עשאה\u0004 הוא, \u0003שנאמר:\u0004 \"ויאמר ה' אל משה... \u0003ומטך אשר הכית בו את היאר\u0004 קח בידך והלכת\" (שמות יז, ה), \u0003וכי משה הכהו\u0004 ליאור? \u0003והלא\u0004 מפורש בתורה ש\u0003אהרן הכהו! אלא לומר לך\u0004 ש\u0003כל המעשה את חבירו לדבר מצוה מעלה עליו הכתוב כאילו עשאה\u0004 הוא עצמו.","שנינו במשנה של \u0003אפיקורוס\u0004 אין חלק לעולם הבא. \u0003רב ור' חנינא אמרי תרוייהו\u0004 \u0005[אמרו שניהם]\u0006 שאפיקורוס הוא \u0003זה המבזה תלמיד חכם. ר' יוחנן ור' יהושע בן לוי אמרי\u0004 \u0005[אמרו]\u0006 יותר מכן: \u0003זה המבזה\u0004 את \u0003חבירו בפני תלמיד חכם.\u0004","ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003המבזה חבירו בפני תלמיד חכם אפיקורוס הוי\u0004 \u0005[הוא],\u0006 אם כן ה\u0003מבזה תלמיד חכם עצמו\u0004 — \u0003מגלה פנים\u0004 (מתחצף) \u0003בתורה שלא כהלכה הוי\u0004 \u0005[הוא],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 כי ה\u0003מבזה תלמיד חכם עצמו אפיקורוס הוי,\u0004 אם כן \u0003מגלה פנים בתורה כגון מאי\u0004 \u0005[מה]?\u0006 ומשיבים: \u0003כגון מנשה בן חזקיה\u0004 שדרש את התורה לגנאי.","\u0003ואיכא דמתני לה אסיפא\u0004 \u0005[ויש ששונים\u0006 דברים אלה \u0005על סופה\u0006 של המשנה\u0005]:\u0006 מהו \u0003מגלה פנים בתורה? רב ור' חנינא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003זה המבזה תלמיד חכם, ר' יוחנן ור' יהושע בן לוי אמרי\u0004 \u0005[אומרים]:\u0006 \u0003זה המבזה חבירו בפני תלמיד חכם.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003המבזה תלמיד חכם עצמו מגלה פנים בתורה הוי\u0004 \u0005[הוא],\u0006 אם כן \u0003מבזה חבירו בפני תלמיד חכם\u0004 — \u0003אפיקורוס הוי\u0004 \u0005[הוא],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003המבזה חבירו בפני תלמיד חכם\u0004 הריהו \u0003מגלה פנים בתורה,\u0004 אם כן \u0003אפיקורוס כגון מאן\u0004 \u0005[מי]?\u0006 \u0003אמר רב יוסף: כגון הני דאמרי\u0004 \u0005[אותם שאומרים]\u0006 \u0003מאי אהנו לן רבנן\u0004 \u0005[מה הועילו לנו חכמים]\u0006 בכל לימודם? והלא \u0003לדידהו קרו, לדידהו תנו\u0004 \u0005[לעצמם\u0006 הם \u0005קוראים\u0006 בתורה, \u0005לעצמם\u0006 הם \u0005שונים\u0006 במשנה\u0005].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: האי\u0004 \u0005[זה]\u0006 שאומר כן, \u0003מגלה פנים בתורה נמי\u0004 \u0005[גם כן]\u0006 \u0003הוא,\u0004 שכופר בתורה עצמה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי\"\u0004 (ירמיה לג, כה), שברית הנצח של התורה היא קיום העולם כולו. \u0003אמר רב נחמן בר יצחק: מהכא נמי שמע מינה\u0004 \u0005[מכאן,\u0006 מפסוק זה, \u0005גם כן\u0006 יכול אתה \u0005לשמוע אותו\u0006 רעיון\u0005],\u0006 \u0003שנאמר: \"\u0004אם אמצא בסדום חמישים צדיקים בתוך העיר \u0003ונשאתי לכל המקום בעבורם\"\u0004 (בראשית יח, כו), הרי שהצדיקים מגינים על המקום שהם חיים בו.","\u0003אלא\u0004 מהו אפיקורוס לפי פירוש זה — \u0003כגון דיתיב קמיה רביה\u0004 \u0005[שיושב לפני רבו]\u0006 \u0003ונפלה ליה\u0004 \u0005[לו],\u0006 הזדמן לו, לומר דבר \u0003שמעתא בדוכתא אחריתי\u0004 \u0005[הלכה ממקום אחר]\u0006 \u0003ואמר\u0004 התלמיד: \u0003הכי אמרינן התם\u0004 \u0005[כך אמרנו שם]\u0006 \u0003ולא אמר\u0004 בלשון כבוד לרבו \u0003\"הכי\u0004 \u0005[כך]\u0006 \u0003אמר מר\"\u0004 \u0005[אדוני],\u0006 שגם אם לא למד מפיו — כך דרך כבוד של תורה. \u0003רבא אמר:\u0004 אפיקורוס לשיטה זו הוא \u0003כגון הני דבי\u0004 \u0005[אותם מבית]\u0006 \u0003בנימין אסיא\u0004 \u0005[הרופא]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003מאי אהני לן רבנן\u0004 \u0005[זה הועילו לנו חכמים]\u0006 בכל לימודם? שהרי \u0003מעולם\u0004"],["\u0003לא שרו לן עורבא\u0004 \u0005[התירו לנו עורב]\u0006 \u0003ולא אסרו לן\u0004 \u0005[לנו]\u0006 \u0003יונה,\u0004 שהכל מפורש בתורה ואין חכמים מביאים לנו כל תועלת.","ומספרים: \u0003רבא כי הוו מייתי טריפתא דבי\u0004 \u0005[כאשר היו מביאים טריפה מבית]\u0006 \u0003בנימין קמיה\u0004 \u0005[לפניו],\u0006 \u0003כי הוה חזי\u0004 \u0005[כאשר היה רואה]\u0006 \u0003בה טעמא להיתירא\u0004 \u0005[טעם להיתר]\u0006 \u0003אמר להו\u0004 \u0005[היה אומר להם]:\u0006 \u0003תחזו דקא שרינא לכו עורבא\u0004 \u0005[ראו שאני מתיר לכם עורב],\u0006 שהרי אני מתיר לכם דבר הנראה כאיסור, וכן \u0003כי הוה חזי לה טעמא לאיסורא\u0004 \u0005[כאשר היה רואה בה טעם לאיסור]\u0006 \u0003אמר להו\u0004 \u0005[היה אומר להם]:\u0006 \u0003תחזו דקא אסרנא לכו\u0004 \u0005[ראו שאני אוסר לכם]\u0006 \u0003יונה.\u0004","\u0003רב פפא אמר:\u0004 אפיקורס הוא \u0003כגון\u0004 זה ש\u0003אמר \"הני רבנן\"\u0004 \u0005[\"אלה החכמים\"],\u0006 שיש בכך נימה של זלזול. מסופר כי \u0003רב פפא\u0004 עצמו \u0003אישתלי\u0004 \u0005[שכח]\u0006 \u0003ואמר: \"כגון הני רבנן\"\u0004 \u0005[\"אלה החכמים\"],\u0006 \u0003ואיתיב בתעניתא\u0004 \u0005[וישב בתענית]\u0006 לכפרה, על שאמר בלשון זו.","מסופר: \u0003לוי בר שמואל ורב הונא בר חייא הוו קא מתקני\u0004 \u0005[היו מתקנים]\u0006 \u0003מטפחות\u0004 ל\u0003ספרי\u0004 הקודש \u0003דבי\u0004 \u0005[של בית]\u0006 \u0003רב יהודה.\u0004 \u0003כי מטו\u0004 \u0005[כאשר הגיעו]\u0006 ל\u0003מגילת אסתר אמרי\u0004 \u0005[אמרו]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 \u0003מגילת אסתר לא בעי\u0004 \u0005[צריכה]\u0006 \u0003מטפחת,\u0004 שאינה חשובה כשאר ספרי קודש הצריכים כיסוי מיוחד. \u0003אמר להו\u0004 \u0005[להם]\u0006 רב יהודה: דיבורים \u0003כי האי גוונא נמי מיחזי כי אפקירותא\u0004 \u0005[כגון אלו גם כן נראים כזלזול],\u0006 שלא היה עליכם לומר על המגילה לשון \"זו המגילה\" (רמ\"ה).","\u0003רב נחמן אמר:\u0004 אפיקורוס \u0003זה הקורא רבו בשמו,\u0004 ואינו קורא לו \"רבי פלוני\". ש\u0003אמר ר' יוחנן: מפני מה נענש גיחזי\u0004 בצרעת — \u0003מפני שקרא לרבו בשמו, שנאמר: \"ויאמר גחזי אדני המלך זאת האשה וזה בנה אשר החיה אלישע\"\u0004 (מלכים ב' ח, ה) ולא הזכירו בלשון כבוד.","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 פעם \u0003ר' ירמיה קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' זירא ויתיב וקאמר\u0004 \u0005[וישב ואמר]:\u0006 \u0003עתיד הקדוש ברוך הוא להוציא נחל מבית קדשי הקדשים ועליו\u0004 יצמחו \u0003כל מיני\u0004 צמחי \u0003מגדים\u0004 (מעדנים), \u0003שנאמר: \"ועל הנחל יעלה על שפתו מזה ומזה כל עץ מאכל לא יבול עלהו ולא יתם פריו לחדשיו יבכר כי מימיו מן המקדש המה יוצאים והיה פריו למאכל ועלהו לתרופה\"\u0004 (יחזקאל מז, יב) — \u0003אמר ליה ההוא סבא\u0004 \u0005[לו זקן אחד]\u0006 שהיה שם: \u0003יישר\u0004 \u0005[יפה],\u0006 \u0003וכן אמר ר' יוחנן, יישר. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: כי האי גונא מיחזי אפקרותא\u0004 \u0005[באופן זה\u0006 האם \u0005נראה כזלזול]?\u0006 כשאדם שאיננו גדול בתורה אומר לחכם שדבריו נכונים?","(רמ\"ה) \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא האי סיועי הא מסייע\u0004 \u0005[הרי זה מסייע]\u0006 \u0003לך\u0004 בדבריו ולא לזלזל בא. \u0003אלא אי שמיע לך, הא שמיע לך\u0004 \u0005[אם שמעת\u0006 בנושא זה, \u0005זה שמעת],\u0006 שלעתים המסייע לדברי רבו הוא מזלזל בו. כיצד? \u0003כי הא דיתיב\u0004 \u0005[כמו זה\u0006 שאירע \u0005שישב]\u0006 \u0003ר' יוחנן וקא דריש\u0004 \u0005[ודרש]:\u0006 \u0003עתיד הקדוש ברוך הוא להביא אבנים טובות ומרגליות שהן\u0004 גדולות \u0003שלשים על שלשים אמות, וחוקק\u0004 (חוצב) \u0003בהם\u0004 נקב של \u0003עשר ברום\u0004 (בגובה) \u0003עשרים\u0004 אמות, \u0003ומעמידן בשערי ירושלים, שנאמר: \"ושמתי כדכד שמשתיך ושעריך לאבני אקדח\"\u0004 (ישעיה נד, יב). \u0003לגלג עליו אותו תלמיד\u0004 ו\u0003אמר: השתא כביעתא דצילצלא לא משכחינן\u0004 \u0005[עכשיו\u0006 בימינו אבנים טובות \u0005כביצת התור אין אנו מוצאים]\u0006 — \u0003כולי האי משכחינן\u0004 \u0005[כל כך\u0006 גדולות כפי שדרשת \u0005מוצאים אנו]?\u0006","\u0003לימים הפליגה ספינתו\u0004 של אותו תלמיד \u0003בים, חזינהו\u0004 \u0005[ראה אותם]\u0006 את \u0003מלאכי השרת דקא מנסרי\u0004 \u0005[שהם מנסרים]\u0006 \u0003אבנים טובות ומרגליות\u0004 בגודל זה. \u0003אמר להו\u0004 \u0005[להם\u0006 למלאכים\u0005]:\u0006 \u0003הני למאן\u0004 \u0005[אלה למי]?\u0006 \u0003אמרי\u0004 \u0005[אמרו]\u0006 לו: \u0003עתיד הקדוש ברוך הוא להעמידן בשערי ירושלים. כי הדר אשכחיה\u0004 \u0005[כאשר חזר, מצאו]\u0006 \u0003לר' יוחנן דיתיב וקא דריש\u0004 \u0005[שיושב ודורש]\u0006 בענין מסויים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי, דרוש ולך נאה לדרוש,\u0004 שכן \u0003כשם שאמרת\u0004 בענין האבנים וגודלם, \u0003כך\u0004 אכן \u0003ראיתי, אמר לו\u0004 ר' יוחנן: \u0003ריקה\u0004 \u0005[פוחז,\u0006 איש ריקני\u0005]!\u0006 \u0003אם לא ראית, לא האמנת\u0004 בדברי?! אם כן \u0003מלגלג על\u0004 \u0003דברי חכמים אתה, יהב ביה עיניה\u0004 \u0005[נתן בו עיניו]\u0006 בכעס \u0003ועשאו גל של עצמות,\u0004 שמת אותו תלמיד ונרקב בשרו.","לגופו של ענין \u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 איך אמר ר' יוחנן כי גובה השערים יהיה עשרים אמה, והלא את הכתוב \u0003\"ואולך אתכם קוממיות\"\u0004 (ויקרא כו, יג) דרשו חכמים כך: \u0003ר' מאיר אומר\u0004 לעתיד לבוא יהיה גובהם של בני אדם \u0003מאתים אמה, כשתי קומות של אדם הראשון\u0004 שאמרנו שהיתה קומתו מאה אמה. \u0003ר' יהודה אומר:\u0004 בני אדם יהיו גבוהים \u0003מאה אמה כנגד\u0004 גובה ה\u0003היכל וכותליו, שנאמר: \"אשר בנינו כנטעים מגדלים בנעוריהם בנותינו כזויות מחטבות תבנית היכל\"\u0004 (תהלים קמד, יב), שיהיו הבנים והבנות בגודלו של ההיכל שהיה בנין ההיכל גבוה מאה אמה. ואם יהיו האנשים גדולים כל כך כיצד יכנסו לשערים אלה של עשרים אמה?","ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוחנן\u0004 — התכוון \u0003לכוי דבי זיקא\u0004 \u0005[\u0006\u0005לחלונות המכניסים רוח],\u0006 שהם יהיו עשר על עשרים אמה אבל השערים יהיו גבוהים יותר.","כיון שהוזכר המקרא על הנחל היוצא מקדש הקדשים שואלים: \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 הכתוב \u0003\"ועלהו לתרופה\"? ר' יצחק בר אבודימי ורב חסדא\u0004 נחלקו בכך. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הכוונה היא כעין נוטריקון — \u0003להתיר פה של מעלה,\u0004 כלומר, לרפא את האלמים. \u0003וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 הכוונה היא אכן כעין נוטריקון, ואולם במשמעות שונה — \u0003להתיר פה של מטה\u0004 (בלשון נקיה), כלומר, לרפא את רחמן של עקרות.","ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כעין זה על ידי חכמים אחרים, ש\u0003חזקיה אמר:\u0004 \"לתרופה\" — \u0003להתיר פה אילמין,\u0004 ו\u0003בר קפרא אמר: להתיר פה עקרות,\u0004 ואילו \u0003ר' יוחנן אמר:\u0004 הכוונה \u0003לתרופה ממש.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לתרופה\"\u0004 במשמעות זו? \u0003ר' שמואל בר נחמני אמר:\u0004 נוטריקון הוא — \u0003לתואר פנים של בעלי הפה,\u0004 כלומר, ליפות פניהם של אותם חכמים שעמלו בפיהם בעולם הזה.","ובדומה לכך \u0003דרש ר' יהודה בר' סימון: כל המשחיר פניו על דברי תורה בעולם הזה\u0004 — \u0003הקדוש ברוך הוא מבהיק זיויו לעולם הבא, שנאמר:\u0004 \"קוצותיו תלתלים שחרות כעורב\" (שיר השירים ה, י), ואחר כך נאמר: \u0003\"\u0004\u0003מראהו כלבנון בחור כארזים\"\u0004 (שיר השירים ה, טו), וסמך לו עוד מיד: \"חיכו ממתקים\" (שיר השירים ה, טז),","לומר שמי שעסק בתורה בעולם הזה (\"חיכו ממתקים\") עד שהשחיר פניו עליה, זוכה לזיו פנים בעולם הבא. \u0003אמר ר' תנחום בר' חנילאי כל המרעיב עצמו על דברי תורה בעולם הזה\u0004 — \u0003הקדוש ברוך הוא משביעו לעולם הבא, שנאמר\u0004 תחילה: \"משפטיך תהום רבה\" (תהלים לו, ז), לומר כמה מקפיד ה' על הצדיקים בעולם הזה ואינו נותן להם כראוי, ואחר כך נאמר: \u0003\"ירוין מדשן ביתך ונחל עדניך תשקם\"\u0004 (תהלים לו, ט) (מהרש\"א).","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: עתיד הקדוש ברוך הוא ליתן לכל צדיק וצדיק מלא עומסו\u0004 (חופניו), \u0003שנאמר: \"ברוך ה' יום יום יעמס לנו האל ישועתנו סלה\"\u0004 (תהלים סח, כ) — \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: וכי אפשר לומר כן,\u0004 שיעמוס הקדוש ברוך הוא מלוא חופניו? \u0003והלא כבר נאמר \"מי מדד בשעלו מים ושמים בזרת תכן\u0004 וכל בשלש עפר הארץ","\u0003\"\u0004(ישעיה מ, יב), ואם זרת של הקדוש ברוך הוא היא כל השמים, כיצד יוכל אדם לקבל \"מלא עומסו\" של הקדוש ברוך הוא? \u0003אמר\u0004 לו רב דימי: \u0003מאי טעמא לא שכיחת באגדתא\u0004 \u0005[מה טעם אינך מצוי\u0006 בדברי \u0005אגדה],\u0006 \u0003דאמרי במערבא משמיה\u0004 \u0005[שאומרים בארץ ישראל משמו]\u0006 של \u0003רבא בר מרי: עתיד הקדוש ברוך הוא ליתן לכל צדיק וצדיק שלש מאות ועשרה עולמות, שנאמר: \"להנחיל אהבי יש ואצרתיהם אמלא\"\u0004 (משלי ח, כא) — \u0003\"יש\" בגימטריא תלת מאה ועשרה הוי\u0004 \u0005[שלש מאות ועשרה הם],\u0006 הרי שמעניק ה' במדה גדושה.","ולענין זה עצמו \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' מאיר אומר: במדה שאדם מודד\u0004 לאחרים \u0003מודדין לו\u0004 מלמעלה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בסאסאה בשלחה תריבנה\"\u0004 (ישעיה כז, ח) — בסאה־סאה, כלומר, לפי הסאה שאדם מודד — באותה סאה מודדים לו.","\u0003אמר\u0004 לו \u0003ר' יהושע: וכי אפשר לומר כן?\u0004 אכן יתכן שיהא \u0003אדם נותן מלא עומסו\u0004 שלו \u0003לעני בעולם הזה,\u0004 וכי \u0003הקדוש ברוך הוא נותן לו מלא עומסו\u0004 שלו \u0003לעולם הבא? והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"\u0004ו\u0003שמים בזרת תכן\"\u0004 (ישעיה מ, יב), ואיך יוכל לקבל שפע ברכה כה גדול? ענה לו: \u0003ואתה\u0004 וכי \u0003אי\u0004 (אין) \u0003אומר כן\u0004 כדבריו? הלא \u0003איזו היא מדה מרובה\u0004 אצל ה', האם \u0003מדה\u0004 \u0003טובה מרובה, או מדת פורענות?\u0004 —"],["\u0003הוי אומר מדה טובה מרובה ממדת פורענות,\u0004 וראיה לדבר — \u0003במדה טובה כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויצו שחקים ממעל ודלתי שמים פתח. וימטר עליהם מן לאכל\"\u0004 (תהלים עח, כג-כד), \u0003ו\u0004אילו \u0003במידת פורענות,\u0004 במבול, \u0003הוא אומר: \"וארבת השמים נפתחו\"\u0004 (בראשית ז, יא), משמע שלרעה פותח ה' ארובות (חלונות) בלבד שהם חלק קטן מן הדלתות, משמע שמדה טובה מרובה.","וכיון ש\u0003במידת פורענות כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויצאו וראו בפגרי האנשים הפשעים בי כי תולעתם לא תמות ואשם לא תכבה והיו דראון לכל בשר\"\u0004 (ישעיה סו, כד), \u0003והלא\u0004 אם \u0003אדם\u0004 רק \u0003מושיט אצבעו באור\u0004 \u0005[באש]\u0006 \u0003בעולם הזה\u0004 — \u0003מיד\u0004 הוא \u0003נכוה,\u0004 וכיצד יכול הוא לסבול אש גיהנם שאינה כבה? \u0003אלא, כשם שנותן הקדוש ברוך הוא כח ברשעים לקבל פורענותם, כך נותן הקדוש ברוך הוא כח בצדיקים לקבל טובתן,\u0004 ועומס להם מלא חופניו.","שנינו במשנה ש\u0003ר' עקיבא אומר: אף הקורא בספרים החיצונים\u0004 אין לו חלק בעולם הבא. \u0003תנא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 הכוונה ל\u0003ספרי מינים. רב יוסף אמר: בספר בן סירא נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור למיקרי\u0004 \u0005[לקרוא]\u0006 משום שיש בו צדדים שליליים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסור לקרוא בו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתב ביה\u0004 \u0005[שכתוב בו]\u0006 \u0003\"לא תינטוש גילדנא מאודניה\u0004 \u0005[אל תפשוט את עור הדג מאוזנו],\u0006 מכיסויי הזימים, ש\u0003לא ליזיל משכיה לחבלא\u0004 \u0005[ילך עורו לאיבוד],\u0006 \u0003אלא צלי יתיה בנורא ואיכול ביה תרתין גריצים\"\u0004 \u0005[צלה אותו באש, ואכול בו שתי פיתי לחם],\u0006 וסבור אתה שדבר שטות הוא, ואולם","\u0003אי מפשטיה\u0004 \u0005[אם כפשוטו]\u0006 של אותו ביטוי — \u0003באורייתא נמי כתב\u0004 \u0005[בתורה גם כן כתוב]\u0006 \u0003\"לא תשחית את עצה\"\u0004 (דברים כ, יט), שמצוות \"לא תעשה\" היא שלא לאבד דבר שיש בו תועלת, אף כאן ראוי שלא לאבד מן הדג דבר הראוי להשתמש בו. \u0003אי מדרשא\u0004 \u0005[אם לדרשה]\u0006 בלשון נקיה נתכוון בן סירא — \u0003אורח ארעא קא משמע לן\u0004 \u0005[דרך ארץ השמיע לנו]\u0006 בכך, ש\u0003לא ליבעול\u0004 \u0005[יבעול]\u0006 אדם את אשתו \u0003שלא כדרכה\u0004 שגורם לה אי נעימות.","\u0003ואלא\u0004 אם טוען אתה כנגד הספר \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 בספר בן סירא: \u0003\"בת לאביה מטמונת שוא, מפחדה לא יישן בלילה, בקטנותה\u0004 — \u0003שמא תתפתה\u0004 על ידי אחרים, \u0003בנערותה\u0004 — \u0003שמא תזנה\u0004 מרצון, \u0003בגרה\u0004 — \u0003שמא לא תינשא, נישאת\u0004 — \u0003שמא לא יהיו לה בנים\u0004 ותחזור לביתו, \u0003הזקינה\u0004 — \u0003שמא תעשה כשפים\"\u0004 (בן סירא מב, יא-יד), וסבור אתה שאין לומר כך לאבי הבנות, ואולם \u0003הא רבנן נמי אמרוה\u0004 \u0005[הרי חכמים גם כן אמרו\u0006 זאת\u0005]\u0006 לגבי נשים, שאמרו: \u0003אי אפשר לעולם בלא זכרים ובלא נקבות,\u0004 שהרי הם קיום העולם, מכל מקום \u0003אשרי מי שבניו זכרים, אוי לו למי שבניו נקבות.\u0004","\u0003אלא\u0004 תטען אתה \u0003משום\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"לא תעיל דויא בלבך, דגברי גיברין קטל דויא\"\u0004 (בן סירא יד, א. ל, כט) \u0005[אל תכניס דאגה בלבך, שאנשים גיבורים הרגה הדאגה]\u0006 ואולם \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003שלמה אמרה\u0004 לדבר זה באופן דומה: \u0003\"דאגה בלב איש ישחנה\"\u0004 (משלי יב, כה), ופירשו ביטוי זה \u0003ר' אמי ור' אסי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי הכוונה: \u0003ישיחנה מדעתו,\u0004 שלא יחשוב בה, שלא תציקנו הדאגה, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 \u0003ישיחנה לאחרים\u0004 כדי להקל עליו. ומכל מקום מסכימים הכל שאין להשאיר דאגה בלבו, והרי זה כדברי בן סירא!","\u0003ואלא\u0004 טוען אתה כנגדו \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"מנע רבים מתוך ביתך, ולא הכל תביא אל ביתך\"\u0004 (בן סירא יא, לו) ואולם \u0003הא\u0004 \u0005[הרי]\u0006 \u0003רבי נמי\u0004 \u0005[גם כן]\u0006 \u0003אמרה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר: לעולם לא ירבה אדם רעים בתוך ביתו, שנאמר: \"איש רעים להתרועע\"\u0004 (משלי יח, כד), כלומר, אדם שיש לו רעים רבים סופו שהוא מתרועע, כלומר, נחלש ונהרס.","\u0003אלא\u0004 אמר לו הטעם \u0003משום דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]\u0006 דברי הבאי, שאמר \u0003\"זלדקן\u0004 — \u0003קורטמן, עבדקן\u0004 — \u0003סכסן\u0004 \u0005[בעל זקן קטן\u0006 הוא \u0005ערמומי, בעל זקן עבה\u0006 הוא \u0005טיפש],\u0006 \u0003דנפח בכסיה\u0004 — \u0003לא צחי\u0004 \u0005[\u0006מי \u0005שנופח בכוסו\u0006 להסיר קצף ולכלוך \u0005איננו צמא],\u0006 שאם לא כן לא היה מקפיד. מי ש\u0003אמר \"במאי איכול לחמא\"\u0004 \u0005[\"במה אוכל לחם\"],\u0006 כלומר, איזה לפתן נחוץ לי — \u0003לחמא סב מיניה\u0004 \u0005[\u0006את ה\u0005לחם קח ממנו],\u0006 שבוודאי אינו רעב אם דואג ללפתן. \u0003מאן דאית ליה מעברתא בדיקניה\u0004 \u0005[מי שיש לו מעבורת,\u0006 מקום פנוי, \u0005ב\u0006תוך \u0005זקנו]\u0006 — \u0003כולי עלמא לא יכלי ליה\u0004 \u0005[כל העולם אינם יכולים לו]\u0006 מרוב ערמומיותו. וכיון שדברים אלה דברים בטלים הם אין כדאי לקרוא בספר זה.","\u0003אמר רב יוסף:\u0004 אפילו שאין הספר כולו ראוי להגות בו, מכל מקום \u0003מילי מעלייתא דאית ביה, דרשינן להו\u0004 \u0005[דברים טובים שיש בו, אנו דורשים אותם]\u0006 אפילו ברבים. שנאמר שם: \u0003\"אשה טובה\u0004 — \u0003מתנה טובה, בחיק ירא אלהים תנתן\"\u0004 (בן סירא כו, ג). \u0003\"אשה רעה\u0004 — הרי היא כ\u0003צרעת לבעלה. מאי תקנתיה\u0004 \u0005[מה תקנתו]?\u0006 — \u0003יגרשנה מביתו ויתרפא מצרעתו\"\u0004 (בן סירא כה, ל). \u0003\"אשה יפה\u0004 — \u0003אשרי בעלה, מספר ימיו כפלים\"\u0004 (בן סירא כו, א), שחייו מאושרים וכאילו מספר ימיו כפליים.","\u0003\"העלם עיניך מאשת חן פן תלכד במצודתה. אל תט אצל בעלה למסוך עמו יין ושכר, כי בתואר אשה יפיה רבים הושחתו, ועצומים כל הרוגיה\"\u0004 (בן סירא ט, ט- יא). ועוד נאמר שם: \u0003\"רבים היו פצעי רוכל\"\u0004 (בן סירא יא, לו), ומשמעו — אלה \u0003המרגילים לדבר ערוה. כניצוץ מבעיר גחלת\u0004 (בן סירא יא, מג), \u0003ככלוב מלא עוף, כן בתיהם מלאים מרמה\u0004 (בן סירא יא, לו- לז). \u0003מנע רבים מתוך ביתך, ולא הכל תביא ביתך. רבים יהיו דורשי שלומך,\u0004 ואולם \u0003גלה סודך\u0004 רק \u0003לאחד מאלף.\u0004 אף \u0003\"משוכבת חיקך שמור פתחי פיך\"\u0004 (מיכה ז, ה) ואל תספר לה הכל. \u0003אל תצר\u0004 (תדאג) ל\u0003צרת מחר \"כי לא\u0004 תדע \u0003מה ילד יום\"\u0004 (משלי כז, א) \u0003שמא למחר איננו,\u0004 שמת בינתיים, \u0003ונמצא מצטער על עולם שאינו שלו,\u0004 ונאמר:","\u0003\"כל ימי עני רעים\"\u0004 (משלי טו, טו). \u0003בן סירא אומר: אף לילות\u0004 של עני רעים מפני דאגתו. \u0003בשפל גגים גגו,\u0004 שהוא חי במקום הנמוך בעיר, \u0003ובמרום הרים כרמו,\u0004 שכרמו הוא במקום הגבוה ביותר בין הכרמים ששם המקומות הזולים והפחותים, ובסופו של דבר, כשיורד גשם בעיר \u0003ממטר גגים\u0004 של כל העיר יורד \u0003לגגו\u0004 ומרטיבו, \u0003ומעפר כרמו\u0004 נסחף על ידי הגשם לשאר \u0003כרמים.\u0004","\u0003סימן\u0004 לשמועות הבאות ואומריהן: \u0003זיר\"א רב\"א משרשי\"א, חנינ\"א טובי\"ה\u0004 (ר' חנינא הזכיר אשה טובה) \u0003ינא\"י יפ\"ה\u0004 (ר' ינאי — מי שדעתו יפה) \u0003יוחנ\"ן מרח\"ם\u0004 (ר' יוחנן — מי שמרחם) \u0003יהוש\"ע מקצ\"ר\u0004 (ר' יהושע בן לוי — מי שדעתו קצרה).","\u0003אמר ר' זירא אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"כל ימי עני רעים\u0004 וטוב לב משתה תמיד\u0003\"\u0004 (משלי טו, טו), \u0003\"כל ימי עני רעים\"\u0004 — \u0003אלו בעלי תלמוד\u0004 היגעים תמיד בלימודם, ותמיד יש להם קשיים ושאלות, \u0003\"וטוב לב משתה תמיד\"\u0004 — \u0003אלו בעלי משנה\u0004 שהם יודעים רק הלכה פסוקה וגמורה, ואין להם בעיות.","\u0003רבא אמר איפכא\u0004 \u0005[ההיפך\u0006 הוא הנכון\u0005],\u0006 \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רב משרשיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"מסיע אבנים יעצב בהם\u0004 בוקע עצים יסכן בם\u0003\"\u0004 (קהלת י, ט), \u0003\"מסיע אבנים יעצב בהם\"\u0004 — \u0003אלו בעלי משנה,\u0004 שהם עמלים ואינם נהנים מעמלם, לפי שהם מתייגעים על לימוד המשנה. אבל אינם יכולים להוציא ממנה מסקנה למעשה, ולכן הם כמסיעים משא כבד שאינם נהנים ממנו. \u0003ו\"בוקע עצים יסכן בם\"\u0004 — \u0003אלו בעלי תלמוד,\u0004 שאמנם עובדים קשה אבל יכולים ליהנות מפירות תורתם, בפסק ההלכה.","\u0003ר' חנינא אומר:\u0004 אותו פסוק מתפרש כך: \u0003\"כל ימי עני רעים\"\u0004 — \u0003זה מי שיש לו אשה רעה, \"וטוב לב משתה תמיד\"\u0004 — \u0003זה\u0004 מי \u0003שיש לו אשה טובה. ר' ינאי אומר: \"כל ימי עני רעים\"\u0004 — \u0003זה אסטניס\u0004 (מפונק) הרגיש לדברים מגעילים, \u0003\"וטוב לב משתה תמיד\"\u0004 — \u0003זה שדעתו יפה,\u0004 האיש שאינו מקפיד, ומסוגל לאכול הכל. \u0003ר' יוחנן אמר: \"כל ימי עני רעים\"\u0004 — \u0003זה רחמני,\u0004 לפי שרואה תמיד סבל בעולם ולכן דואב, \u0003\"וטוב לב משתה תמיד\"\u0004 — \u0003זה אכזרי,\u0004 שאיננו כואב בסבלות העולם. \u0003ר' יהושע בן לוי אמר: \"כל ימי\u0004 \u0003עני רעים\"\u0004 — \u0003זה\u0004"],["\u0003שדעתו קצרה,\u0004 כלומר, אינו יכול לסבול דברים שעושים כנגד רצונו. \u0003\"וטוב לב משתה תמיד\"\u0004 — \u0003זה שדעתו רחבה\u0004 ויכול לקבל דברים בנחת. \u0003ואמר ר' יהושע בן לוי:\u0004 אמרנו ש\u0003\"כל ימי עני רעים\", והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003שבתות וימים טובים\u0004 שהוא נח ואוכל בהם? ויש לומר שגם אז ימיו רעים \u0003כ\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: שינוי וסת\u0004 (מנהג קבוע) הוא \u0003תחלת חולי מעיים.\u0004 וכיון שהעני משנה בשבת ובחג את מנהגו באכילה ומנוחה — סובל הוא מחולי מעיים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הקורא פסוק של שיר השירים ועושה אותו כמין זמר\u0004 שלא למטרת קדושה אלא כשירת חולין סתם, \u0003ו\u0004כן \u0003הקורא פסוק\u0004 כל שהוא \u0003בבית משתאות בלא זמנו\u0004 לצורך זמרה בלבד — \u0003מביא רעה לעולם\u0004 על ידי כך. \u0003מפני שהתורה חוגרת שק ועומדת לפני הקדוש ברוך הוא, ואומרת לפניו: רבונו של עולם! עשאוני בניך ככנור שמנגנין בו לצים,\u0004 שהם משתמשים בתורה ככלי משחק.","\u0003אמר לה\u0004 הקדוש ברוך הוא לתורה: \u0003בתי, בשעה שאוכלין ושותין במה יתעסקו? אמרה לפניו: רבונו של עולם! אם בעלי מקרא הן\u0004 — \u0003יעסקו בתורה ובנביאים ובכתובים, אם בעלי משנה הן\u0004 — \u0003יעסקו במשנה, בהלכות ובהגדות, ואם בעלי תלמוד הן\u0004 — \u0003יעסקו בהלכות פסח בפסח, בהלכות עצרת\u0004 (שבועות) \u0003בעצרת, בהלכות חג\u0004 (הסוכות) \u0003בחג.\u0004 ומדוע יבזו את דברי התורה בשימוש בה לצורכי שעשועים? ובמקביל \u0003העיד ר' שמעון בן אלעזר משום\u0004 (בשם) \u0003ר' שמעון בן חנניא: כל הקורא פסוק בזמנו\u0004 שראוי לקרותו בו, ובאופן הראוי — \u0003מביא טובה לעולם, שנאמר: \"\u0004שמחה לאיש במענה פיו \u0003ודבר בעתו מה טוב\"\u0004 (משלי טו, כג).","במשנה נמנה בין אלה שאין להם חלק לעולם הבא גם \u0003הלוחש על המכה. אמר ר' יוחנן: וברוקק בה\u0004 בשעת לחישה, \u0003לפי שאין מזכירין שם שמים על הרקיקה,\u0004 והמזכיר שם שמים על הרקיקה מבזה את השם, ולכן נענש. \u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003רב אמר: אפילו\u0004 את הפסוק \u0003\"נגע צרעת\u0004 כי תהיה באדם והובא אל הכהן\u0003\"\u0004 (ויקרא יג, ט) שאין בו שם, אין אומרים ללחש. \u0003ר' חנינא אמר: אפילו\u0004 פסוק שאיננו קשור לענין מחלה, וכגון \u0003\"ויקרא אל משה\"\u0004 ((ויקרא א, א) אין אומרים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003סכין וממשמשין בבני מעיים בשבת\u0004 כדי להקל את הכאב, ואין בכך משום איסור רפואה בשבת. \u0003ולוחשין לחישת נחשים ועקרבים בשבת\u0004 לרפא את כאב הנשיכה (רמב\"ם). \u0003ומעבירין כלי על גב העין בשבת,\u0004 כלומר, שאם סובל מדלקת בעין מותר לו לשים כלי קר כדי לצנן מעט. \u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 — \u0003בכלי הניטל,\u0004 כלי שמותר לטלטלו בשבת, \u0003אבל בכלי שאינו ניטל\u0004 — \u0003אסור. ואין שואלין בדבר שדים בשבת. ר' יוסי אומר: אף בחול אסור.\u0004","\u0003אמר רב הונא: הלכה כר' יוסי.\u0004 ומעירים: \u0003ואף ר' יוסי לא אמרה\u0004 לאסור מפני איסור תורה של כשפים, \u0003אלא משום סכנה\u0004 שמא יזיקוהו השדים, \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 של \u0003רב יצחק בר יוסף\u0004 שנשאל בשד וגרם לו \u0003דאיבלע בארזא\u0004 \u0005[שנבלע ב\u0006תוך \u0005הארז]\u0006 (רש\"ש), \u0003ואתעביד ליה ניסא\u0004 \u0005[ונעשה לו נס]\u0006 ו\u0003פקע ארזא\u0004 \u0005[הארז],\u0006 \u0003ופלטיה\u0004 \u0005[ופלטו],\u0006 ללמד כמה מסוכן הדבר.","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003סכין וממשמשין בבני מעיים בשבת\u0004 לרפואה \u0003ובלבד שלא יעשה\u0004 בשבת \u0003כדרך שהוא עושה בחול!\u0004 ושואלים: \u0003היכי עביד\u0004 \u0005[כיצד עושה]\u0006 בשבת? \u0003ר' חמא בר' חנינא אמר: סך\u0004 תחילה \u0003ואחר כך ממשמש. ר' יוחנן אמר: סך וממשמש\u0004 בשבת \u0003בבת אחת,\u0004 שכיון שעושה בשינוי — מותר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שרי שמן ושרי ביצים,\u0004 שהם שדים ששואלים אותם על ידי שמן וביצים — \u0003מותרין לשאול בהן\u0004 בשבת ואין בכך משום איסור, \u0003אלא\u0004 אין טעם לעשות כן \u0003מפני שמכזבין,\u0004 שאינם עונים תשובות אמת. ועוד: \u0003לוחשין\u0004 לרפואה \u0003על שמן שבכלי, ואין לוחשין על שמן שביד. לפיכך סכין משמן ש\u0004מביאים \u0003ביד\u0004 מכל אדם, כי אין לחשוש שמא לחשו עליו, \u0003ואין סכין משמן שבכלי\u0004 שמא לחשו עליו ויזיקנו.","ומסופר, \u0003רב יצחק בר שמואל בר מרתא איקלע לההוא אושפיזא\u0004 \u0005[הזדמן לפונדק אחד]\u0006 \u0003אייתי ליה מישחא במנא\u0004 \u0005[הביאו לו שמן בכלי],\u0006 \u0003שף, נפקן ליה צימחי באפיה\u0004 \u0005[סך\u0006 משמן זה בפניו, ו\u0005יצאו לו אבעבועות בפניו],\u0006 \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003לשוק, חזיתיה ההיא איתתא\u0004 \u0005[ראתה אותו אשה אחת]\u0006 ו\u0003אמרה: זיקא\u0004 \u0005[\u0006את \u0005הרוח\u0006 הרעה\u0005]\u0006 של \u0003חמת קא חזינא הכא\u0004 \u0005[אני רואה כאן\u0006 בפניך\u0005].\u0006 \u0003עבדא ליה מלתא ואיתסי\u0004 \u0005[עשתה לו דבר,\u0006 לחש, \u0005והתרפא].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרבה בר מרי, כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"כל המחלה אשר שמתי במצרים לא אשים עליך כי אני ה' רפאך\"\u0004 (שמות טו, כו), ויש לשאול: \u0003וכי מאחר שלא שם\u0004 מחלה, אם כן \u0003רפואה למה? אמר ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: מקרא זה מעצמו נדרש,\u0004 שיש בו תשובה לשאלה זו באופן זה, \u0003שנאמר: \"ויאמר אם שמוע תשמע לקול ה' אלהיך...\"\u0004(שמות טו, כו), \u0003אם תשמע\u0004 — \u0003לא אשים, ואם לא תשמע\u0004 — \u0003אשים.\u0004 ו\u0003אף על פי כן,\u0004 גם אם לא תשמע ותהיה בך מחלה, דע לך \u0003כי אני ה' רפאך\u0004 וארפאך גם אז.","\u0003אמר רבה בר בר חנה: כשחלה ר' אליעזר נכנסו תלמידיו לבקרו. אמר להן: חמה עזה יש בעולם,\u0004 כלומר, רואה אני שהקדוש ברוך הוא כועס על העולם, ומשום כך אני סובל יסורים (רמ\"ה). \u0003התחילו הן,\u0004 תלמידיו, \u0003בוכין\u0004 מפני צערו של רבם, \u0003ור' עקיבא\u0004 היה \u0003משחק\u0004 (צוחק). \u0003אמרו לו: למה אתה משחק? אמר להן: וכי מפני מה אתם בוכים? אמרו לו: אפשר ספר תורה,\u0004 רבינו, ר' אליעזר, המלא וגדוש תורה כספר תורה \u0003שרוי בצער, ולא נבכה?\u0004","\u0003אמר להן: לכך אני משחק,\u0004 מטעם זה עצמו, כי \u0003כל זמן שאני רואה\u0004 את \u0003רבי שאין יינו מחמיץ\u0004 במחלה, \u0003ואין פשתנו לוקה, ואין שמנו מבאיש, ואין דובשנו\u0004 (הדבש שלו) \u0003מדביש\u0004 (מתקלקל), \u0003אמרתי: שמא חס ושלום קיבל רבי\u0004 את \u0003עולמו,\u0004 כלומר, שכר מצוותיו, שהוא ראוי לו לעולם הבא, בחייו. \u0003ועכשיו שאני רואה\u0004 את \u0003רבי\u0004 כשהוא \u0003בצער\u0004 — \u0003אני שמח.\u0004 שבוודאי מקבל עכשיו עונשו על מעט חטאים שחטא כדי שיקבל את כל שכרו בעולם הבא. \u0003אמר לו\u0004 ר' אליעזר: \u0003עקיבא! כלום חיסרתי מן התורה כולה? אמר לו, לימדתנו רבינו: \"כי אדם אין צדיק בארץ אשר יעשה טוב ולא יחטא\"\u0004 (קהלת ז, כ).","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בענין זה: \u0003כשחלה ר' אליעזר, נכנסו ארבעה זקנים לבקרו: ר' טרפון, ור' יהושע, ור' אלעזר בן עזריה, ור' עקיבא.\u0004","\u0003נענה ר' טרפון\u0004 בדברי עידוד \u0003ואמר: טוב אתה לישראל מטיפה של גשמים, שטיפה של גשמים\u0004 מועילה רק \u0003בעולם הזה,\u0004 \u0003ורבי\u0004 מועיל \u0003בעולם הזה ובעולם הבא.\u0004","\u0003נענה ר' יהושע ואמר: טוב אתה לישראל יותר מגלגל חמה, שגלגל חמה בעולם הזה ורבי בעולם הזה ובעולם הבא. \u0004","\u0003נענה ר' אלעזר בן עזריה ואמר: טוב אתה לישראל יותר מאב ואם, שאב ואם\u0004 מועילים \u0003בעולם הזה, ורבי\u0004 מועיל \u0003בעולם הזה\u0004 \u0003ו\u0004אף \u0003בעולם הבא. \u0004","\u0003נענה ר' עקיבא ואמר: חביבין יסורין.\u0004 מששמע זאת ר' אליעזר \u0003אמר להם\u0004 למשמשיו: \u0003סמכוני,\u0004 כלומר, החזיקו בי שאוכל לשבת, \u0003ואשמעה\u0004 את \u0003דברי עקיבא תלמידי, שאמר \"חביבין יסורין\", אמר לו: עקיבא, זו מנין לך? אמר\u0004 לו: \u0003מקרא אני דורש,\u0004 נאמר: \u0003\"בן שתים עשרה שנה מנשה במלכו וחמשים וחמש שנה מלך בירושלם... ויעש הרע בעיני ה' \"\u0004\u0005(מלכים ב' כא, א-ב)\u0006."],["ונאמר \u0003וכתיב\u0004 \u0005[ונאמר]\u0006: \u0003\"גם אלה משלי שלמה אשר העתיקו אנשי חזקיה מלך יהודה\"\u0004 (משלי כה, א), משמע שחזקיה עסק בלימוד התורה והרבצתה ברבים, \u0003וכי חזקיה מלך יהודה לכל העולם כולו לימד תורה, ו\u0004אילו \u0003למנשה בנו לא לימד תורה? אלא\u0004 ודאי דאג ללמדו הרבה, ובכל זאת \u0003מכל טורח שטרח בו ומכל עמל שעמל בו לא העלהו למוטב אלא יסורין, שנאמר: \"וידבר ה' אל מנשה ואל עמו ולא הקשיבו. ויבא ה' עליהם את שרי הצבא אשר למלך אשור וילכדו את מנשה בחחים ויאסרהו בנחשתים ויוליכהו בבלה\"\u0004 (דברי הימים ב' לג, י-יא)","\u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחר כך: \u0003\"וכהצר לו חלה את פני ה' אלהיו ויכנע מאד מלפני אלהי אבותיו. ויתפלל אליו ויעתר לו וישמע תחנתו וישיבהו ירושל ם למלכותו וידע מנשה כי ה' הוא האלהים\"\u0004 (דברי הימים ב' יב-יג), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת שחביבין יסורין,\u0004 שיפה כוחם לתקן יותר מדברים אחרים.","כיון שהוזכרה אגב הסיפור תשובת מנשה, מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003שלשה באו בעלילה\u0004 בטענה כלפי הקדוש ברוך הוא, ו\u0003אלו הן: קין, עשו ומנשה. קין\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שאמר קין: \u0003\"גדול עוני מנשוא\"\u0004 (בראשית ד, יג), \u0003אמר לפניו: רבונו של עולם, כלום גדול עוני מששים ריבוא שעתידין לחטוא לפניך\u0004 בחטא העגל \u0003ואתה סולח להם?\u0004 אם כן ודאי גם לעווני יש מחילה. \u0003עשו\u0004 — בא בטענה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הברכה אחת היא לך אבי\"\u0004 (בראשית כז, לח). וכן \u0003מנשה\u0004 — \u0003בתחילה קרא לאלוהות הרבה\u0004 ולא ענוהו, \u0003ולבסוף קרא לאלהי אבותיו,\u0004 וטען: אם ה' לא יענהו משמע שכולם שווים.","שנינו במשנה ש\u0003אבא שאול אומר\u0004 ש\u0003אף ההוגה את השם באותיותיו\u0004 אין לו חלק לעולם הבא. \u0003תנא:\u0004 מדובר כשהוגה את השם \u0003בגבולין\u0004 ולא במקדש, \u0003ובלשון עגה\u0004 בלשון שיחה, שלא לצורך (גאונים).","שנינו במשנה ש\u0003שלשה מלכים וארבעה הדיוטות\u0004 אין להם חלק לעולם הבא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ירבעם\u0004 נקרא כך משום \u0003שריבע\u0004 (הרביץ), כלומר, השפיל את ישראל. \u0003דבר אחר: ירבעם\u0004 — \u0003שעשה מריבה בעם\u0004 ופילג את ישראל. \u0003דבר אחר: ירבעם\u0004 — \u0003שעשה מריבה בין ישראל לאביהם שבשמים,\u0004 שהרי עשה את עגלי הזהב. ונקרא \u0003בן נבט\u0004 — \u0003בן שניבט\u0004 (הביט) \u0003ולא ראה\u0004 כראוי.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003הוא נבט, הוא מיכה, הוא שבע בן בכרי,\u0004 ושמותיו נדרשים כך: \u0003\"נבט\"\u0004 — \u0003שניבט ולא ראה,\u0004 שחשב שהוא עצמו יגיע לגדולה ובאמת זכה לגדולה רק בנו. \u0003\"מיכה\"\u0004 — משום \u0003שנתמכמך\u0004 (נמעך) \u0003ב\u0004תוך \u0003בנין\u0004 ערי המסכנות של פרעה והוצא משם בדרך נס. \u0003ומה שמו\u0004 האמיתי? — \u0003שבע בן בכרי שמו.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה ניבטו\u0004 (הביטו) \u0003ולא ראו\u0004 מה בדיוק יהיה, וטעו בעצמם, \u0003ואלו הן: נבט, ואחיתופל, ואיצטגניני פרעה.\u0004","ומפרטים: \u0003נבט ראה אש שיוצאת מאמתו\u0004 (אבר המין שלו), \u0003הוא סבר איהו מליך\u0004 \u0005[חשב\u0006 ש\u0005הוא ימלוך],\u0006 \u0003ולא היא\u0004 אלא \u0003ירבעם הוא דנפק מיניה\u0004 \u0005[שיצא ממנו]\u0006 ומלך.","\u0003אחיתופל ראה צרעת שזרחה לו על אמתו, הוא סבר איהו מלך\u0004 \u0005[חשב\u0006 ש\u0005הוא ימלוך],\u0006 \u0003ולא היא,\u0004 אלא \u0003בת שבע בתו,\u0004 בת בנו, \u0003הוא דנפקא מינה\u0004 \u0005[שיצא ממנה]\u0006 \u0003שלמה\u0004 המלך.","\u0003איצטגניני פרעה\u0004 — כפי ש\u0003אמר ר' חמא בר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"המה מי מריבה\"\u0004 (במדבר כ, יג) — \u0003המה\u0004 המים \u0003שראו איצטגניני פרעה וטעו\u0004 בהם. ומה היתה טעותם? — \u0003ראו\u0004 בכוכבים \u0003שמושיען של ישראל במים הוא לוקה,\u0004 ועל סמך זה \u0003אמר\u0004 פרעה \u0003\"כל הבן הילוד היארה תשליכהו\"\u0004 (שמות א, כב), שחשבו שבמים אלה תהיה מפלתו, \u0003והן לא ידעו\u0004 שלא בכך הוא נפגע אלא \u0003שעל עסקי מי מריבה לוקה,\u0004 שעל ידם נענש ולא נכנס לארץ.","ושוב לענין ירבעם: \u0003ומנא לן דלא אתי לעלמא דאתי\u0004 \u0005[ומנין לנו שאינו בא,\u0006 ירבעם, \u0005לעולם הבא]?\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי בדבר הזה לחטאת בית ירבעם ולהכחיד ולהשמיד מעל פני\u0004 ה\u0003אדמה\"\u0004 (מלכים א' יג, לד), \u0003\"להכחיד\"\u0004 — \u0003בעולם הזה, \"ולהשמיד\"\u0004 — \u0003לעולם הבא.\u0004","\u0003אמר ר' יוחנן: מפני מה זכה ירבעם למלכות?\u0004 — \u0003מפני שהוכיח את שלמה\u0004 על חטאיו. \u0003ומפני מה נענש\u0004 שנכשל בעבודה זרה ואיבד עולמו — \u0003מפני שהוכיחו ברבים\u0004 וביישו. \u0003שנאמר: \"וזה הדבר אשר הרים יד במלך שלמה בנה את המלוא סגר את פרץ עיר דוד אביו\"\u0004 (מלכים א' יא, כז) \u0003אמר לו\u0004 ירבעם לשלמה: \u0003דוד אביך פרץ פרצות בחומה כדי שיעלו ישראל לרגל, ואתה גדרת אותם כדי לעשות אנגריא\u0004 (לגבות מיסים) עבור \u0003בת פרעה!\u0004","\u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"וזה אשר הרים יד במלך\",\u0004 כיצד עשה? \u0003אמר רב נחמן: שחלץ תפיליו בפניו,\u0004 והעושה כן מראה שאיננו מתחשב במי שגדול ממנו. \u0003אמר רב נחמן: גסות הרוח\u0004 (גאוה) \u0003שהיה בו בירבעם טרדתו מן העולם\u0004 הבא. \u0003שנאמר: \"ויאמר ירבעם בלבו עתה תשוב הממלכה לבית דוד. אם יעלה העם הזה לעשות זבחים בבית ה' בירושל ם ושב לב העם הזה אל אדניהם אל רחבעם מלך יהודה והרגני ושבו אל רחבעם מלך יהודה\"\u0004 (מלכים א' יב, כו-כז),","\u0003אמר,\u0004 כלומר, כך יש לפרש את הדבר: \u0003גמירי\u0004 \u0005[למודים אנו]\u0006 ש\u0003אין ישיבה בעזרה אלא למלכי בית יהודה בלבד,\u0004 ולכן רק רחבעם יוכל לשבת בעזרה ולא אני. \u0003כיון דחזו ליה\u0004 \u0005[שיראו אותו]\u0006 את \u0003רחבעם דיתיב ואנא קאימנא\u0004 \u0005[ש\u0006הוא \u0005יושב ואני עומד],\u0006 \u0003סברי\u0004 \u0005[יחשבו]:\u0006 \u0003הא מלכא והא עבדא\u0004 \u0005[זה,\u0006 רחבעם, הוא \u0005המלך, וזה,\u0006 ירבעם, הוא \u0005העבד],\u0006 \u0003ואי יתיבנא\u0004 \u0005[ואם אשב]\u0006 שם — \u0003מורד במלכות הואי\u0004 \u0005[אהיה,\u0006 אחשב\u0005],\u0006 \u0003וקטלין לי\u0004 \u0005[ויהרגוני]\u0006 \u0003ואזלו בתריה\u0004 \u0005[וילכו אחריו].\u0006 \u0003מיד \"ויועץ המלך ויעש שני עגלי זהב ויאמר אלהם רב לכם מעלות ירושל ם הנה אלהיך ישראל אשר העלוך מארץ מצרים. וישם את האחד בבית אל ואת האחד נתן בדן\"\u0004 (מלכים א' כח–כט),","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ויועץ\u0004 המלך \u0003\"?\u0004 \u0003אמר רב יהודה: שהושיב רשע אצל צדיק\u0004 בין גדולי ישראל ונועץ בהם. \u0003אמר להו\u0004 \u0005[להם]\u0006 לזקני ישראל: האם \u0003חתמיתו\u0004 \u0005[חותמים אתם]\u0006 \u0003על כל\u0004 מה \u0003דעבידנא\u0004 \u0005[שאני עושה]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הין\u0004 \u0005[כן].\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מלכא בעינא למיהוי\u0004 \u0005[מלך רוצה אני להיות],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הין\u0004 \u0005[כן].\u0006 והוסיף לשאול: האם \u0003כל\u0004 מה \u0003דאמינא לכו עבידתו\u0004 \u0005[שאומר לכם תעשו]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הין\u0004 \u0005[כן].\u0006 אמר להם: \u0003אפילו למפלח\u0004 \u0005[לעבוד]\u0006 \u0003לעבודה זרה?\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003צדיק: חס וחלילה,\u0004 עבודה זרה איננו מקבלים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רשע לצדיק\u0004 היושב בצידו: האם \u0003סלקא דעתך דגברא\u0004 \u0005[עולה על דעתך שאדם]\u0006 \u0003כירבעם פלח\u0004 \u0005[יעבוד]\u0006 \u0003לעבודה זרה? אלא למינסינהו\u0004 \u0005[לנסות אותם]\u0006 \u0003הוא דקא בעי\u0004 \u0005[שרצה],\u0006 לדעת \u0003אי קבליתו למימריה\u0004 \u0005[אם יקבלו את דבריו],\u0006 ולשון הפלגה היא ואין כוונתו לכך כלל,"],["\u0003ואף אחיה השילוני טעה\u0004 באותו דבר \u0003וחתם\u0004 שמקבל על עצמו כל שיאמר ירבעם, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003יהוא צדיקא רבה הוה\u0004 \u0005[צדיק גדול היה],\u0006 \u0003שנאמר: \"ויאמר ה' אל יהוא יען אשר הטיבת לעשות הישר בעיני ככל אשר בלבבי עשית לבית אחאב בני רבעים ישבו לך על כסא ישראל\"\u0004 (מלכים ב' י, ל), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהוא לא שמר ללכת בתורת ה' אלהי ישראל בכל לבבו לא סר מעל חטאות ירבעם אשר החטיא את ישראל\"\u0004 (מלכים ב' י, לא),","\u0003מאי גרמא ליה\u0004 \u0005[מה גרם לו]\u0006 לעשות כן? \u0003אמר אביי: ברית כרותה לשפתים, שנאמר\u0004 שאמר יהוא בערמה: \u0003\"אחאב עבד את הבעל מעט יהוא יעבדנו הרבה\"\u0004 (מלכים ב' י, יח), וכיון שהוציא דבר זה מפיו גרם לו שנגרר אחרי הדברים ועשאם. \u0003רבא אמר: חותמו של אחיה השילוני ראה\u0004 על המלכת ירבעם, \u0003וטעה\u0004 וחשב שהדבר מותר.","ועוד בענין ירבעם. על מה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושחטה שטים העמיקו ואני מוסר לכלם\"\u0004 (הושע ה, ב), \u0003אמר ר' יוחנן, אמר הקדוש ברוך הוא: הם העמיקו\u0004 והחמירו מגזירותי \u0003שלי.\u0004 ש\u0003אני אמרתי: כל שאינו עולה לרגל\u0004 — \u0003עובר בעשה, והם אמרו: כל העולה לרגל ידקר בחרב,\u0004 וכך הצליח ירבעם למנוע את ישראל מלעלות לרגל.","ושוב בדברי רב: נאמר \u0003\"ויהי בעת ההיא וירבעם יצא מירושל ם וימצא אתו אחיה השילני הנביא בדרך והוא מתכסה בשלמה חדשה\"\u0004 (מלכים א' יא, כט). \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003משום\u0004 (בשם) \u0003ר' יוסי:\u0004 \"בעת ההיא\", כוונתו: \u0003עת היא מזומנת לפורענות.\u0004","וכן על הנאמר \u0003\"בעת פקדתם יאבדו\"\u0004 (ירמיה נא, יח), \u0003תנא משום ר' יוסי: עת\u0004 היא \u0003מזומנת לפורענות.\u0004 וכיוצא בו מה שנאמר: \u0003\"בעת רצון עניתיך\"\u0004 (ישעיה מט, ח), \u0003תנא משום ר' יוסי:\u0004 יש \u0003עת\u0004 שהיא \u0003מזומנת לטובה.\u0004 וכן על הנאמר \u0003\"וביום פקדי ופקדתי עלהם חטאתם\"\u0004 (שמות לב, לד), \u0003תנא משום ר' יוסי: עת היא מזומנת לפורענות.\u0004 וכן \u0003\"ויהי בעת ההיא וירד יהודה מאת אחיו\"\u0004 (בראשית לח, א), \u0003תנא משום ר' יוסי: עת\u0004 היא \u0003מזומנת לפורענות.\u0004","ועוד בירבעם, נאמר: \u0003\"וילך רחבעם שכם כי שכם בא כל ישראל להמליך אתו\"\u0004 (מלכים א' יב, א) \u0003תנא משום\u0004 \u0003ר' יוסי:\u0004 שכם הוא \u0003מקום מזומן לפורענות; בשכם עינו את דינה, ב\u0004סביבות העיר \u0003שכם מכרו אחיו את יוסף, בשכם נחלקה מלכות בית דוד.\u0004","ועל הנאמר \u0003\"וירבעם יצא מירושל ם\"\u0004 (מלכים א' יא, כט), \u0003אמר ר' חנינא בר פפא: שיצא מפיתקה של ירושלים,\u0004 כלומר, הוציא את עצמו מכלל יושבי ירושלים ודריה, שלא לחזור לשם לעולם.","נאמר שם: \u0003\"וימצא אתו אחיה השילוני הנביא בדרך והוא מתכסה בשלמה חדשה ושניהם לבדם בשדה\"\u0004 (מלכים א' יא, כט) \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005],\u0006 ומה מלמדנו האמור \u0003\"בשלמה חדשה\"? אמר רב נחמן: כשלמה חדשה, מה שלמה חדשה אין בה שום דופי\u0004 (פגם) — \u0003אף תורתו של ירבעם לא היה בה\u0004 אז \u0003שום דופי. דבר אחר: \"שלמה חדשה\"\u0004 — \u0003שחידשו דברים שלא שמעה אזן מעולם.\u0004","\u0003מאי\u0004 \u0005[מה]\u0006 מלמדנו האמור \u0003\"ושניהם לבדם בשדה\"? אמר רב יהודה אמר רב: שכל תלמידי חכמים\u0004 שבדור \u0003דומין לפניהם כעשבי השדה,\u0004 ששניהם היו למעלה מכולם בחכמה. \u0003ואיכא דאמר\u0004 \u0005[ויש\u0006 מי \u0005שאומר]\u0006 ופירש: \u0003שכל טעמי תורה מגולין להם כשדה.\u0004","על הנאמר: \u0003\"לכן תתני שלוחים על מורשת גת בתי אכזיב לאכזב למלכי ישראל\"\u0004 (מיכה א, יד), \u0003אמר ר' חנינא בר פפא:\u0004 כשהמליכו את ירבעם \u0003יצאה בת קול ואמרה להן\u0004 לישראל: ד\u0003מי שהרג את הפלשתי והוריש אתכם גת,\u0004 כלומר, דוד המלך, \u0003תתנו שילוחים לבניו\u0004 ותמרדו בהם? סופכם כי \u0003\"בתי אכזיב לאכזב למלכי ישראל\",\u0004 שאף מלכי ישראל יוכזבו על ידי נתיניהם שכולם לא יהיו נאמנים להם.","\u0003אמר רב חיננא בר פפא: כל הנהנה מן העולם הזה בלא ברכה\u0004 הריהו \u0003כאילו גוזל\u0004 גם את \u0003הקדוש ברוך הוא\u0004 שהכל שלו, וגם את \u0003כנסת ישראל,\u0004 שהוא מביא עליה קללה אם אינו מברך. ורמז לדבר — \u0003שנאמר: \"גוזל אביו ואמו ואמר אין פושע חבר הוא לאיש משחית\"\u0004 (משלי כח, כד), \u0003ואין \"אביו\" אלא הקדוש ברוך הוא, שנאמר: \"הלא הוא אביך קנך\"\u0004 (דברים לב, ו), \u0003ואין \"אמו\" אלא כנסת ישראל, שנאמר: \"שמע בני מוסר אביך ואל תטש תורת אמך\"\u0004 (משלי א, ח), שמשמע שתורת האם היא המסורת המקובלת בישראל.","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חבר הוא לאיש משחית\"\u0004 — \u0003חבר הוא לירבעם בן נבט, שהשחית\u0004 את \u0003ישראל לאביהם שבשמים.\u0004","על הנאמר \u0003\"וידח ירבעם בן נבט את ישראל מאחרי ה' והחטיאם חטאה גדולה\"\u0004 (מלכים ב' יז, כא), \u0003אמר רבי חנין: כשתי מקלות המתיזות\u0004 (זורקות) \u0003זו את זו,\u0004 שמתוך הריב שנוצר על ידי כך גרר ירבעם את ישראל מאחרי ה'.","אגב הזכרת עגלי ירבעם מזכירים את העגל הראשון, על הנאמר: \u0003\"ודי זהב\"\u0004 (דברים א, א), \u0003אמרו דבי\u0004 \u0005[\u0006חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: אמר משה לפני הקדוש ברוך הוא: רבונו של עולם, בשביל כסף וזהב שהשפעת להן לישראל\u0004 כה הרבה, \u0003עד שיאמרו דיי\u0004 לנו — הוא ש\u0003גרם להם לעשות להם אלהי זהב\u0004 מפני השפע והבטלה, שהיתה דעתם לדברים כאלה. ו\u0003משל\u0004 לדבר: \u0003אין ארי דורס ונוהם מתוך קופה\u0004 (סל) \u0003של תבן, אלא מתוך קופה של בשר,\u0004 ואם כן לא רק הם אשמים בכך.","\u0003אמר ר' אושעיא: עד ירבעם היו ישראל יונקים,\u0004 כלומר, סובלים על חטאתם \u0003מעגל אחד\u0004 שעשו במדבר, \u0003מכאן ואילך משנים ושלשה עגלים\u0004 שהוסיף ירבעם בישראל. \u0003אמר ר' יצחק: אין לך כל פורענות ופורענות שבאה לעולם שאין בה אחד מעשרים וארבעה בהכרע ליטרא של עגל הראשון,\u0004 שבתוך המשקל היו מוסיפים דבר קטן כדי להכריע את כף המאזניים, ואחד מעשרים וארבע בהכרע ליטרא הוא דבר קטן מאוד, וכוונתו, שחלק קטן מזעיר מחטא עגל הראשון נזכר בכל חטאי ישראל, \u0003ש\u0004כן \u0003נאמר: \"וביום פקדי ופקדתי עלהם חטאתם\"\u0004 (שמות לב, לד), שחטא זה לא נמחל, אלא נפרע מישראל בכל דור.","\u0003אמר ר' חנינא: לאחר עשרים וארבעה דורות\u0004 מאז חטא העגל \u0003נגבה פסוק זה, שנאמר: \"ויקרא באזני קול גדול לאמר קרבו פקדות העיר ואיש כלי משחתו בידו\"\u0004 (יחזקאל ט, א), שמאז חטא העגל עד גלות בבל היו עשרים וארבעה דורות.","נאמר בירבעם \u0003\"אחר הדבר הזה לא שב ירבעם מדרכו הרעה\"\u0004 (מלכים א' יג, לג) \u0003מאי\u0004 \u0005[מהי]\u0006 משמעות \u0003\"אחר\"\u0004 שנאמר? מהו אותו מאורע שמרומז לו? \u0003אמר ר' אבא: אחר שתפשו הקדוש ברוך הוא לירבעם בבגדו\u0004 כלומר, ששלח נביאים והפציר בו, \u0003ואמר לו: חזור בך, ו\u0004אז \u0003אני ואתה ובן ישי נטייל בגן עדן. אמר לו: מי\u0004 יהיה \u0003בראש?\u0004 אמר לו ה': \u0003בן ישי\u0004 ילך \u0003בראש.\u0004 אמר ירבעם: \u0003אי הכי, לא בעינא\u0004 \u0005[אם\u0006 \u0005כך, אין אני רוצה],\u0006 שמפני גאוותו לא רצה לחזור בו.","מסופר: \u0003ר' אבהו הוה\u0004 \u0005[היה]\u0006 \u0003רגיל דהוה קא דריש\u0004 \u0005[לדרוש],\u0006 ולהאריך בדרשה על המשנה \u0003בשלשה מלכים\u0004 שאין להם חלק לעולם הבא. \u0003חלש, קביל עליה\u0004 \u0005[נחלש,\u0006 חלה, ו\u0005קיבל על עצמו]\u0006 ש\u0003לא\u0004 \u0003דריש\u0004 \u0005[ידרוש]\u0006 עוד במשנה זו. \u0003כיון\u0004"],["\u0003כ\u0004\u0003דאיתפח, הדר קא דריש\u0004 \u0005[שהבריא, חזר, ודרש].\u0006 \u0003אמרי\u0004 \u0005[אמרו]\u0006 לו תלמידיו: וכי \u0003לא קבילת עלך\u0004 \u0005[קיבלת עליך]\u0006 ש\u0003לא דרשת בהו?\u0004 \u0005[תדרוש בהם]?\u0006 \u0003אמר: אינהו מי הדרו בהו, דאנא אהדר בי?\u0004 \u0005[\u0006ו\u0005הם, האם חזרו בהם\u0006 בתשובה, \u0005שאני אחזור בי\u0006 מלדרוש בגנותם\u0005]?\u0006","\u0003רב אשי אוקי\u0004 \u0005[עמד,\u0006 הפסיק\u0005]\u0006 בלמודיו יום אחד סמוך לענין \u0003שלשה מלכים,\u0004 \u0003אמר\u0004 לתלמידים: \u0003למחר נפתח\u0004 את הלימוד \u0003בחברין\u0004 \u0005[בחברינו],\u0006 כלומר, ששלושה מלכים אלו, אף על פי שרשעים היו, מכל מקום היו תלמידי חכמים והם כחברים בהלכה. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003מנשה\u0004 מלך יהודה \u0003איתחזי ליה בחלמיה\u0004 \u0005[\u0006ו\u0005נראה לו בחלומו].\u0006 \u0003אמר\u0004 לו מנשה בכעס: \u0003חברך וחבירי דאבוך קרית לן\u0004 \u0005[חבריך וחברי אביך קורא אתה לנו]!\u0006 כיצד עושה אתה עצמך חבר לנו?!","הנה אשאלך \u0003מהיכא בעית למישרא\u0004 \u0005[מהיכן,\u0006 מאיזה מקום בככר הלחם \u0005צריך אתה לפתוח,\u0006 לחתוך\u0005]\u0006 לפני ברכת \u0003\"המוציא\"?\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003לא ידענא\u0004 \u0005[אין אני יודע].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מנשה: \u0003מהיכא דבעית למישרא\u0004 \u0005[מהיכן שצריך אתה לפתוח]\u0006 לברכת \u0003\"המוציא\" לא גמירת\u0004 \u0005[למדת],\u0006 \u0003ו\"חברך\" קרית לן\u0004 \u0005[ו\"חבריך\" אתה קורא לנו]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי למנשה: \u0003אגמריה\u0004 \u0005[למד]\u0006 \u0003לי\u0004 את הדבר, \u0003ולמחר דרישנא ליה משמך בפירקא\u0004 \u0005[אדרוש אותו בשמך בדרשה\u0006 הפומבית\u0005]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מנשה: \u0003מהיכא דקרים בישולא\u0004 \u0005[מהיכן שהקרים והתבשל\u0006 יפה הלחם\u0005]\u0006 משם חותכים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003מאחר דחכימתו כולי האי\u0004 \u0005[שהייתם חכמים כל כך],\u0006 \u0003מאי טעמא קא פלחיתו\u0004 \u0005[מה טעם\u0006 אם כן \u0005עבדתם]\u0006 \u0003לעבודה זרה?\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מנשה: \u0003אי הות התם הות נקיטנא בשיפולי גלימא ורהטת אבתראי\u0004 \u0005[אילו היית שם\u0006 באותם הדורות \u0005היית אוחז בשיפולי הגלימה\u0006 שלך, מגביהה \u0005ורץ אחרי]\u0006 מרוב תשוקתך, שבאותם דורות היתה זו תאוה עזה, ואמונה מקובלת. \u0003למחר אמר להו לרבנן\u0004 \u0005[להם\u0006 רב אשי \u0005לחכמים]\u0006 לפני שפתח בדרשה: \u0003נפתח ברבוותא\u0004 \u0005[ברבותינו],\u0006 באותם מלכים שהיו גדולים מאתנו בתורה ומפני חטאיהם אין להם חלק לעולם הבא.","ומעתה לענין המלך אחאב. את שמו הפרטי דורשים כך: \u0003\"אחאב\"\u0004 — שאמנם היה \u0003אח לשמים,\u0004 אבל \u0003אב לעבודה זרה. אח לשמים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ו\u0003אח לצרה יולד\"\u0004 (משלי יז, יז), שבעתות צרה נעשה אח לשמים (מהרש\"א). \u0003אב לעבודה זרה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כרחם אב על בנים\"\u0004 (תהלים קג, יג).","נאמר באחאב: \u0003\"ויהי הנקל לכתו בחטאות ירבעם בן נבט\"\u0004 (מלכים א' טז, לא), מכאן \u0003אמר ר' יוחנן:\u0004 עבירות \u0003קלות שעשה אחאב\u0004 היו \u0003כ\u0004עבירות \u0003חמורות שעשה ירבעם,\u0004 שחמורות יותר היו חטאות אחאב משל ירבעם. \u0003ומפני מה תלה הכתוב\u0004 בכל מקום בחטאי מלכי ישראל \u0003בירבעם\u0004 אף שכאמור אחאב הרשיע יותר — \u0003מפני שהוא,\u0004 ירבעם, \u0003היה תחילה לקלקלה.\u0004 על הנאמר: \u0003\"גם מזבחותם כגלים על תלמי שדי\"\u0004 (הושע יב, יב), \u0003אמר ר' יוחנן: אין לך כל תלם ותלם בארץ ישראל שלא העמיד עליו אחאב עבודה זרה והשתחוה לה.\u0004","ושואלים: \u0003ומנא לן\u0004 \u0005[ומנין לנו]\u0006 ש\u0003לא אתי לעלמא דאתי\u0004 \u0005[בא\u0006 אחאב \u0005לעולם הבא]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"והכרתי לאחאב משתין בקיר ועצור ועזוב בישראל\"\u0004 (מלכים א' כא, כא), והכפילות נדרשת כך: \u0003\"עצור\"\u0004 — \u0003בעולם הזה, \"ועזוב\"\u0004 — \u0003לעולם הבא.\u0004","\u0003אמר ר' יוחנן: מפני מה זכה עמרי\u0004 מלך ישראל \u0003למלכות\u0004 — \u0003מפני שהוסיף כרך אחד בארץ ישראל, שנאמר: \"ויקן את ההר שמרון מאת שמר בככרים כסף ויבן את ההר ויקרא את שם העיר אשר בנה על שם שמר אדני ההר שמרון\"\u0004 (מלכים א' טז, כד).","\u0003אמר ר' יוחנן: מפני מה זכה אחאב למלכות עשרים ושתים שנה\u0004 —","\u0003מפני שכיבד את התורה, שניתנה בעשרים ושתים אותיות,\u0004 וכיצד רואים שכיבד את התורה — \u0003שנאמר: \"וישלח מלאכים אל אחאב מלך ישראל העירה. ויאמר לו כה אמר בן הדד כספך וזהבך לי הוא ונשיך ובניך הטובים לי הם... כי אם כעת מחר אשלח את עבדי אליך וחפשו את ביתך ואת בתי עבדיך והיה כל מחמד עיניך ישימו בידם ולקחו... ויאמר למלאכי בן הדד\u0004 \u0003אמרו לאדני המלך כל אשר שלחת אל עבדך בראשונה אעשה והדבר הזה לא אוכל לעשות\"\u0004 (מלכים א' כ, ב-ג. מלכים א' כ, ו. מלכים א' כ,ס ט).","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 אותו \u0003\"מחמד עיניך\"\u0004 שלא רצה לתת לבן הדד אחר שכבר הסכים לתת את נשיו וזהבו, \u0003לאו\u0004 \u0005[האם לא]\u0006 היה זה \u0003ספר תורה?\u0004 ואם כן רואים אנו שהיה מוכן לוותר על הכל, אבל לא לתת את ספר התורה לגויים ובשל כך נמשכה מלכותו.","ושואלים: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003עבודה זרה\u0004 היא מחמד עיניו? ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כך, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 ששאל אחאב בענין זה את הזקנים, \u0003\"ויאמרו אליו כל הזקנים וכל העם אל תשמע ולוא \"תאבה\"\u0004 (מלכים א' כ, ח), ו\"זקנים\" משמע כרגיל חכמים. ועוד ממשיכים בשאלה: \u0003ודילמא סבי דבהתא הוו\u0004 \u0005[ושמא זקני תוהו,\u0006 רשעים, \u0005היו]\u0006 ועובדי עבודה זרה? וראיה לדבר — \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ויישר הדבר בעיני אבשלם ובעיני כל זקני ישראל\"\u0004 (שמואל ב' יז, ד), \u0003ואמר רב יוסף:\u0004 אותם \"זקני ישראל\" המוזכרים בפסוק היו \u0003סבי דבהתא\u0004 \u0005[זקני תוהו],\u0006 הרי שייתכן שזקני ישראל יהיו רשעים.","ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 באבשלום \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וכל העם\", הכא כתיב\u0004 \u0005[כאן נאמר]\u0006 \u0003\"וכל העם\",\u0004 ש\u0003אי אפשר\u0004 ש\u0003לא הוו בהון צדיקי\u0004 \u0005[היו בהם צדיקים]\u0006 ואם גם הצדיקים הסכימו לכך — ראיה היא שדבר קדושה היה זה. שהרי \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"והשארתי בישראל שבעת אלפים כל הברכים אשר לא כרעו לבעל וכל הפה אשר לא נשק לו\"\u0004 (מלכים א' יט, יח).","\u0003אמר רב נחמן: אחאב\u0004 עצמו \u0003שקול היה\u0004 בין טוב ורע, \u0003שנאמר: \"ויאמר ה' מי יפתה את אחאב ויעל ויפל ברמת גלעד ויאמר זה בכה וזה אמר בכה\"\u0004 (מלכים א' כב, כ) ולא היה ברור שהוא רשע גמור. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: מאן דכתב ביה\u0004 \u0005[מי שנכתב בו]\u0006 \u0003\"רק לא היה כאחאב אשר התמכר לעשות הרע בעיני ה' אשר הסתה אתו איזבל אשתו\"\u0004 (מלכים א' כא, כה), \u0003ותנינא\u0004 \u0005[ושנינו]\u0006 על כך: \u0003בכל יום היתה שוקלת שקלי זהב\u0004 במשקלו \u0003לעבודה זרה, ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003שקול היה?! אלא, אחאב וותרן בממונו היה\u0004 שלא הקפיד ולא קימץ, \u0003ומתוך ש\u0004גם \u0003ההנה תלמידי חכמים מנכסיו כיפרו לו מחצה\u0004 מעוונותיו.","ואגב הזכרת הכתוב מביאים את המשכו: \u0003\"ויצא הרוח ויעמד לפני ה' ויאמר אני אפתנו ויאמר ה' אליו במה. ויאמר אצא והייתי רוח שקר בפי כל נביאיו ויאמר תפתה וגם תוכל צא ועשה כן\"\u0004 (מלכים א' כב, כא-כב). ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 אותו \u0003רוח? אמר ר' יוחנן: רוחו של נבות היזרעאלי\u0004 שרצה להינקם מאחאב.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"צא\"\u0004 שאמר ה' לרוח? \u0003אמר רבינא,\u0004 כוונתו: \u0003צא ממחיצתי\u0004 ושוב אל תהיה כאן, \u0003שכן כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"דבר שקרים לא יכון לנגד עיני\"\u0004 (תהלים קא, ז), ואינו ראוי להיות עוד לפני ה'. \u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי: \u0003\"דפרע קיניה\u0004 \u0005[\u0006מי \u0005שפורע,\u0006 נוקם, \u0005את קנאתו]\u0006 — הריהו בסופו של דבר \u0003מחריב ביתיה\u0004 \u0005[\u0006את \u0005ביתו\u0006 שלו\u0005]\u0006 וכן אירע ברוח נבות שנדחה ממחיצת ה'.","על הנאמר \u0003\"ויעש אחאב את האשרה ויוסף אחאב לעשות להכעיס את ה' אלהי ישראל מכל מלכי ישראל אשר היו לפניו\"\u0004 (מלכים א' טז, לג), \u0003אמר ר' יוחנן: שכתב על דלתות שמרון \"אחאב כפר באלהי ישראל\", לפיכך אין לו חלק באלהי ישראל.\u0004","על הנאמר \u0003\"ויבקש את אחזיהו וילכדהו והוא מתחבא בשמרון\"\u0004 (דברי הימים ב' כב, ט), \u0003אמר ר' לוי:\u0004 מה היה עושה בהחבא? — \u0003היה קודר\u0004 (חותך ומוציא) את \u0003אזכרות\u0004 שם ה' הכתובות בספרי התורה \u0003וכותב\u0004 שם \u0003עבודה זרה תחתיהן.\u0004","מעתה מדברים מענין \u0003מנשה.\u0004 מדוע נקרא כן — מפני \u0003שנשה\u0004 (שכח) \u0003יה. דבר אחר: מנשה\u0004 — \u0003שהנשי\u0004 (השכיח) \u0003את ישראל לאביהם שבשמים. ומנלן\u0004 \u0005[ומנין לנו]\u0006 שהוא \u0003לא אתי לעלמא דאתי\u0004 \u0005[בא לעולם הבא]?\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בן שתים עשרה שנה מנשה במלכו וחמשים וחמש שנה מלך בירושל ם... ויעש אשרה כאשר עשה אחאב מלך ישראל\"\u0004 (מלכים ב' כא, א. מלכים ב' כא ג), ונלמד מכאן: \u0003מה אחאב אין לו חלק לעולם הבא\u0004 — \u0003אף מנשה אין לו חלק לעולם הבא.\u0004","שנינו במשנה ש\u0003ר' יהודה אומר: מנשה יש לו חלק לעולם הבא, שנאמר: \"ויתפלל אליו ויעתר לו\u0004 וישמע תחנתו וישיבהו ירושלים למלכותו\u0003\"\u0004 (דברי הימים ב' לג, יג). \u0003אמר ר' יוחנן: ושניהם,\u0004 ר' יהודה וחכמים החולקים עליו ולדעתם אין למנשה חלק לעולם הבא, \u0003מקרא אחד דרשו. שנאמר: \"ונתתים לזעוה לכל ממלכות הארץ בגלל מנשה בן יחזקיהו\"\u0004 (ירמיה טו, ד) \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003\"בגלל מנשה\"\u0004 — שלבסוף \u0003עשה תשובה, ואינהו\u0004 \u0005[והם]\u0006 \u0003לא עבוד\u0004 \u0005[עשו]\u0006 והוא גנאי לישראל שאף רשע גמור כמנשה יכול לעשות תשובה והם אינם עושים. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבורים]:\u0006"],["\u0003\"בגלל מנשה\"\u0004 — ש\u0003לא עבד\u0004 \u0005[עשה]\u0006 \u0003תשובה.\u0004","\u0003אמר ר' יוחנן: כל האומר מנשה אין לו חלק לעולם הבא\u0004 בכך הוא \u0003מרפה\u0004 את \u0003ידיהן של בעלי תשובה,\u0004 שנראה מכאן שיש מקרים שאין אדם יכול לחזור בו. \u0003דתני תנא קמיה\u0004 \u0005[ששנה חוזר המשניות לפני]\u0006 \u0003ר' יוחנן: מנשה עשה תשובה לשלשים ושלש שנים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בן שתים עשרה שנה מנשה במלכו וחמשים וחמש שנה מלך בירושל ם... ויעש הרע... ויעש אשרה כאשר עשה אחאב מלך ישראל\"\u0004 (מלכים ב' כא, א–ג). \u0003כמה\u0004 שנים \u0003מלך אחאב?\u0004 — \u0003עשרין ותרתין שנין\u0004 \u0005[עשרים ושתים שנה],\u0006 \u0003מנשה כמה מלך?\u0004 — \u0003חמשים וחמש. דל מינייהו עשרים ותרתין\u0004 \u0005[הוצא מהן עשרים ושתים\u0006 שנים\u0005]\u0006 שעשה את הרע כמעשה אחאב, אם כן \u0003פשו להו תלתין ותלת\u0004 \u0005[נשארו להן שלושים ושלוש\u0006 שנים\u0005]\u0006 שבהן עשה תשובה.","\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"וישמע אליו ויחתר לו\",\u0004 והלא \u0003\"ויעתר לו\"\u0004 (דברי הימים ב' לג, יג) \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לכתוב\u0005]!\u0006 אלא כתוב זה \u0003מלמד שעשה לו הקדוש ברוך הוא כמין מחתרת ברקיע, כדי לקבלו בתשובה, מפני מדת הדין\u0004 שעכבה ואמרה שאין לו תקנה.","\u0003ואמר ר' יוחנן משום ר' שמעון בן יוחי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"בראשית ממלכות יהויקים בן יאשיהו\"\u0004 (ירמיה כו, א), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"בראשית ממלכת צדקיה\"\u0004 (ירמיה כח, א), \u0003וכי עד האידנא\u0004 \u0005[עכשיו]\u0006 \u0003לא הוו מלכי\u0004 \u0005[היו מלכים]?\u0006 ומה היא לשון \"בראשית\" האמורה דווקא בהם מבשאר מלכים? היה לו לומר \"בשנה ראשונה\" וכדומה!","\u0003אלא בקש הקדוש ברוך הוא להחזיר את העולם כולו לתוהו ובוהו בשביל יהויקים\u0004 הרשע, \u0003נסתכל בדורו ונתקררה דעתו,\u0004 שהיה מרוצה מן הצדיקים שבאותו דור, ולכן נאמרה המלה \"בראשית\", לומר שבימיו היתה כבריאה חדשה מן התוהו.","וכן \u0003בקש הקדוש ברוך הוא להחזיר את העולם כולו לתוהו ובוהו בשביל דורו של צדקיה\u0004 שהיו כולם רשעים, \u0003נסתכל בצדקיה ונתקררה דעתו.\u0004 ושואלים: והלא \u0003בצדקיה נמי כתיב\u0004 \u0005[גם כן נאמר]\u0006 \u0003\"ויעש הרע בעיני ה' \"\u0004(מלכים ב' כד, יט)! ומשיבים: לא שהיה רשע, אלא \u0003שהיה בידו למחות\u0004 בבני דורו \u0003ולא מיחה\u0004 כראוי, על כן נקרא על שמו.","\u0003ו\u0004עוד \u0003אמר ר' יוחנן משום ר' שמעון בן יוחי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"איש חכם נשפט את איש אויל ורגז ושחק ואין נחת\"\u0004 (משלי כט, ט) — \u0003אמר הקדוש ברוך הוא: כעסתי על אחז ונתתיו ביד מלכי דמשק,\u0004 מה עשה? \u0003זיבח וקיטר לאלהיהם, שנאמר: \"ויזבח לאלהי דרמשק המכים בו ויאמר כי אלהי מלכי ארם הם מעזרים אתם להם אזבח ויעזרוני והם היו לו להכשילו ולכל ישראל\"\u0004 (דברי הימים ב' כח, כג), הרי שכאשר כעס הקדוש ברוך הוא על ישראל והכשילם במלחמה, הלכו ועבדו עבודה זרה.","\u0003שחקתי עם אמציה ונתתי מלכי אדום בידו\u0004 — \u0003הביא אלהיהם והשתחוה להם, שנאמר: \"ויהי אחרי בוא אמציהו מהכות את אדומים ויבא את אלהי בני שעיר ויעמידם לו לאלהים ולפניהם ישתחוה ולהם יקטר\"\u0004 (דברי הימים ב' כח, כג), הרי שכאשר כעס הקדוש ברוך הוא על ישראל (דברי הימים ב' כה, יד), שאף בשעת הצלחה עובדים עבודה זרה, ואם כן אין להם תקנה. \u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי לגבי תוכחה לאויל: \u0003\"בכיי ליה למר\u0004 \u0005[בכיתי לו לאדוני]\u0006 ו\u0003לא ידע, חייכי למר\u0004 \u0005[צחקתי לאדוני]\u0006 ו\u0003לא ידע,\u0004 \u0003ווי ליה למר דלא ידע בין טב לביש\u0004 \u0005[אוי לו לאדוני שאינו יודע בין טוב לרע]\u0006\u0003\".\u0004 וכך הם ישראל, בין כשמיטיב ה' להם בין כשמרע להם — עובדים הם עבודה זרה.","על הנאמר: \u0003\"ויבאו כל שרי מלך בבל וישבו בשער התוך\"\u0004 (ירמיה לט, ג), \u0003אמר ר' יוחנן משום ר' שמעון בן יוחי:\u0004 \"שער התוך\" היה \u0003מקום שמחתכין בו הלכות,\u0004 שדרש בחילוף ה' ו־ח' — \"התוך\" כמו חתוך. \u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 כפתגם עממי: \u0003\"באתרא דמריה תלא ליה זייניה, תמן קולבא רעיא קולתיה תלא\"\u0004 \u0005[במקום שבעל הבית תולה שם\u0006 את \u0005כלי זינו, שם הרועה הבזוי תולה\u0006 את \u0005כדו],\u0006 שבמקום סנהדרין ישב נבוכדנצר הרשע.","\u0003(סימן\u0004 לדברים האמורים להלן: \u0003על שדה בתים לא תאונה).\u0004","\u0003אמר רב חסדא אמר ר' ירמיה בר אבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"על שדה איש עצל עברתי ועל כרם אדם חסר לב. והנה עלה כלו קמשונים כסו פניו חרלים וגדר אבניו נהרסה\"\u0004 (משלי כד, ל–לא) — המדובר הוא בירידתם הרוחנית והמדינית של מלכי יהודה, \u0003\"על שדה איש עצל עברתי\"\u0004 — \u0003זה אחז. \"ועל כרם אדם חסר לב\"\u0004 — \u0003זה מנשה. \"והנה עלה כלו קמשונים\"\u0004 — \u0003זה אמון. \"כסו פניו חרלים\"\u0004 — \u0003זה יהויקים. \"וגדר אבניו נהרסה\"\u0004 — \u0003זה צדקיהו, שנחרב בית המקדש בימיו.\u0004 וכיון שהוזכר מאמר של רב חסדא בשם ר' ירמיה מביאים עוד מאמר כזה.","\u0003ואמר רב חסדא אמר ר' ירמיה בר אבא: ארבע כיתות\u0004 של בני אדם \u0003אין מקבלות פני שכינה: כת לצים, כת שקרנים, כת חניפים, כת מספרי לשון הרע. כת לצים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"משך ידו את לצצים\"\u0004 (הושע ז, ה), משמע שה' מושך ידו מהם. \u0003כת שקרנים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"דבר שקרים לא יכון לנגד עיני\"\u0004 (תהלים קא, ז). \u0003כת חניפים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לא לפניו חנף יבוא\"\u0004 (איוב יג, טז). \u0003כת מספרי לשון הרע\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לא אל חפץ רשע אתה לא יגרך רע\"\u0004 (תהלים ה, ה), משמע: \u0003צדיק אתה, ולא יהיה במגורך\u0004 דבר של \u0003רע. ו\u0004עוד","\u0003אמר רב חסדא אמר ר' ירמיה בר אבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"לא תאנה אליך רעה ונגע לא יקרב באהלך\"\u0004 (תהלים צא, י), יש לפרש ולומר: \u0003\"לא תאנה אליך רעה\"\u0004 — \u0003שלא ישלוט בהן יצר הרע. \"ונגע לא יקרב באהלך\"\u0004 — \u0003שלא תמצא אשתך ספק נדה בשעה שתבא מן הדרך,\u0004 שאז אדם משתוקק לאשתו, וכיון שהיא ספק נדה מצטער יותר מכאשר ידוע לו שהיא נדה ודאית, שהרי אינו יודע אם באמת חייב הוא לפרוש ממנה.","\u0003דבר אחר: \"לא תאנה אליך רעה\"\u0004 — \u0003שלא יבעתוך חלומות רעים והרהורים רעים. \"ונגע לא יקרב באהלך\"\u0004 — \u0003שלא יהא לך בן או תלמיד שמקדיח תבשילו ברבים,\u0004 כלומר, שמקלקל דמעשיו, \u0003כגון ישו הנוצרי.\u0004","\u0003עד כאן ברכו\u0004 דוד \u0003אביו\u0004 לשלמה בברכות הנוגעות והמתאימות לברכת אב, \u0003מכאן ואילך ברכתו אמו,\u0004 כי הברכות הן כעין ברכת אם לעניינים שהאם מודאגת עליו: \u0003\"כי מלאכיו יצוה לך לשמרך בכל דרכיך. על כפים ישאונך\u0004 פן תגוף באבן רגלך \u0003על שחל ופתן תדרך\u0004 תרמוס כפיר ותנין","\u0003\"\u0004(תהלים צא, יג–יד), \u0003עד כאן ברכתו אמו, מכאן ואילך ברכתו שמים,\u0004 שעובר לדבר על ה' בגוף ראשון כמדבר בעדו:"],["\u0003\"כי בי חשק ואפלטהו אשגבהו כי ידע שמי. יקראני ואענהו עמו אנכי בצרה אחלצהו ואכבדהו. ארך ימים אשביעהו ואראהו בישועתי\"\u0004 (תהלים צא, יד —טז).","\u0003אמר ר' שמעון בן לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"וימנע מרשעים אורם וזרוע רמה תשבר\"\u0004 (איוב לח, טו)? — \u0003מפני מה\u0004 האות \u0003עי\"ן של\u0004 המלה \u0003\"רשעים\" תלויה\u0004 וכתובה קצת מעל לשורה? — ללמד שצריכים לקרוא כאילו היה כתוב \"רשים\", לומר: \u0003כיון שנעשה אדם רש מלמטה\u0004 שמתרבים שונאיו למטה — \u0003נעשה רש\u0004 גם \u0003מלמעלה,\u0004 שבוודאי אדם חוטא הוא ולכן הוא שנוא.","ושואלים: אם כך הוא הפירוש, \u0003ו\u0004ש\u0003לא נכתביה\u0004 \u0005[יכתבו]\u0006 \u0003כלל\u0004 את האות ע', ויכתב בפירוש \"רשים\"! \u0003ר' יוחנן ור' אלעזר\u0004 השיבו על כך שיש צורך לרמוז ש\"רשים\" (שנואים) אלה הם גם רשעים ממש, כי לעתים יש צדיקים הנשנאים חנם. \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מפני כבודו של דוד,\u0004 שאף שהיו לו שונאים מרובים למטה, היה צדיק ורצוי למעלה, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: משום כבודו של נחמיה בן חכליה,\u0004 שאף הוא היו לו שונאים מרובים מלמטה שלא בצדק.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנשה\u0004 מלך יהודה \u0003היה שונה חמשים וחמשה פנים\u0004 (דרכים) \u0003בתורת כהנים\u0004 (מדרש ההלכה על ספר ויקרא) \u0003כנגד שני\u0004 (שנות) \u0003מלכותו,\u0004 שכל כך גדול היה בחכמה. \u0003אחאב\u0004 גדול היה ממנו, ושנה \u0003שמנים וחמשה\u0004 פנים, \u0003ירבעם\u0004 שנה \u0003מאה ושלשה\u0004 פנים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: אבשלום אין לו חלק לעולם הבא, שנאמר: \"ויכו את אבשלום וימתהו\"\u0004 (שמואל ב' יח, טו), \u0003\"ויכוהו\"\u0004 — שהרגוהו \u0003בעולם הזה, \"וימיתהו\"\u0004 — \u0003לעולם הבא. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003ר' מאיר: אחז ואחזיה\u0004 ממלכי יהודה \u0003וכל מלכי ישראל שכתוב בהן \"ויעש הרע בעיני ה' \"\u0004— \u0003לא חיין\u0004 לעתיד לבוא, \u0003ו\u0004אולם גם \u0003לא נידונין\u0004 לנצח בגיהנם.","נאמר \u0003\"וגם דם נקי שפך מנשה הרבה מאד עד אשר מלא את ירושל ם פה לפה לבד מחטאתו אשר החטיא את יהודה לעשות הרע בעיני ה' \"\u0004(מלכים ב' כא, טז), מה עניינו של \"מלא את ירושלים פה לפה\"? \u0003הכא תרגימו\u0004 \u0005[כאן,\u0006 בבבל, \u0005הסבירו]\u0006 \u0003שהרג\u0004 את הנביא \u0003ישעיה\u0004 שהיה מדבר עם ה' פה אל פה. \u0003במערבא אמרי\u0004 \u0005[בארץ ישראל היו אומרים]:\u0006 \u0003שעשה צלם\u0004 כה גדול וכבד שהיה \u0003משאוי\u0004 (משא) \u0003אלף בני אדם, ובכל יום ויום הורג את כולם\u0004 מפני כובד המשא. ושואלים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו]\u0006 השמועה ש\u0003אמר רבה בר בר חנה: שקולה נשמה של צדיק אחד כנגד כל העולם כולו?\u0004 — \u0003כמאן דאמר\u0004 \u0005[כ\u0006שיטת \u0005מי שאומר]\u0006 שאת \u0003ישעיה הרג.\u0004","\u0003כתיב\u0004 \u0005[נאמר\u0006 במקרא\u0005]\u0006 שעשה \u0003\"פסל\"\u0004 (דברי הימים ב' לג, ו), \u0003וכתיב \"פסילים\"\u0004 (דברי הימים ב' לג, יט), \u0003אמר ר' יוחנן: בתחלה עשה לו\u0004 לפסל \u0003פרצוף אחד, ולבסוף עשה לו ארבעה פרצופים, כדי\u0004 להכעיס, \u0003שתראה שכינה\u0004 מכל צד \u0003ותכעוס.\u0004","\u0003אחז העמידו\u0004 את הפסל \u0003בעלייה\u0004 שבמקדש, \u0003שנאמר: \"ואת המזבחות אשר על הגג עלית אחז\"\u0004 (מלכים ב' כג, יב). \u0003מנשה העמידו בהיכל\u0004 עצמו, \u0003שנאמר: \"וישם את פסל האשרה אשר עשה בבית אשר אמר ה' אל דוד ואל שלמה בנו בבית הזה ובירושל ם אשר בחרתי מכל שבטי ישראל אשים את שמי לעולם\"\u0004 (מלכים ב' כא, ז). \u0003אמון הכניסו לבית קדשי הקדשים, שנאמר: \"כי קצר המצע מהשתרע והמסכה צרה כהתכנס\"\u0004 (ישעיה כח, כ).","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כי קצר המצע מהשתרע\"? אמר ר' שמואל בר נחמני אמר ר' יונתן: כי קצר המצע זה מלהשתרר\u0004 להיות \u0003עליו שני רעים כאחד,\u0004 שלא ייתכן שיהיו באותו מקום גם עבודת ה' וגם עבודה זרה. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"והמסכה צרה\u0004 כהתכנס \u0003\"?\u0004 \u0003אמר ר' שמואל בר נחמני: ר' יונתן כי הוה מטי\u0004 \u0003להאי קרא, הוה קא בכי\u0004 \u0005[כאשר היה מגיע למקרא זה, היה בוכה],\u0006 \u0003מי שכתב בו \"כנס כנד מי הים\"\u0004 (תהלים לג, ז) (והוא \"כהתכנס\") \u0003תעשה לו מסכה צרה\u0004 (מתחרה)?!","\u0003אחז\u0004 המלך \u0003בטל את העבודה\u0004 במקדש \u0003וחתם את התורה,\u0004 שאסר את לימודה, \u0003שנאמר: \"צור תעודה חתום תורה בלמדי\"\u0004 (ישעיה ח, טז). \u0003מנשה קדר\u0004 (חתך) \u0003את האזכרות\u0004 של שמות ה' מספרי הקודש, \u0003והרס את המזבח. אמון שרף את התורה, והעלה שממית\u0004 שהיא טמאה, כקרבן \u0003על גבי המזבח. אחז התיר את הערוה,\u0004 שהכריז שאין עוד איסורי עריות בנישואין. \u0003מנשה\u0004 עשה מעשה ו\u0003בא על אחותו,\u0004","\u0003אמון בא על אמו, שנאמר: \"כי הוא אמון הרבה אשמה\"\u0004 (דברי הימים ב' לג, כג) כלומר, עשה אשמה רבה ובזויה יותר מכולם. \u0003ר' יוחנן ור' אלעזר\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: ששרף את התורה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: שבא על אמו. אמרה לו אמו: כלום יש לך הנאה\u0004 בביאה \u0003ממקום שיצאת ממנו? אמר לה: כלום אני עושה\u0004 להנאתי? \u0003אלא להכעיס את בוראי\u0004 אני עושה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 ומלך המלך \u0003יהויקים, אמר: קמאי\u0004 \u0005[\u0006המלכים \u0005הראשונים]\u0006 \u0003לא ידעי לארגוזי\u0004 \u0005[ידעו\u0006 כלל \u0005להרגיז]\u0006 את הקדוש ברוך הוא, \u0003כלום אנו צריכין אלא לאורו\u0004 של הקדוש ברוך הוא? \u0003יש לנו זהב פרויים שאנו משתמשין בו\u0004 והוא מבריק, \u0003יטול\u0004 הקדוש ברוך הוא את \u0003אורו\u0004 מן העולם. \u0003אמרו לו: והלא\u0004 אף \u0003כסף וזהב שלו הוא, שנאמר: \"לי הכסף ולי הזהב נאם ה' צבאות\"\u0004 (חגי ב, ח)! \u0003אמר להם: כבר נתנו לנו, שנאמר: \"השמים שמים לה' והארץ נתן לבני אדם\"\u0004 (תהלים קטו, טז).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: מפני מה לא מנו את יהויקים\u0004 בין המלכים שאין להם חלק לעולם הבא? ויש טעם לחשוב שלא יהא לו חלק \u0003משום דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"ויתר דברי יהויקים ותעבתיו אשר עשה והנמצא עליו\"\u0004 (דברי הימים ב' לו, ח). והסבירו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"והנמצא עליו\"? ר' יוחנן ור' אלעזר\u0004 נחלקו, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: שחקק שם עבודה זרה על אמתו\u0004 (אבר המין שלו) מתוך דבקותו הרבה בה, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: שחקק שם שמים על אמתו\u0004 כדי לבזות את השם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה בר מרי לרבא: \u0003במלכים לא שמעתי\u0004 מדוע לא נמנה יהויקים, ואילו לגבי ארבעה \u0003הדיוטות שמעתי מפני מה לא מנו\u0004 ביניהם גם \u0003את מיכה\u0004 שעשה עבודה זרה שתעו כל ישראל אחריו? — \u0003מפני ש\u0004היתה \u0003פתו מצויה לעוברי דרכים, שנאמר: \"כל העובר ושב אל הלוים\",\u0004 שהיה מפרנס את כל המתארח בביתו.","על הנאמר: \u0003\"ועבר בים צרה והכה בים גלים\"\u0004 (זכריה י, יא), \u0003אמר ר' יוחנן: זה פסלו של מיכה\u0004 (\"צרה\") שאף הוא עבר ב\"ים\" כאשר עברו בו ישראל ביציאת מצרים. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר: מגרב\u0004 מקומו של מיכה \u0003לשילה\u0004 מרחק \u0003שלשה מילין, והיה עשן המערכה\u0004 שעל המזבח שבשילה \u0003ועשן פסל מיכה מתערבין זה בזה.\u0004","\u0003בקשו מלאכי השרת לדוחפו,\u0004 להוציא את מיכה מן העולם, \u0003אמר להן הקדוש ברוך הוא: הניחו לו,\u0004 לפי \u0003שפתו מצויה לעוברי דרכים. ועל דבר זה,\u0004 על חטא פסל מיכה, \u0003נענשו אנשי פלגש בגבעה\u0004 שבטי ישראל שעלו למלחמה על שבט בנימין ונהרגו מהם ארבעים אלף איש. \u0003אמר להן הקדוש ברוך הוא: בכבודי לא מחיתם\u0004 ולא עשיתם דבר לבער את פסלו של מיכה, \u0003על כבודו של בשר ודם\u0004 שהרגו את אשתו \u0003מחיתם!\u0004 ולכן לא הצליחו בתחילה במלחמתם ואבדו נפשות רבות.","\u0003אמר ר' יוחנן משום ר' יוסי בן קסמא: גדולה לגימה\u0004 (אכילה) שגרמה \u0003שהרחיקה שתי משפחות מישראל, שנאמר: \"\u0004לא יבא עמוני ומואבי בקהל ה'... \u0003על דבר אשר לא קדמו אתכם בלחם ובמים\"\u0004 (דברים כג, ד–ה). \u0003ור' יוחנן דידיה\u0004 \u0005[משלו]\u0006 \u0003אמר:\u0004 הלגימה פעמים \u0003מרחקת את הקרובים, ו\u0004פעמים \u0003מקרבת את הרחוקים, ומעלמת עינים מן הרשעים,\u0004 שלא יענשו, \u0003ומשרה שכינה על נביאי הבעל, ושגגתו\u0004 שפעמים אם אין מאכילים אדם רק מתוך שגגה הרי זה \u0003עולה\u0004 ונחשבת כ\u0003זדון.\u0004","ומפרטים ומבארים את הדברים: \u0003מרחקת\u0004 \u0003את הקרובים\u0004 —"],["\u0003מעמון ומואב\u0004 שהיו קרובים לישראל, שהם מבני לוט בן אחי אברהם, ומשום שלא נתנו לחם ומים לישראל נאסר להתחתן בהם.","\u0003ומקרבת את הרחוקים\u0004 — \u0003מיתרו.\u0004 ש\u0003אמר ר' יוחנן: בשכר\u0004 שאמר יתרו לבנותיו על משה \u0003\"קראן לו ויאכל לחם\"\u0004 (שמות ב, כ) \u0003זכו בני בניו\u0004 של יתרו \u0003וישבו בלשכת הגזית\u0004 במושב הסנהדרין, \u0003שנאמר: \"ומשפחות סופרים ישבי יעבץ תרעתים שמעתים שוכתים המה הקינים הבאים מחמת אבי בית רכב\"\u0004 (דברי הימים א' ב, נה), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 מי הם ה\"קינים\" — \u0003\"ובני קיני חתן משה עלו מעיר התמרים את בני יהודה מדבר יהודה אשר בנגב ערד וילך וישב את העם\"\u0004 (שופטים א, טז).","\u0003ומעלמת עינים מן הרשעים\u0004 — \u0003ממיכה,\u0004 שאמרנו שלא נענש משום שהיה עוסק בהכנסת אורחים.","\u0003ומשרה שכינה על נביאי הבעל\u0004 — \u0003מחבירו של עדו הנביא,\u0004 שעידו הנביא נשלח לנבא לירבעם ונשאר לאכול שם בניגוד לדבר ה', \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי הם ישבים אל השלחן ויהי דבר ה' אל הנביא אשר השיבו\"\u0004 (מלכים א' יג, כ) — אף שאותו נביא, נביא שקר היה מתחילה, זכה להתנבאות באמת בזכות הכנסת האורחים.","\u0003ושגגתה עולה זדון\u0004 — ש\u0003אמר רב יהודה אמר רב: אלמלא\u0004 (אילו) \u0003הלווהו יהונתן לדוד שתי ככרות לחם\u0004 בברחו מפני שאול, לא היה דוד נזקק ללכת לנוב לבקש שם לחם, ועל ידי כך \u0003לא נהרגה נוב עיר הכהנים, ולא נטרד דואג האדמי\u0004 מעולם הבא, \u0003ולא נהרג שאול ושלשת בניו\u0004 שכל אלה נגרמו בשל מעשה זה.","\u0003ו\u0004שואלים: כיון שמסופר כל כך הרבה על רשעותו של אחז, \u0003מפני מה לא מנו את אחז\u0004 בין המלכים שאין להם חלק לעולם הבא? \u0003אמר ר' ירמיה בר אבא: מפני שמוטל בין שני צדיקים, בין\u0004 אביו \u0003יותם ל\u0004בין בנו \u0003חזקיהו,\u0004 שהיו צדיקים. \u0003רב יוסף אמר: מפני שהיה לו בשת פנים מישעיהו\u0004 הנביא, \u0003שנאמר: \"ויאמר ה' אל ישעיהו צא נא לקראת אחז אתה ושאר ישוב בנך אל קצה תעלת הברכה העליונה אל מסלת שדה כובס\"\u0004 (ישעיה ז, ג). \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כובס\"\u0004 כאן? \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003דכבשינהו לאפיה וחלף\u0004 \u0005[שכבש\u0006 אחז \u0005אותם, את פניו, ועבר],\u0006 שדרשו \"כובס\" מלשון \"כובש\", שנתבייש אחז ועבר מלפני ישעיהו, \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003אוכלא דקצרי סחף ארישיה וחלף\u0004 \u0005[כלי הכובסים שם על ראשו\u0006 שלא יכירנו הנביא \u0005ועבר].\u0006","ועוד שואלים: \u0003מפני מה לא מנו את אמון\u0004 שאמרנו שהרבה אשמה, בין המלכים שאין להם חלק לעולם הבא? ומשיבים: \u0003מפני כבודו של יאשיהו\u0004 בנו. ושואלים: \u0003מנשה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא נמני\u0004 \u0005[ימנו]\u0006 אותו \u0003מפני כבודו של חזקיהו\u0004 אביו! ומשיבים: \u0003ברא מזכי אבא\u0004 \u0005[הבן מזכה\u0006 את \u0005האב],\u0006 שהרי נחשב הדבר לזכות לאב שמוליד בן צדיק, ואולם \u0003אבא לא מזכי ברא\u0004 \u0005[האב אינו מזכה\u0006 את \u0005הבן],\u0006 \u0003דכתיב \"ואין מידי מציל\"\u0004 (דברים לב, לט), \u0003אין אברהם מציל את ישמעאל\u0004 בנו מדיני שמים, \u0003אין יצחק מציל את עשו\u0004 בנו. ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן],\u0006 להסבר זה שהבן מזכה את האב, יכול אתה לומר: \u0003אחז נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אימני\u0004 \u0005[נמנה]\u0006 \u0003משום כבודו של חזקיהו\u0004 בנו.","ושואלים: \u0003ומפני מה לא מנו את יהויקים\u0004 שאמרנו שאף הוא היה רשע מופלג בין המלכים שאין להם חלק לעולם הבא? ומסבירים: \u0003משום\u0004 המסופר על ידי \u0003ר' חייא בר' אבויה.\u0004 ש\u0003אמר ר' חייא בר' אבויה: כתיב\u0004 \u0005[כתוב\u0006 היה, חקוק\u0005]\u0006 \u0003על גולגלתו\u0004 \u0003של יהויקים \"זאת ועוד אחרת\"\u0004 שיענש עונש כפול. מסופר: \u0003זקינו\u0004 של \u0003ר' פרידא\u0004 (ונראה שהוא ר' חייא בר אבויה) \u0003אשכח גולגלתא דהוה קא שדיא\u0004 \u0005[מצא גולגולת שהיתה מושלכת]\u0006 \u0003בשערי ירושלים, וכתיב\u0004 \u0005[וכתוב]\u0006 \u0003בה: \"זאת ועוד אחרת\". קברה ולא איקברא\u0004 \u0005[נקברה],\u0006 \u0003קברה\u0004 שוב \u0003ולא איקברא\u0004 \u0005[נקברה],\u0006 שבכל פעם היתה מבצבצת ויוצאת מן הקבר,","\u0003אמר:\u0004 ודאי \u0003גולגלתו של יהויקים היא, דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"קבורת חמור יקבר סחוב והשלך\u0004 מהלאה לשערי ירושלים\u0003\"\u0004 (ירמיה כב, יט), ונתקיים בו הדבר שאינו יכול להיקבר כשאר כל אדם מישראל. \u0003אמר:\u0004 מכל מקום \u0003מלכא\u0004 \u0005[מלך]\u0006 \u0003הוא, ולא איכשר לזלזולי ביה\u0004 \u0005[ואין ראוי לזלזל בו].\u0006 \u0003כרכה\u0004 את הגולגולת \u0003בשיראי ואותבה בסיפתא\u0004 \u0005[במשי והניחה בתוך תיבה].\u0006 \u0003חזיתא דביתהו\u0004 \u0005[ראתה\u0006 זאת \u0005אשתו],\u0006 \u0003סברא\u0004 \u0005[חשבה]\u0006 כי \u0003הא דאיתתא קמייתא הוה, דהא לא קא מנשי לה\u0004 \u0005[זו\u0006 הגולגולת \u0005של אשתו הראשונה היא, שאיננו שוכח אותה].\u0006 לכן \u0003שגרא תנורא וקלתה\u0004 \u0005[הסיקה\u0006 את \u0005התנור ושרפה אותה,\u0006 את הגולגולת\u0005],\u0006 וכשנודע המעשה לבעלה אמר: \u0003היינו דכתיב\u0004 \u0005[זהו שכתוב\u0006 עליה\u0005]\u0006 \u0003\"זאת ועוד אחרת\"\u0004 שלא די שיקבר בבזיון אלא אף ישרף. וכיון שנענש בגופו באופן זה, נתכפר לו מקצת עוונו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: בשביל\u0004 שאמר חזקיהו בהתפארות \u0003\"\u0004ו\u0003הטוב בעיניך עשיתי\"\u0004 (מלכים ב' כ, ג), ונתפאר במעשיו הטובים, גרם לעצמו שישאל מן הנביא \u0003\"מה אות\u0004 כי ירפא ה' לי\u0003\"\u0004 (מלכים ב' כ, ח), \u0003בשביל \"מה אות\"\u0004 — \u0003נכרים אכלו על שולחנו,\u0004 כי אות זה היה שתרד השמש במעלות אחז, ומשום כך שלח מלך בבל שלוחים אליו. \u0003בשביל שנכרים אכלו על שולחנו\u0004 לבסוף \u0003גרם גלות לבניו.\u0004 ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לחזקיה.\u0004 ש\u0003אמר חזקיה: כל המזמן עובד עבודה זרה לתוך ביתו ומשמש עליו גורם גלות לבניו\u0004 כעונש על כך, \u0003שנאמר: \"ומבניך אשר יצאו ממך אשר תוליד יקחו והיו סריסים בהיכל מלך בבל\"\u0004 (מלכים ב' כ, יח).","על הנאמר שם \u0003\"וישמח עליהם חזקיהו ויראם את בית נכתה את הכסף ואת הזהב ואת הבשמים ואת השמן הטוב\"\u0004 (ישעיה לט, ב), \u0003אמר רב: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בית נכתה\"?\u0004 — \u0003אשתו,\u0004 שכרגיל אין אחרים רואים אותה מפני צניעות, היא \u0003השקתה עליהם. ושמואל אמר: בית גנזיו\u0004 ממש \u0003הראה להם. ור' יוחנן אמר: זין\u0004 (כלי נשק) שהוא כל כך חזק ש\u0003אוכל\u0004 (ששובר) \u0003זין\u0004 אחר \u0003הראה להן.\u0004","כיון שהזכרנו את גלות בני מלכי יהודה לבבל, מביאים כמה דברי אגדה בענין החורבן וחטאי ישראל שגרמו לו. על הנאמר \u0003\"איכה ישבה בדד\"\u0004 (איכה א, א), \u0003אמר רבה אמר ר' יוחנן: מפני מה לקו ישראל\u0004 ונאמרה עליהם קינה \u0003ב\u0004לשון \u0003\"איכה\"?\u0004 — \u0003מפני שעברו על שלשים ושש כריתות ש\u0004יש \u0003בתורה\u0004 שהם כמנין \"איכה\".","\u0003אמר ר' יוחנן: מפני מה לקו באל\"ף בי\"ת,\u0004 שמגילת איכה כתובה באלף בית? — \u0003מפני שעברו על התורה שניתנה באל\"ף בי\"ת.\u0004","על הנאמר \u0003\"ישבה בדד\", אמר רבא אמר ר' יוחנן, אמר הקדוש ברוך הוא: אני אמרתי \"וישכן ישראל בטח בדד עין יעקב אל ארץ דגן ותירוש אף שמיו יערפו טל\"\u0004 (דברים לג, כח) ותהא בדידותם של עושר וגדולה, \u0003עכשיו\u0004 שלא רצו לקבל דברי והתחברו ולמדו מן הגויים — \u0003יהיה בדד מושבם.\u0004 על הנאמר \u0003\"העיר רבתי עם\"\u0004 (איכה א, א), \u0003אמר רבא אמר ר' יוחנן\u0004 לפרש: \u0003שהיו משיאין קטנה לגדול וגדולה לקטן, כדי שיהו להם בנים הרבה.\u0004","ובפירוש הכתוב \u0003\"היתה כאלמנה\"\u0004 (איכה א, א), \u0003אמר רב יהודה אמר רב: כאלמנה, ולא אלמנה ממש, אלא כאשה שהלך בעלה למדינת הים\u0004 שהיא אמנם בודדה כאלמנה אבל \u0003דעתו לחזור אליה. \"רבתי בגוים שרתי במדינות\"\u0004 (איכה א, א), \u0003אמר רבא אמר ר' יוחנן: כל מקום שהן הולכין\u0004 (בגלות במדינות) הריהם \u0003נעשין שרים לאדוניהן\u0004 מפני חכמתם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בשני בני אדם\u0004 מישראל \u0003שנשבו בהר הכרמל, והיה\u0004 ה\u0003שבאי\u0004 (זה ששבה אותם) \u0003מהלך אחריהם.\u0004"],["\u0003אמר לו אחד מהם\u0004 מן השבויים \u0003לחבירו: גמל שמהלכת לפנינו סומא\u0004 (עיוורת) \u0003באחת מעיניה, וטעונה שתי נודות, אחת של יין ואחת של שמן, ושני בני אדם המנהיגים אותה אחד\u0004 מהם \u0003ישראל ואחד\u0004 מהם \u0003גוי. אמר להן שבאי: עם קשה עורף! מאין אתם יודעין\u0004 דברים אלה שאינכם רואים?","\u0003אמרו לו:\u0004 שה\u0003גמל\u0004 סומא יודעים הם \u0003מעשבים שלפניה,\u0004 כי \u0003מצד שרואה אוכלת, מצד שאינה רואה אינה אוכלת,\u0004 ורואים אנו שאכלה רק מצד אחד. \u0003וטעונה שתי נודות אחת של יין ואחת של שמן,\u0004 כי טיפה מן הנוד \u0003של יין\u0004 — \u0003מטפטף ושוקע, ושל שמן\u0004 — \u0003מטפטף וצף,\u0004 ורואים אנו את ההבדל בטיפות. \u0003ושני בני אדם המנהיגים אותה אחד גוי ואחד ישראל,\u0004 כי \u0003גוי נפנה\u0004 לצרכיו \u0003לדרך\u0004 עצמה, \u0003וישראל\u0004 שנפנה \u0003נפנה לצדדין\u0004 מפני הצניעות.","\u0003רדף\u0004 השבאי \u0003אחריהם\u0004 אחרי ההולכים לפניו להשיגם ולברר את הדבר, \u0003ומצא כדבריהם. בא ונשקן על ראשן\u0004 בכבוד, \u0003והביאן לביתן ועשה להן סעודה גדולה, והיה מרקד לפניהם, ואמר: ברוך שבחר בזרעו של אברהם, ונתן להם מחכמתו, ובכל מקום שהן הולכים נעשין שרים לאדוניהם. ופטרן והלכו לבתיהם לשלום.\u0004","ועוד בפירוש מגילת איכה. על הנאמר \u0003\"בכה תבכה בלילה\"\u0004 (איכה א, ב) יש לתהות: \u0003שתי בכיות הללו למה? אמר רבה אמר ר' יוחנן: אחד על מקדש ראשון, ואחד על מקדש שני\u0004 שעתיד ליחרב. \u0003\"בלילה\"\u0004 — \u0003על עסקי\u0004 (בגלל) בעיות של \u0003לילה, שנאמר\u0004 לאחר שמיעת דברי המרגלים את הארץ: \u0003\"ותשא כל העדה ויתנו את קולם ויבכו העם בלילה ההוא\"\u0004 (במדבר יד, א).","\u0003אמר רבה אמר ר' יוחנן: אותו היום ליל תשעה באב היה, אמר להן הקדוש ברוך הוא לישראל: אתם בכיתם\u0004 ביום זה \u0003בכיה של חנם, ואני אקבע לכם בכיה לדורות\u0004 שתהא לכם סיבה לבכיה.","\u0003דבר אחר: \"בלילה\"\u0004 — \u0003שכל הבוכה בלילה, קולו נשמע\u0004 בגלל הדממה בחוץ. \u0003דבר אחר: \"בלילה\"\u0004 — \u0003שכל הבוכה בלילה כוכבים ומזלות בוכין עמו. דבר אחר: \"בלילה\"\u0004 — \u0003שכל הבוכה בלילה, השומע קולו\u0004 מתרגש ו\u0003בוכה כנגדו. מעשה באשה אחת\u0004 שהיתה \u0003שכנתו של רבן גמליאל שמת בנה, והיתה בוכה עליו בלילה, שמע רבן גמליאל קולה ובכה כנגדה, עד שנשרו ריסי עיניו\u0004 מרוב בכיה. \u0003למחר הכירו בו תלמידיו\u0004 שבכה \u0003והוציאוה משכונתו\u0004 כדי שתהא לו מנוחה.","על הנאמר שם \u0003\"ודמעתה על לחיה\"\u0004 (איכה א, ב), \u0003אמר רבא אמר ר' יוחנן: כאשה שבוכה על בעל נעוריה, שנאמר: \"אלי כבתולה חגרת שק על בעל נעוריה\"\u0004 (יואל א, ח). ועל הנאמר \u0003\"היו צריה לראש\"\u0004 (איכה א, ה), \u0003אמר רבא אמר ר' יוחנן:\u0004 כתוב זה בא ללמדנו ש\u0003כל המיצר לישראל נעשה ראש, שנאמר: \"כי לא מועף לאשר מוצק לה כעת הראשון הקל ארצה זבלון וארצה נפתלי והאחרון הכביד דרך הים עבר הירדן גליל הגוים\"\u0004 (ישעיה ח, כג), \u0003אמר רבא אמר ר' יוחנן:\u0004 מכתוב זה נלמד כי \u0003כל המציק לישראל אינו\u0004 נעשה \u0003עיף.\u0004","על הנאמר \u0003\"לא אליכם כל עברי דרך\"\u0004 (איכה א, יב), \u0003אמר רבא אמר ר' יוחנן: מכאן לקובלנא\u0004 (הבעת צער) \u0003מן התורה,\u0004 שראוי לאדם לפרסם לרבים את צערו כדי שיעזרוהו וירחמו עליו. על הכתוב \u0003\"כל עברי דרך\", אמר רב עמרם אמר רב:\u0004 שאמרה ירושלים \u0003עשאוני כעוברי על דת\u0004 העוברים על עיקרי החוק והמוסר, ש\u0003אילו בסדום כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וה' המטיר\u0004 \u0003על סדם\u0004 גפרית ואש מאת ה' מן השמים\u0003\"\u0004 (בראשית יט, כד), \u0003ואילו בירושלים כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ממרום שלח אש בעצמתי וירדנה\"\u0004 (איכה א, יג) — שבשניהם ירד אש משמים, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ויגדל עון בת עמי מחטאת סדם\"\u0004 (איכה ד, ו).","ושואלים: \u0003וכי משוא פנים יש בדבר\u0004 שלא נענשה ירושלים כסדום ולא נהפכה? \u0003אמר רבא אמר ר' יוחנן: מדה יתירה\u0004 של סבל \u0003היתה בירושלים שלא היתה בסדום,\u0004 ש\u0003אילו בסדום כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"הנה זה היה עון סדם אחותך גאון שבעת לחם\u0004 ושלות השקט היה לה ולבנותיה \u0003ויד עני ואביון לא החזיקה\"\u0004 (יחזקאל טז, מט), שיושבי העיר לא סבלו יסורי עוני ורעב, \u0003ואילו בירושלים כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ידי נשים רחמניות בשלו ילדיהן\"\u0004 (איכה ד, י), ואם כן נענשו יושבי ירושלים גם הם בחומרה רבה.","וביאור הכתוב \u0003\"סלה כל אבירי ה' בקרבי\"\u0004 (איכה א, טו) — \u0003כאדם שאומר לחברו: נפסלה מטבע זו,\u0004 שגדולי ירושלים נרמסו ובוזו ללא תקנה.","ועל הנאמר \u0003\"פצו עליך פיהם\"\u0004 (איכה ב, טז), \u0003אמר רבא אמר ר' יוחנן: בשביל מה הקדים\u0004 בכמה מפרקי איכה הפסוק שיש בו את האות \u0003פ\"א ל\u0004פסוק שיש בו את האות \u0003עי\"ן?\u0004 — \u0003בשביל\u0004 עוון ה\u0003מרגלים שאמרו בפיהם מה שלא ראו בעיניהם,\u0004 וכנגד הקדמת פה לעין הקדימו בקינה פ\"א לעי\"ן.","ועל הנאמר \u0003\"אכלי עמי אכלו לחם ה' לא קראו\"\u0004 (תהלים יד, ד), \u0003אמר רבא אמר ר' יוחנן: כל\u0004 גוי שודד \u0003האוכל מלחמן של ישראל\u0004 נראה לו כ\u0003טועם טעם לחם, ושאינו אוכל מלחמן של ישראל אינו טועם טעם לחם.\u0004 שכך נראה שאינם נהנים אלא מגזל של ישראל. ובביאור הכתוב \u0003\"ה' לא קראו\"\u0004 — \u0003רב אמר: אלו הדיינין\u0004 שלא היו יראי שמים, \u0003ושמואל אמר: אלו מלמדי תינוקות\u0004 שלא קראו בשם ה' בזמן הוראתם.","ומכאן חוזרים לעיקר ענין של המשנה, לגבי מניינם של אלה שאין להם חלק לעולם הבא. ושואלים: \u0003מי מנאן? אמר רב אשי: אנשי כנסת הגדולה מנאום. אמר רב יהודה אמר רב: בקשו עוד למנות אחד\u0004 (את שלמה המלך) בין אלה שאין להם חלק לעולם הבא, \u0003באה דמות דיוקנו של אביו ונשטחה לפניהם\u0004 בתחינה שלא ימנוהו, \u0003ולא השגיחו עליה. באה אש מן השמים ולחכה אש בספסליהם\u0004 — \u0003ולא השגיחו עליה.\u0004","\u0003יצאה בת קול ואמרה להם: \"חזית איש מהיר במלאכתו לפני מלכים יתיצב בל יתיצב לפני חשכים\"\u0004 (משלי כב, כט), כלומר, ראו גדולתו של שלמה \u0003מי שהקדים\u0004 בנין \u0003ביתי\u0004 (המקדש) \u0003ל\u0004בנין \u0003ביתו, ולא עוד אלא שביתי בנה\u0004 בזריזות \u0003בשבע שנים וביתו בנה בשלש עשרה שנה,\u0004 הוא \u0003\"לפני מלכים יתיצב בל יתיצב לפני חשכים\",\u0004 שאין ראוי למנותו עם הרשעים, \u0003ו\u0004עדיין \u0003לא השגיח עליה. יצאה בת קול ואמרה: \"המעמך ישלמנה כי מאסת כי אתה תבחר ולא אני\"\u0004 (איוב לד, לג), שהרי רק ה' הוא לבדו קובע מי יש לו חלק לעולם הבא, ואין הדבר תלוי בבני אדם.","ומעירים: \u0003דורשי רשומות היו אומרים: כולן,\u0004 כל ישראל המנויים שאין להם חלק, בסופם \u0003באין לעולם הבא, שנאמר: \"לי גלעד ולי מנשה ואפרים מעוז ראשי יהודה מחקקי. מואב סיר רחצי על אדום אשליך נעלי עלי פלשת התרועעי\"\u0004 (תהלים ס, ט–י. וראה שם קח ט,י). וכך נתבאר פסוק זה: \u0003\"לי גלעד ולי מנשה\"\u0004 — \u0003זה אחאב שנפל ברמות גלעד. \"מנשה\"\u0004 — \u0003כמשמעו\u0004 הוא המלך מנשה. \u0003\"אפרים מעוז ראשי\"\u0004 — \u0003זה ירבעם דקאתי\u0004 \u0005[שבא]\u0006 \u0003מ\u0004שבט \u0003אפרים. \"יהודה מחקקי\"\u0004 — \u0003זה אחיתופל\u0004"],["\u0003דקאתי\u0004 \u0005[שבא]\u0006 \u0003מ\u0004שבט \u0003יהודה. \"מואב סיר רחצי\"\u0004 — \u0003זה גחזי, שלקה על עסקי רחיצה\u0004 של נעמן ולקח ממונו ונענש בצרעת. \u0003\"על אדום אשליך נעלי\"\u0004 — \u0003זה דואג האדומי. \"עלי פלשת התרועעי\"\u0004 — \u0003אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם! אם יבא דוד שהרג את הפלשתי, והוריש את בניך גת,\u0004 ויטען \u0003על שאתה נותן חלק לדואג ואחיתופל שהיו שונאיו,\u0004 \u0003מה אתה עושה לו,\u0004 האם אתה מקבל לעולם הבא את אלה שהיו אויביו ושונאיו? \u0003אמר להן\u0004 הקב\"ה: \u0003עלי לעשותן ריעים זה לזה,\u0004 שאף דוד יסכים לכך.","על הנאמר \u0003\"מדוע שובבה העם הזה ירושל ם משבה נצחת\"\u0004 (ירמיה ח, ה), \u0003אמר רב: תשובה נצחת השיבה כנסת ישראל לנביא. אמר להן נביא לישראל: חזרו בתשובה,\u0004 שהרי \u0003אבותיכם שחטאו היכן הם? אמרו להן\u0004 לנביאים: \u0003ונביאיכם שלא חטאו היכן הם?\u0004 שהרי אף הם מתו! \u0003שנאמר\u0004 ויכוח זה בקיצור: \u0003\"אבותיכם איה הם והנבאים הלעולם יחיו\"\u0004 (זכריה א, ה). \u0003אמר להן\u0004 הנביא לישראל: \u0003אבותיכם חזרו והודו\u0004 שדברי הנביאים התקיימו, \u0003שנאמר: \"אך דברי וחקי אשר צויתי את עבדי הנביאים\u0004 הלוא השיגו אבותיכם וישובו ויאמרו כאשר זמם ה' צבאות לעשות לנו כדרכינו וכמעללינו כן עשה איתנו","\u0003\"\u0004(זכריה א, ו). \u0003שמואל אמר,\u0004 תשובה נצחת כך היתה: \u0003באו עשרה בני אדם וישבו לפניו\u0004 לפני הנביא יחזקאל, \u0003אמר להן: חזרו בתשובה! אמרו לו: עבד שמכרו רבו\u0004 (בעליו) לאדון אחר, \u0003ואשה שגרשה בעלה, כלום יש לזה על זה כלום?\u0004 וכיון שמסרנו ה' בידי אדונים אחרים, שוב אין בינינו לבינו כלום. \u0003אמר לו הקדוש ברוך הוא לנביא, לך אמור להן: \"אי זה ספר כריתות אמכם אשר שלחתיה או מי מנושי אשר מכרתי אתכם לו הן בעונתיכם נמכרתם ובפשעיכם שלחה אמכם\"\u0004 (ישעיה נ, א), שלא נותקו היחסים בין ה' ובין ישראל.","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר\u0004 \u0003ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"דוד עבדי\"\u0004 (שמואל ב' ג, יח) ונאמר: \u0003\"\u0004\u0003נבוכדנצר עבדי\"\u0004 (ירמיה מג, י), ולכאורה מה מקום לקרוא לנבוכדנצר הרשע עבד ה' כמו שקרא לדוד? אלא ש\u0003גלוי וידוע לפני מי שאמר והיה העולם שעתידין ישראל לומר כך\u0004 שמכרם ה' לגויים, ושוב אין להם קשר לקדוש ברוך הוא, \u0003לפיכך הקדים הקדוש ברוך הוא וקראו\u0004 לנבוכדנצר \u0003עבדו.\u0004 ולפי ההלכה \u0003עבד שקנה נכסים, עבד למי, נכסים למי?\u0004 — הכל שייך לאדון, ואם כן ברשות שמים הם עומדים.","על הנאמר \u0003\"והעלה על רוחכם היו לא תהיה אשר אתם אמרים נהיה כגוים כמשפחות הארצות לשרת עץ ואבן. חי אני נאם ה' אלהים אם לא ביד חזקה ובזרוע נטויה ובחמה שפוכה אמלוך עליכם\"\u0004 (יחזקאל כ, לב–לג), \u0003אמר רב נחמן: כל כי האי ריתחא לירתח רחמנא עלן ולפרוקינן\u0004 \u0005[\u0006ולואי \u0005ככל הכעס הזה שיכעס ה' עלינו ויצילנו].\u0006","ועל הנאמר \u0003\"ויסרו למשפט אלהיו יורנו\"\u0004 (ישעיה כח, כו), \u0003אמר רבה בר בר חנה: אמר להן נביא לישראל: חזרו בתשובה! אמרו לו: אין אנו יכולין,\u0004 כי \u0003יצר הרע שולט בנו. אמר להם: יסרו יצריכם! אמרו לו: \"אלהיו יורנו\"\u0004 כיצד לעשות זאת, ואנו לבדנו איננו מסוגלים אף לכך.","שנינו במשנה כי \u0003ארבעה הדיוטות\u0004 שהיו גם גדולים בחכמה — \u0003בלעם, ודואג, ואחיתופל וגחזי\u0004 — אין להם חלק בעולם הבא. ומעתה דורשים בהם. \u0003\"בלעם\"\u0004 נדרש כנוטריקון — \u0003בלא עם,\u0004 שאין לו חלק עם ישראל לעתיד. \u0003דבר אחר: \"בלעם\"\u0004 — \u0003שבלה\u0004 (השמיד, כילה) את \u0003עם\u0004 ישראל. \u0003\"בן בעור\"\u0004 — ללמד \u0003שבא על בעיר\u0004 (בהמה).","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003הוא בעור\u0004 אבי בלעם, \u0003הוא כושן רשעתים, הוא לבן הארמי. \"בעור\"\u0004 קראו לו — משום \u0003שבא על בעיר, כושן רשעתים\u0004 — משום \u0003דעבד\u0004 \u0005[שעשה]\u0006 \u0003שתי רשעיות בישראל, אחת בימי יעקב\u0004 שרדף אחריו לאבדו, \u0003ואחת בימי שפוט השופטים.\u0004 \u0003ומה שמו\u0004 האמיתי? — \u0003לבן הארמי שמו.\u0004","והיכן אתה למד זאת — \u0003כתיב\u0004 \u0005[נאמר]\u0006 פעם אחת: \u0003\"בן בעור\"\u0004 (במדבר כב, ה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 פעם אחרת: \u0003\"בנו בער\"\u0004 (במדבר כד, ג), וליישב זאת \u0003אמר ר' יוחנן:\u0004 ללמד ש\u0003אביו בנו הוא לו בנביאות,\u0004 שלגבי נבואה בעור הוא כבנו של בלעם, שבלעם היה גדול מאביו.","מדברי המשנה מדייקים: \u0003בלעם הוא דלא אתי לעלמא דאתי\u0004 \u0005[שאינו בא לעולם הבא],\u0006 \u0003הא אחריני אתו\u0004 \u0005[הרי\u0006 גויים \u0005אחרים באים]\u0006 לעולם הבא. \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006","— כשיטת \u0003ר' יהושע היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 נאמר \u0003\"ישובו רשעים לשאולה כל גוים שכחי אלהים\"\u0004 (תהלים ט, יח), וכוונת הכתוב: \u0003\"ישובו רשעים לשאולה\"\u0004 — \u0003אלו פושעי ישראל\u0004 הנידונים לשאול. \u0003\"כל גוים שכחי אלהים\"\u0004 — \u0003אלו פושעי גוים,\u0004 אלו \u0003דברי ר' אליעזר. אמר לו ר' יהושע: וכי נאמר \"בכל גוים\"\u0004 שפושעי ישראל הם כשאר כל הגויים, \u0003והלא לא נאמר אלא \"כל גוים שכחי אלהים\", אלא\u0004 כך יש לפרש \u0003\"ישובו רשעים לשאולה\" מאן נינהו\u0004 \u0005[מי הם]?\u0006 — \u0003\"כל גוים שכחי אלהים\",\u0004 וגויים שהם יראי ה' יש להם חלק לעולם הבא.","\u0003ואף אותו רשע,\u0004 בלעם, \u0003נתן סימן בעצמו, אמר: \"תמת נפשי מות ישרים\u0004 ותהי אחריתי כמוהו\u0003\"\u0004 (במדבר כג, י), \u0003אם תמות נפשי מות ישרים,\u0004 שאמות כדרך הטבע — \u0003תהא אחריתי כמוהו,\u0004 שיהיה לי חלק לעולם הבא כמו ישראל, \u0003ואם לאו\u0004 \u0005[לא]\u0006 אמות בדרך הטבע — \u0003\"הנני הולך לעמי\",\u0004 כלומר, כשאר רשעים שבדורו שאין להם חלק בו.","על הנאמר \u0003\"וילכו זקני מואב וזקני מדין\u0004 וקסמים בידם ויבואו אל בלעם\u0003\"\u0004 (במדבר כב, ז), \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003מדין ומואב לא היה להם שלום מעולם,\u0004 שהיו נלחמים זה בזה, ומפני מה השלימו בשעה זו? \u0003משל לשני כלבים שהיו בעדר, והיו צהובין\u0004 (שונאים) \u0003זה לזה. בא זאב\u0004 והתנפל \u0003על האחד. אמר האחד: אם איני עוזרו, היום הורג אותו ולמחר בא עלי. הלכו שניהם והרגו\u0004 את \u0003הזאב.\u0004 כך מואב ומדין השלימו לשעה כדי להלחם בישראל. \u0003אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם העממי: \u0003\"כרכושתא ושונרא עבדו הלולא מתרבא דביש גדא\"\u0004 \u0005[החולדה והחתול עשו חתונה מן החלב של רע המזל],\u0006 שאף ששניהם שונאים זה לזה עושים הם שלום ושמחה על חשבונו של אחר.","נאמר: \u0003\"וישבו שרי מואב עם בלעם\"\u0004 (במדבר כב, ח), ושואלים: \u0003ושרי מדין להיכן אזול\u0004 \u0005[הלכו]?\u0006 מדוע לא נאמר דבר עליהם? ומשיבים: \u0003כיון\u0004 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003\"לינו פה הלילה והשיבתי אתכם דבר\u0004 כאשר ידבר ה' אלי\u0003\"\u0004 (במדבר כב, ח), \u0003אמרו\u0004 זקני מדין: אם רצונו לקבל רשות מה' \u0003כלום יש אב ששונא את בנו?\u0004 ובוודאי יסייע ה' לבני ישראל.","\u0003אמר רב נחמן: חוצפא, אפילו כלפי שמיא\u0004 \u0005[שמים]\u0006 \u0003מהני\u0004 \u0005[\u0006היא \u0005מועילה].\u0006 כיצד? \u0003מעיקרא כתיב\u0004 \u0005[מתחילה נאמר]\u0006 שאמר לו ה' \u0003\"לא תלך עמהם\"\u0004 (במדבר כב, יב), \u0003ולבסוף\u0004 שהפציר וניסה שנית \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"קום לך אתם\"\u0004 (במדבר כב, כ). \u0003אמר רב ששת: חוצפא, מלכותא\u0004 \u0005[מלכות]\u0006 \u0003בלא תאגא\u0004 \u0005[כתר]\u0006 \u0003היא,\u0004 שתוקפה ואימתה מרובים ואין חסר לה אלא כתר מלוכה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ואנכי היום רך ומשוח מלך והאנשים האלה בני צרויה קשים ממני\"\u0004 (שמואל ב' ג, לט), הרי שבני צרויה בתוקף חוצפתם חזקים היו כדוד עצמו.","\u0003אמר ר' יוחנן: בלעם חיגר ברגלו\u0004 ה\u0003אחת היה, שנאמר\u0004 בו: \u0003\"וילך שפי\"\u0004 (במדבר כג, ג), ששפו (זזו) עצמות רגלו ממקומן. \u0003שמשון\u0004 היה חיגר \u0003בשתי רגליו, שנאמר\u0004 עליו בנבואת יעקב: \u0003\"\u0004יהי דן נחש עלי דרך \u0003שפיפן עלי ארח הנושך עקבי סוס\"\u0004 (בראשית מט, יז), ו\"שפיפון\" הוא כפלים \"שפי\". \u0003בלעם סומא באחת מעיניו היה, שנאמר: \"שתם העין\"\u0004 (במדבר כד, ג), שמשמעו שעין אחת פתוחה וגלויה, הרי שעינו האחרת עיורת היתה.","ועוד אומרים: בלעם \u0003קוסם באמתו\u0004 (אבר הזכרות שלו) \u0003היה.\u0004 ומהיכן אתה למד זאת — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"נפל וגלוי עינים\"\u0004 (במדבר כד, ד), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"והמן נפל על המטה\"\u0004 (אסתר ז, ח), משמע שנפילה זו קשורה בענייני משכב ואישות. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדבר, \u0003מר זוטרא אמר:\u0004 בלעם \u0003קוסם באמתו היה, מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא אמר: שבא על אתונו. מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003קוסם באמתו היה\u0004 — \u0003כדאמרן\u0004 \u0005[כפי שאמרנו],\u0006 \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 ש\u0003בא על אתונו היה\u0004 — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"כרע שכב\"\u0004 (במדבר כד, ט), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"בין רגליה\u0004"],["\u0003כרע נפל שכב\"\u0004 (שופטים ה, כז) שפירשוהו לענין בעילה.","נאמר בבלעם \u0003\"וידע דעת עליון\"\u0004 (במדבר כד, טז), ושואלים: \u0003השתא\u0004 \u0005[הרי]\u0006 \u0003דעת בהמתו לא הוה ידע\u0004 \u0005[היה יודע],\u0006 וכי \u0003דעת עליון הוה ידע\u0004 \u0005[היה יודע]?!\u0006 ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003דעת בהמתו\u0004 שלא ידע לענות? — \u0003דאמרי ליה\u0004 \u0005[שאמרו לו]\u0006 השרים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא רכבת\u0004 על \u0003סוסיא\u0004 \u0005[סוסים]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שדאי להו ברטיבא\u0004 \u0005[הבאתי אותם\u0006 את הסוסים לרעות \u0005באחו]\u0006 ולנוח שם.","\u0003אמרה ליה\u0004 \u0005[לו]\u0006 האתון: \u0003\"הלוא אנכי אתנך\"\u0004 (במדבר כב, ל), אמר לה: \u0003לטעינה בעלמא\u0004 \u0005[בלבד],\u0006 שמשתמש בה כרגיל למשא ואינו רוכב עליה. אמרה לו: \u0003\"אשר רכבת עלי\"\u0004 (במדבר כב, ל), אמר לה: \u0003אקראי בעלמא\u0004 \u0005[\u0006זו \u0005במקרה בלבד]\u0006 ולא בקביעות. אמרה לו: \u0003\"מעודך עד היום הזה\"\u0004 (במדבר כב, ל),","\u0003ולא עוד אלא שאני עושה לך מעשה אישות בלילה,\u0004 שהיה בועל אתונו. ומהיכן למד את זאת — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ההסכן הסכנתי\"\u0004 (במדבר כב, ל), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 באבישג השונמית: \u0003\"ותהי לו סכנת\"\u0004 (מלכים א' א, ב), הרי שלשון \"סכן\" רמז למשכב הוא.","ואם כן לא יכול בלעם אף לנצח את בהמתו בויכוח, \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וידע דעת עליון\"?\u0004 כיצד יתכן שהיה יודע דעת עליון? אלא \u0003שהיה יודע לכוון אותה שעה ש\u0004עליון, \u0003הקדוש ברוך הוא, כועס בה,\u0004 ובאותה שעה היה מקלל והיתה קללתו מתקיימת.","\u0003והיינו דקאמר להו\u0004 \u0005[וזהו שאמר להם]\u0006 ה\u0003נביא לישראל: \"עמי זכר נא מה יעץ בלק מלך מואב ומה ענה אתו בלעם בן בעור מן השטים עד הגלגל למען דעת צדקות ה' \"\u0004(מיכה ו, ה). \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"למען דעת צדקות ה' \"?\u0004 — \u0003אמר להן הקדוש ברוך הוא לישראל: דעו נא כמה צדקות עשיתי עמכם, שלא כעסתי כל אותן הימים בימי בלעם הרשע, שאילמלא כעסתי כל אותן הימים לא נשתייר משונאיהן של ישראל\u0004 (מישראל, בלשון נקיה) \u0003שריד ופליט.\u0004","\u0003היינו דקאמר ליה\u0004 \u0005[זהו שאמר לו]\u0006 \u0003בלעם לבלק: \"מה אקב לא קבה אל\u0004 ומה אזעם לא זעם ה'\u0003\"\u0004 (במדבר כג, ח), שמאחר ולא זעם ה' אינו יכול לקלל. נאמר \u0003\"\u0004ו\u0003אל זעם בכל יום\"\u0004 (תהלים ז, יב), \u0003וכמה\u0004 נמשך \u0003זעמו?\u0004 — \u0003רגע\u0004 אחד בלבד, \u0003שנאמר: \"כי רגע באפו חיים ברצונו\"\u0004 (תהלים ל, ו).","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 ראיה לדבר ממקום אחר, שנאמר: \u0003\"לך עמי בא בחדריך וסגר דלתך בעדך חבי כמעט רגע עד יעבר זעם\"\u0004 (ישעיה כו, כ). \u0003אימת רתח\u0004 \u0005[מתי כועס]\u0006 הקדוש ברוך הוא? מתי הוא אותו רגע של זעם? \u0003בתלת שעי קמייתא\u0004 \u0005[בשלוש שעות ראשונות\u0006 של היום\u0005],\u0006 \u0003כי חוורא כרבלתא דתרנגולא\u0004 \u0005[כאשר מלבינה כרבולת התרנגול],\u0006 וחיורון זה הוא סימן לזעם ה'. ושואלים: והלא \u0003כל שעתא ושעתא נמי חוורא\u0004 \u0005[שעה ושעה גם כן מלבינה\u0006 הכרבולת\u0005],\u0006 שאינה עומדת תמיד באדמומיתה! ומשיבים: \u0003כל שעתא ושעתא אית ביה סוריקי סומקי\u0004 \u0005[שעה ושעה יש בה גידים אדומים],\u0006 \u0003ההיא שעתא לית ביה סוריקי סומקי\u0004 \u0005[אותה שעה אין בה גידים אדומים]\u0006 ומלבינה כולה, וזה הוא רגע זעמו של ה'.","מסופר: \u0003ההוא מינא דהוה בשיבבותיה\u0004 \u0005[מין אחד שהיה בשכנותו]\u0006 של \u0003ר' יהושע בן לוי דהוה קא מצער ליה\u0004 \u0005[שהיה מצער אותו].\u0006 \u0003יומא חד נקט תרנגולתא, ואסר ליה בכרעיה, ואותיב\u0004 \u0005[יום אחד לקח\u0006 ר' יהושע בן לוי \u0005תרנגול, וקשר אותו ברגליו, והושיבו].\u0006 \u0003אמר: כי מטא ההוא שעתא אילטייה\u0004 \u0005[כאשר תגיע אותה שעה\u0006 של זעם \u0005אקללנו].\u0006 \u0003כי מטא ההוא שעתא\u0004 \u0005[כאשר הגיעה אותה השעה]\u0006 \u0003נמנם. אמר:\u0004 ר' יהושע בן לוי \u0003שמע מינה לאו אורח ארעא\u0004 \u0005[למד מכאן\u0006 ש\u0005אין\u0006 זו \u0005דרך ארץ]\u0006 ואין ראוי לעשות כן, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"גם ענוש לצדיק לא טוב\"\u0004 (משלי יז, כו), \u0003אפילו במיני\u0004 \u0005[ב\u0006ענין \u0005מינים]\u0006 \u0003לא איבעי ליה למימר הכי\u0004 \u0005[היה צריך לו לומר כך]\u0006 דברי קללה, שאינו ראוי לצדיק להיות מענישם של הבריות.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' מאיר: בשעה שהחמה זורחת והמלכים מניחין כתריהן על ראשיהן ומשתחוים לחמה, מיד כועס\u0004 הקדוש ברוך הוא, ולכן זמן הכעס הוא בשלוש שעות ראשונות.","נאמר בבלעם \u0003\"ויקם בלעם בבקר ויחבש את אתנו\"\u0004 (במדבר כב, כא), \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003משום\u0004 (בשם) \u0003ר' שמעון בן אלעזר: אהבה מבטלת שורה\u0004 (גדר) \u0003של גדולה,\u0004 ודבר זה נלמד \u0003מאברהם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישכם אברהם בבקר\u0004 ויחבוש את חמורו\u0003\"\u0004 (בראשית כב, ג), שהוא עצמו עשה כן ולא המתין למשרתיו, וכיוצא בזה \u0003שנאה מבטלת שורה של גדולה\u0004 — \u0003מבלעם, שנאמר: \"ויקם בלעם בבקר ויחבש\u0004 \u0003את אתנו\"\u0004 (במדבר כב, כא).","\u0003אמר רב יהודה אמר רב: לעולם יעסוק אדם בתורה ובמצוה, אפילו שלא לשמה, שמתוך שלא לשמה בא\u0004 לבסוף \u0003לשמה.\u0004 וראיה לדבר \u0003שבשכר ארבעים ושתים קרבנות שהקריב בלק\u0004 אף שהקריבם לשם מפלת ישראל \u0003זכה ויצאה ממנו רות. אמר ר' יוסי בר הונא: רות בתו של עגלון,\u0004 שהוא \u0003בן בנו של בלק מלך מואב היתה.\u0004","כיון שהוזכרה רות אמה של מלכות בית דוד, מביאים מה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרבה בר מרי: כתיב\u0004 \u0005[נאמר]\u0006 שאמרו עבדי דוד לדוד: \u0003\"ייטב אלהים את שם שלמה משמך ויגדל את כסאו מכסאך\"\u0004 (מלכים א' א, מז), והדבר תמוה: וכי \u0003אורח ארעא למימרא ליה למלכא הכי\u0004 \u0005[דרך ארץ לומר למלך כך]\u0006 שבנו יגדל ממנו?! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מעין קאמרה ליה\u0004 \u0005[אמרה לו],\u0006 וכוונתה: \"מכסאך\" — שיהיה מעין כסאך.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 ותפרש בצורה זו, אף מה שנאמר \u0003\"תברך מנשים יעל אשת חבר הקיני מנשים באהל תברך\"\u0004 (שופטים ה, כד), \u0003\"נשים באהל\" מאן נינהו\u0004 \u0005[מי הן]?\u0006 הלא הן האמהות \u0003שרה רבקה רחל ולאה,\u0004 וכי \u0003אורח ארעא למימר הכי\u0004 \u0005[דרך ארץ לומר כך]\u0006 על אמותיהם של ישראל? \u0003אלא מעין קאמר\u0004 \u0005[אמר]\u0006 שתבורך מברכתן של האמהות. \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003מעין\u0004 כסאו \u0003קאמר\u0004 \u0005[אמר].\u0006","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על דעת \u0003רב יוסי בר חוני,\u0004 ש\u0003אמר רב יוסי בר חוני: בכל אדם מתקנא, חוץ מ\u0004אשר ב\u0003בנו ותלמידו,\u0004 שכיון שהם באים מכוחו שמח הוא בגדלותם. \u0003בנו\u0004 למדים \u0003משלמה,\u0004 שאמרו עבדי דוד לדוד בפניו ששלמה יהיה גדול ממנו. \u0003ו\u0004לענין \u0003תלמידו, איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 נלמד ממה שאמר אלישע לאליהו: \u0003\"ויהי נא פי שנים ברוחך אלי\"\u0004 (מלכים ב' ב, ט), שביקש ממנו בפניו שיהא גדול ממנו, משמע שאין זה דבר צער, \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ראיה ממשה: \u0003\"ויסמך את ידיו עליו ויצוהו\"\u0004 (במדבר כז, כג), שה' ציווהו רק לסמוך ידו אחת עליו והוא סמכו בכל יכולתו בשתי ידיו.","על הנאמר \u0003\"וישם\u0004 ה' \u0003דבר בפי בלעם\"\u0004 (במדבר כג, ה), \u0003ר' אלעזר אומר: מלאך\u0004 היה מדבר בפיו, \u0003ר' יונתן אמר: חכה\u0004 נתנו בפיו, כלומר, מעצור עשה לו שלא יאמר דבר אחר.","\u0003אמר ר' יוחנן: מברכתו של אותו רשע אתה למד מה היה בלבו\u0004 לקלל, אלא שהפך את הקללה לברכה. \u0003ביקש לומר שלא יהו להם בתי כנסיות ובתי מדרשות,\u0004 ואמר \u0003\"מה טבו אהליך יעקב\"\u0004 (במדבר כד, ה) שהיא ברכת בתי כנסיות. ביקש לומר \u0003לא תשרה שכינה עליהם,\u0004 \u0003ו\u0004אמר \u0003\"משכנתיך ישראל\".\u0004 ביקש לומר ש\u0003לא תהא מלכותן נמשכת,\u0004 והפך ואמר \u0003\"כנחלים נטיו\"\u0004 (במדבר כד, ו), שהם נמשכים והולכים. ביקש לומר ש\u0003לא יהא להם זיתים וכרמים,\u0004 והפך ואמר \u0003\"כגנת עלי נהר\".\u0004 רצה לקללם ש\u0003לא יהא ריחן נודף\u0004 במצוות, ואמר להיפך \u0003\"כאהלים נטע ה' \"\u0004(במדבר כד, ו).","רצה לקללם ש\u0003לא יהיו להם מלכים בעלי קומה,\u0004 ואמר \u0003\"כארזים עלי מים\".\u0004 רצה לומר ש\u0003לא יהיה להם מלך בן מלך,\u0004 והוכרח לומר \u0003\"יזל מים מדליו\"\u0004 (במדבר כד, ז). רצה לקלל ש\u0003לא תהא מלכותן שולטת באומות,\u0004 ואמר \u0003\"וזרעו במים רבים\"\u0004 (במדבר כד, ז) כנגד רצונו. רצה לומר ש\u0003לא תהא עזה מלכותן,\u0004 ואמר \u0003\"וירם מאגג מלכו\"\u0004 (במדבר כד, ז). ביקש לומר ש\u0003לא תהא אימת מלכותן\u0004 על נתיניהם, אבל אמר \u0003\"ותנשא מלכתו\".\u0004","\u0003אמר ר' אבא בר כהנא: כולם חזרו\u0004 לבסוף \u0003לקללה\u0004 שהיתה בלבו, שכל אותם הדברים נתקיימו בישראל, \u0003חוץ מ\u0004חורבן \u0003בתי כנסיות ומבתי מדרשות, שנאמר: \"ויהפך ה' אלהיך לך את הקללה לברכה כי אהבך ה' אלהיך\"\u0004 (דברים כג, ו) — \u0003\"קללה\"\u0004 בלשון יחיד נאמר \u0003ולא \"קללות\",\u0004 לומר שרק אחת הקללות בטלה כולה לעולם.","\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"נאמנים פצעי אוהב ונעתרות נשיקות שונא\"\u0004 (משלי כז, ו) — \u0003טובה קללה שקילל אחיה השילוני את ישראל יותר מברכה שברכם בלעם הרשע. אחיה השילוני קילל את ישראל בקנה, שנאמר: \"והכה ה' את ישראל כאשר ינוד הקנה במים\"\u0004 (מלכים א' יד, טו), וצד הברכה שבו — \u0003מה קנה זה עומד במקום\u0004 \u0003מים\u0004 והמים משקים אותו תמיד, \u0003וגיזעו\u0004"],["\u0003מחליף,\u0004 שאם קוצצים אותו הוא חוזר ומגדל גזע חדש, \u0003ושרשיו מרובין, ואפילו כל רוחות שבעולם באות ונושבות בו אין מזיזות אותו ממקומו\u0004 שיעקר, \u0003אלא הוא הולך ובא עמהן, כיון שדוממו הרוחות עמד קנה במקומו.\u0004","\u0003אבל בלעם הרשע ברכן בארז, מה ארז זה אינו עומד במקום מים, ושרשיו מועטין\u0004 לפי גדלו, \u0003ואין גזעו מחליף,\u0004 שאם נחתך אינו צומח עוד, ו\u0003אפילו כל הרוחות שבעולם באות ונושבות בו אין מזיזות אותו ממקומו,\u0004 ואולם \u0003כיון שנשבה בו רוח דרומית מיד עוקרתו והופכתו על פניו. ולא עוד אלא שזכה קנה ליטול ממנו קולמוס\u0004 (עט) \u0003לכתוב ממנו ספרי תורה נביאים וכתובים,\u0004 ואם כן יפה קללתו של אחיה מברכת בלעם.","נאמר עוד בדברי בלעם: \u0003\"וירא את הקיני וישא משלו\u0004 ויאמר איתן מושבך ושים בסלע קנך\u0003\"\u0004 (במדבר כד, כא), \u0003אמר לו בלעם ליתרו: קיני,\u0004 וכי \u0003לא היית עמנו באותה עצה\u0004 שיעצנו להטביע את בני ישראל במצרים, \u0003מי הושיבך אצל איתני עולם?\u0004","\u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' חייא בר אבא אמר ר' סימאי: שלשה היו באותה עצה, אלו הן: בלעם, איוב ויתרו. בלעם שיעץ\u0004 עצה זו — סופו \u0003נהרג, איוב ששתק\u0004 ופחד להביע דעה — \u0003נידון ביסורין, ויתרו שברח\u0004 לאחר שאמר שאינו מסכים לעצה ורצה פרעה להרגו — \u0003זכו בני בניו לישב בלשכת הגזית, שנאמר: \"ומשפחות סופרים יושבי יעבץ תרעתים שמעתים שוכתים המה הקינים הבאים מחמת אבי בית רכב\"\u0004 (דברי הימים א' ב, נה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ובני קיני חתן משה עלו מעיר התמרים\"\u0004 (שופטים א, טז).","ועל מה שנאמר עוד בדברי בלעם \u0003\"וישא משלו ויאמר אוי מי יחיה משמו אל\"\u0004 (במדבר כד, כג), \u0003אמר ר' שמעון בן לקיש: אוי מי שמחיה\u0004 את \u0003עצמו בשם אל\u0004 ומתפרנס ממה שמדבר בשם ה' כבלעם. \u0003אמר ר' יוחנן: אוי לה לאומה שתמצא\u0004 מעכבת את ישראל \u0003בשעה שהקדוש ברוך הוא עושה פדיון לבניו,\u0004 כי \u0003מי מטיל כסותו בין לביא ללביאה בשעה שנזקקין זה עם זה?\u0004 מי שעושה כן ודאי סופו מיתה.","ועל מה שנאמר שם \u0003\"וצים מיד כתים\"\u0004 (במדבר כד, כד), \u0003אמר רב:\u0004 אלה הן \u0003ליבון אספיר,\u0004 גדוד רומי שיבוא על אשור. \u0003\"וענו אשור וענו עבר\"\u0004 (במדבר כד, כד), כלומר, \u0003עד\u0004 שיגיעו ל\u0003אשור\u0004 — \u0003קטלי מיקטל\u0004 \u0005[יהרגו]\u0006 את ישראל, \u0003מכאן ואילך\u0004 — \u0003משעבדי שיעבודי\u0004 \u0005[ישעבדו אותם]\u0006 ולא יהרגום.","נאמר עוד שאמר בלעם: \u0003\"הנני הולך לעמי לכה איעצך אשר יעשה העם הזה לעמך\"\u0004 (במדבר כד, יד), ולכאורה \u0003\"\u0004אשר יעשה \u0003עמך לעם הזה\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אמר ר' אבא בר כהנא: כאדם שמקלל את עצמו\u0004 אבל אינו רוצה להוציא את הדבר מפיו \u0003ותולה קללתו באחרים.\u0004","\u0003אמר להם\u0004 עצה זאת: \u0003אלהיהם של אלו\u0004 של ישראל \u0003שונא זימה הוא, והם\u0004 ישראל \u0003מתאוים לכלי פשתן,\u0004 שאין להם בגדים חדשים, \u0003בוא ואשיאך עצה\u0004 זו: \u0003עשה להן קלעים\u0004 (סוכות), \u0003והושיב בהן זונות, זקינה מבחוץ וילדה\u0004 (צעירה) \u0003מבפנים, וימכרו להן כלי פשתן.\u0004","\u0003עשה להן קלעים מהר שלג\u0004 (החרמון) \u0003עד בית הישימות, והושיב בהן זונות, זקינה מבחוץ וילדה מבפנים,\u0004 \u0003ובשעה שישראל אוכלין ושותין ושמחין ויוצאין לטייל בשוק, אומרת לו הזקינה:\u0004 וכי \u0003אי\u0004 (אין) \u0003אתה מבקש כלי פשתן?\u0004 נכנס לראות ושואל למחיר, \u0003זקינה אומרת לו ב\u0004מחיר ה\u0003שוה, וילדה אומרת לו בפחות,\u0004 וכך באים \u0003שתים ושלש פעמים.\u0004","\u0003ואחר כך אומרת לו: הרי את כבן בית\u0004 אצלנו, \u0003שב ברור לעצמך\u0004 סחורה שאתה חפץ בה. \u0003וצרצורי\u0004 (כד) \u0003של יין עמוני מונח אצלה, ועדיין לא נאסר\u0004 לישראל סתם \u0003יין של עמוני ולא יין של גוים. אמרה לו: רצונך שתשתה כוס של יין? כיון ששתה, בער בו\u0004 יצרו.","\u0003אמר לה: השמיעי\u0004 (היבעלי) \u0003לי.\u0004 \u0003הוציאה יראתה\u0004 (פסל עבודה זרה) \u0003מתוך חיקה, אמרה לו: עבוד לזה! אמר לה:\u0004 ו\u0003הלא יהודי אני\u0004 ואסורה עלי עבודה זרה! \u0003אמרה לו: ומה איכפת לך? כלום מבקשים ממך אלא פיעור\u0004 (הטלת צואה בפניו), \u0003והוא אינו יודע שעבודתה בכך.\u0004 כיון שעשה כן אומרת לו: \u0003ולא עוד אלא שאיני מנחתך עד שתכפור בתורת משה רבך, שנאמר: \"המה באו בעל פעור וינזרו לבשת ויהיו שקוצים באהבם\"\u0004 (הושע ט, י), שנתנו עצמם לחרפת הפיעור, ואף שיקצו שם ה'.","ועל הנאמר \u0003\"וישב ישראל בשטים\"\u0004 (במדבר כה, א), \u0003ר' אליעזר אומר: \"שטים\" שמה, ר' יהושע אומר:\u0004 רמז הוא \u0003שנתעסקו בדברי שטות\u0004 של זנות ועבודה זרה.","ועל הנאמר \u0003\"ותקראן לעם לזבחי אלהיהן\"\u0004 (במדבר כה, ב), \u0003ר' אליעזר אומר: ערומות פגעו בהן\u0004 (שדורש \"תקראן\" מלשון פגישה, מקרה), \u0003ר' יהושע אומר: שנעשו כולן בעלי קריין\u0004 מן התאוה, שדורש \"ותקראנה\" לשון \"קרי\".","וכיון שדרשו שמות מקומות הביאו מחלוקת דומה, \u0003מאי\u0004 \u0005[מה]\u0006 ה\u0003לשון \"רפידים\"? ר' אליעזר אומר: \"רפידים\"\u0004 ממש \u0003שמה, ר' יהושע אומר:\u0004 רמז הוא \u0003שריפו עצמן מדברי תורה\u0004 (\"רפידים\" — רפיון ידים), \u0003שנאמר: \"לא הפנו אבות אל בנים מרפיון ידים\"\u0004 (ירמיה מז, ג), שאף שם משמעו ביטול לימוד התורה.","\u0003אמר ר' יוחנן: כל מקום שנאמר\u0004 לשון \u0003\"וישב\" אינו אלא לשון צער,\u0004 שאז מתחילה פורענות כלשהי, \u0003שנאמר: \"וישב ישראל בשטים ויחל העם לזנות אל בנות מואב\"\u0004 (במדבר כה, א). נאמר \u0003\"וישב יעקב בארץ מגורי אביו בארץ כנען\"\u0004 (בראשית לז, א), ומיד \u0003\"ויבא יוסף את דבתם רעה אל אביהם\"\u0004 (בראשית לז, ב), ובהמשך כל מה שאירע במכירת יוסף. \u0003ונאמר: \"וישב ישראל\u0004 בארץ מצרים \u0003בארץ גשן\"\u0004 (בראשית מז, כז), ומיד אחריו \u0003\"ויקרבו ימי ישראל למות\"\u0004 (בראשית מז, כט). \u0003\"וישב יהודה וישראל לבטח איש תחת גפנו ותחת תאנתו\"\u0004 (מלכים א' ה, ה), ונאמר אחר כך \u0003\"ויקם ה' שטן לשלמה את הדד האדמי מזרע המלך הוא באדום\"\u0004 (מלכים א' יא, יד).","ועוד לענין בלעם, נאמר כי \u0003\"ואת מלכי מדין הרגו על חלליהם... ואת בלעם בן בעור הרגו בחרב\"\u0004 (במדבר לא, ח). ושואלים: \u0003בלעם מאי בעי התם\u0004 \u0005[מה צריך הוא שם]\u0006 ומה מעשיו במלחמה זו? והלא מקומו בארם! \u0003אמר ר' יוחנן: שהלך ליטול שכר עשרים וארבעה אלף שהפיל מישראל\u0004 על ידי עצתו. \u0003אמר מר זוטרא בר טוביה אמר רב: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי: \u0003\"גמלא אזלא למיבעי קרני, אודני דהוו ליה גזיזן מיניה\"\u0004 \u0005[גמל הלך לבקש קרניים, האזניים שהיו לו נגזזו ממנו],\u0006 וכן אירע לבלעם, שלא זו בלבד שלא קיבל שכרו אלא גם איבד את חייו.","נאמר: \u0003\"ואת בלעם בן בעור הקוסם\u0004 הרגו בני ישראל בחרב אל חלליהם\u0003\"\u0004 (יהושע יג, כב). ותמהים: וכי \u0003קוסם\u0004 הוא?! והלא \u0003נביא הוא! אמר ר' יוחנן: בתחלה נביא\u0004 היה, \u0003ולבסוף\u0004 נסתלקה ממנו הנבואה ונשאר רק \u0003קוסם. אמר רב פפא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי: \u0003\"מסגני ושילטי הואי\u0004 \u0005[מ\u0006משפחת \u0005אדונים ושליטים\u0006 \u0005היתה]\u0006 אשה זו, \u0003אייזן לגברי נגרי\u0004 \u0005[וזנתה לאיש נגר]\u0006 \u0003\".\u0004"],["\u0003\"הרגו בני ישראל בחרב אל חלליהם\"\u0004 (יהושע יג, כב), \u0003אמר רב: שקיימו בו ארבע מיתות\u0004 כולן: \u0003סקילה ושריפה הרג וחנק.\u0004","\u0003אמר ליה ההוא מינא\u0004 \u0005[לו מין אחד]\u0006 \u0003לר' חנינא: מי שמיע\u0004 \u0005[האם ידוע]\u0006 \u0003לך\u0004 \u0003בלעם בר\u0004 \u0005[בן]\u0006 \u0003כמה הוה\u0004 \u0005[היה]\u0006 כשמת? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מיכתב\u0004 \u0005[להיכתב]\u0006 במקרא \u0003לא כתיב\u0004 \u0005[נכתב]\u0006 הדבר במפורש, \u0003אלא מדכתיב\u0004 \u0005[מכיון שנאמר]\u0006 \u0003\"אנשי דמים ומרמה לא יחצו ימיהם\"\u0004 (תהלים נה, כד), משמע ש\u0003בר תלתין ותלת שנין\u0004 \u0005[בן שלושים ושלוש שנים]\u0006 \u0003או בר תלתין\u0004 \u0005[בן שלושים]\u0006 \u0003וארבע,\u0004 שוודאי לא הגיע למחצית שנות אדם רגילות שהן שבעים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שפיר קאמרת\u0004 \u0005[יפה אמרת],\u0006 \u0003לדידי חזי לי פנקסיה\u0004 \u0005[אני עצמי ראיתי\u0006 את \u0005ספרו]\u0006 של \u0003בלעם, והוה כתיב ביה\u0004 \u0005[והיה כתוב בו]:\u0006 \u0003בר תלתין ותלת שנין\u0004 \u0005[בן שלושים ושלוש שנים]\u0006 היה \u0003בלעם חגירא\u0004 \u0005[החיגר]\u0006 \u0003כד קטיל יתיה\u0004 \u0005[כאשר הרג אותו]\u0006 \u0003פנחס ליסטאה\u0004 \u0005[השודד].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא לבריה\u0004 \u0005[לבנו]:\u0006 \u0003בכולהו\u0004 \u0005[בכולם]\u0006 שנזכר שאין להם חלק לעולם הבא \u0003לא תפיש למדרש\u0004 \u0005[אל תרבה לדרוש]\u0006 דברים של גנאי, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מבלעם הרשע,\u0004 שכל \u0003כמה דמשכחת ביה\u0004 \u0005[שאתה מוצא בו]\u0006 דברי גנאי \u0003דרוש ביה\u0004 \u0005[בו]\u0006 והוסף למצוא בגנותו, שכן ראוי לייחס לרשע דברי רשע.","\u0003כתיב\u0004 \u0005[נאמר]\u0006 ששמו \u0003\"דואג\"\u0004 (\"ויען דואג האדומי\". שמואל א' כב, ט) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 גם ששמו \u0003\"דוייג\"\u0004 (\"ויאמר המלך לדויג... ויסוב דויג האדומי\". שמואל א' כב, יח). \u0003אמר ר' יוחנן,\u0004 כך יש לדרוש: \u0003בתחילה יושב הקדוש ברוך הוא ודואג\u0004 עליו: \u0003שמא יצא זה לתרבות רעה. לאחר שיצא אמר: \"ווי שיצא זה\"\u0004 והוא \"וי\" שבדוייג.","\u0003(סימן\u0004 לדברי ר' יצחק שלהלן: \u0003גבור ורשע וצדיק חיל וסופר).\u0004","\u0003אמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"מה תתהלל ברעה הגבור חסד אל כל היום\"\u0004 (תהלים נב, ג)? — \u0003אמר לו הקדוש ברוך הוא לדואג:\u0004 וכי \u0003לא גבור בתורה אתה? מה תתהלל ברעה?\u0004 וכי \u0003לא חסד אל נטוי עליך כל היום\u0004 כשאתה עוסק בתורתו?","\u0003ואמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ולרשע אמר אלהים מה לך לספר חקי\u0004 ותשא בריתי עלי פיך\u0003\"\u0004 (תהלים נ, טז)? — \u0003אמר לו הקדוש ברוך הוא לדואג הרשע: מה לך לספר\u0004 ולדון ב\u0003חקי\u0004 ובתורתי? \u0003כשאתה מגיע לפרשת מרצחים ופרשת מספרי לשון הרע, מה אתה דורש בהם?\u0004 והלא בשתיהן עברת. על הנאמר שם \u0003\"ותשא בריתי עלי פיך\"\u0004 (תהלים נ, טז), \u0003אמר ר' אמי: אין תורתו של דואג אלא משפה ולחוץ,\u0004 \"עלי פיך\" ולא בלבבך, שלא הבין את התורה לכל עומקה, ולא קיבלה על עצמו.","\u0003ואמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ויראו צדיקים וייראו ועליו ישחקו\"\u0004 (תהלים נב, ח) — \u0003בתחילה ייראו\u0004 מפני הצלחתו, \u0003ולבסוף ישחקו\u0004 שראו במפלתו.","\u0003ואמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"חיל בלע ויקאנו מבטנו ירשנו אל\"\u0004 (איוב כ, טו)? — \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם, ימות דואג\u0004 ולא תהא לו תקנה. \u0003אמר לו\u0004 ה': \u0003\"חיל בלע ויקיאנו\",\u0004 הלא מלא הוא בדברי תורה וחכמה והמתן לו עד שישכח מה שלמד! \u0003אמר לפניו\u0004 דוד: \u0003\"מבטנו יורישנו אל\",\u0004 שיכול ה' להוציא תורתו ממנו אף קודם שישכחנה מעצמו.","\u0003ואמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"גם אל יתצך לנצח\"\u0004 (תהלים נב, ז) — \u0003אמר הקדוש ברוך הוא לדוד: ניתי\u0004 \u0005[שיבוא]\u0006 \u0003דואג לעלמא דאתי\u0004 \u0005[לעולם הבא].\u0006 \u0003אמר\u0004 דוד \u0003לפניו: \"גם אל יתצך לנצח\",\u0004 שלא יהיה לו נצח. \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"יחתך ויסחך מאהל ושרשך מארץ חיים סלה\"\u0004 (תהלים נב, ז)? — \u0003אמר הקדוש ברוך הוא\u0004 לדוד: לפחות \u0003לימרו שמעתא בי מדרשא משמיה\u0004 \u0005[שיאמרו הלכה בבית המדרש בשמו].\u0006 \u0003אמר לפניו\u0004 דוד: \u0003\"יחתך ויסחך מאהל\"\u0004 שיסולק לגמרי מאהלי תורה. אמר לו ה': \u0003ליהוי ליה בנין רבנן\u0004 \u0005[שיהו לו בנים חכמים].\u0006 אמר דוד: \u0003\"ושרשך מארץ חיים סלה\"\u0004 שיעקר משורשו לגמרי.","\u0003ואמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"איה ספר איה שקל איה ספר את המגדלים\"\u0004 (ישעיה לג, יח)? — \u0003\"איה ספר\"\u0004 — \u0003כל אותיות שבתורה, \"איה שקל\"\u0004 — \u0003ששוקל כל קלים וחמורים שבתורה, \"איה ספר את המגדלים\"\u0004 — \u0003שהיה\u0004 דואג \u0003סופר\u0004 היה יכול להגיע ולמנות \u0003שלש מאות הלכות\u0004 \u0003פסוקות במגדל הפורח באויר\u0004 ודיני טומאה הנובעים מבעיה זו.","\u0003אמר רבי: ארבע מאה בעייא בעו\u0004 \u0005[מאות שאלות שאלו]\u0006 \u0003דואג ואחיתופל במגדל הפורח באויר, ולא איפשט להו חד\u0004 \u0005[נפתרה להם אחת],\u0006 להודיע כמה מרובה היתה חכמתם. על כך \u0003אמר רבא:\u0004 וכי \u0003רבותא למבעי בעיי\u0004 \u0005[גדולה\u0006 היא \u0005לשאול שאלות]?!\u0006 לא בכך נמדדת גדולתו של אדם, שהרי \u0003בשני\u0004 \u0005[בשנותיו]\u0006 של \u0003רב יהודה כולי תנויי\u0004 \u0005[כל לימודם]\u0006 \u0003ב\u0004סדר \u0003נזיקין\u0004 היה, \u0003ואנן קא מתנינן טובא\u0004 \u0005[ואנו שונים הרבה]\u0006 ואפילו \u0003בעוקצין\u0004 שבסדר טהרות הקשה.","ועוד, \u0003וכי הוה מטי\u0004 \u0005[וכאשר היה מגיע]\u0006 \u0003רב יהודה\u0004 למשנה \u0003\"אשה שכובשת ירק בקדירה\"\u0004 העוסקת בדיני משקים המקבלים טומאה, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 למשנה של \u0003\"זיתים שכבשן בטרפיהן טהורים\"\u0004 שעניינה דיני ידים לטומאה, \u0003אמר: הויות\u0004 \u0005[בעיות]\u0006 של \u0003רב ושמואל קא חזינא הכא\u0004 \u0005[אני רואה כאן],\u0006 שהיה מתקשה בדברים אלה ומשווה אותם לבעיות הקשות שעסקו בהן רבותיו, רב ושמואל. \u0003ואנן קא מתנינן\u0004 \u0005[ואנחנו מלמדים]\u0006 \u0003בעוקצין תלת סרי מתיבתא\u0004 \u0005[\u0006ב\u0005שלוש עשרה ישיבות],\u0006","\u0003ו\u0004בכל זאת אף שאנו לומדים יותר \u0003רב יהודה שליף מסאני ואתא מטרא\u0004 \u0005[היה מוריד את נעלו\u0006 בתחילת תענית על הגשמים \u0005ו\u0006מיד \u0005יורד גשם]\u0006 מפני צדקותו, \u0003ואנן צוחינן וליכא דמשגח בן\u0004 \u0005[ואנו צווחים ואין מי שמשגיח בנו]\u0006 כיון שאין אנו ראויים לכך. \u0003אלא הקדוש ברוך הוא ליבא בעי\u0004 \u0005[\u0006את \u0005הלב\u0006 הוא \u0005רוצה],\u0006 ומי שאין ליבו שלם אינו נחשב בעיני ה' על אף תורתו המרובה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וה' יראה ללבב\"\u0004 (שמואל א' טז, ז).","\u0003אמר רב משרשיא: דואג ואחיתופל לא הוו סברי שמעתא\u0004 \u0005[היו מבינים\u0006 את \u0005ההלכה].\u0006 \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר זוטרא: מאן דכתיב ביה\u0004 \u0005[מיהו שנאמר בו]\u0006 \u0003\"איה ספר איה שקל איה ספר את המגדלים\"\u0004 (ישעיה לג, יח), \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 ש\u0003לא הוו סברי שמעתא\u0004 \u0005[היו מבינים את ההלכה]?!\u0006 \u0003אלא\u0004 יש לומר ש\u0003לא הוה סלקא להו שמעתא אליבא דהלכתא\u0004 \u0005[היתה עולה להם השמועה על פי ההלכה],\u0006 שלא היו מגיעים לסיכום הדיון בדרכה של ההלכה הפסוקה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"סוד ה' ליראיו\"\u0004 (תהלים כה, יד), וכיון שלא היו יראי שמים לא הגיעו למרות חריפותם לפסק אמיתי.","\u0003אמר ר' אמי: לא מת דואג עד ששכח תלמודו, שנאמר: \"הוא ימות באין מוסר וברב אולתו ישגה\"\u0004 (משלי ה, כג). \u0003רב אשי אמר: נצטרע\u0004 דואג לפני מותו, \u0003שנאמר: \"הצמתה כל זונה ממך\"\u0004 (תהלים עג, כז).","ומנין שהפסוק רומז לצרעת — נאמר כאן לשון \"הצמתה\", ו\u0003כתיב התם\u0004 \u0005[נאמר שם]\u0006 לשון דומה \u0003\"לצמתת\"\u0004 (\"והארץ לא תימכר לצמיתות\". ויקרא כה, כג), \u0003ומתרגמינן\u0004 \u0005[ומתרגמים אנו]\u0006 מלה זו בארמית: \u0003לחלוטין. ו\u0004את ענין \"חלוטין\" אתה למד ממה ש\u0003תנן\u0004 \u0005[\u0006ש\u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין בין\u0004 מצורע \u0003מוסגר\u0004 (שעדיין לא החליט הכהן בדבר משמעות סימני הטומאה שבו) למצורע \u0003מוחלט\u0004 שטימאו הכהן סופית, \u0003אלא\u0004 דין \u0003פריעה ופרימה\u0004 בלבד. הרי שלשון \"חלוטין\" קשור לטומאת צרעת, וכך גם לשון \"צמיתות\", והצמתה.","\u0003(סימן\u0004 להלכות הבאות: \u0003שלשה, ראו וחצי וקראו).\u0004","\u0003אמר ר' יוחנן: שלשה מלאכי חבלה נזדמנו לו לדואג, אחד ששכח\u0004 (השכיח) \u0003תלמודו\u0004 ממנו, \u0003ואחד ששרף נשמתו, ואחד שפיזר עפרו בבתי כנסיות ובבתי מדרשות\u0004 להיות מדרס לרגלי צדיקים.","\u0003אמר ר' יוחנן: דואג ואחיתופל לא ראו זה את זה,\u0004 כי שניהם מתו בגיל צעיר, כאמור, \u0003דואג בימי שאול\u0004 היה כשהיה דוד נער, \u0003ואחיתופל בימי דוד\u0004 קרוב לסוף ימיו.","\u0003ואמר ר' יוחנן: דואג ואחיתופל לא חצו ימיהם,\u0004 שמתו לפני שהגיעו לשלושים וחמש שנה, מחצית \"ימי שנותינו בהם שבעים שנה\" (תהלים צ, י). \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003\"אנשי דמים ומרמה לא יחצו ימיהם\"\u0004 (תהלים נה, כד), \u0003כל שנותיו של דואג לא היו אלא שלשים וארבע, ושל אחיתופל אינן אלא שלשים ושלש.\u0004","\u0003ואמר ר' יוחנן: בתחלה קרא דוד לאחיתופל \"רבו\", ולבסוף קראו \"חבירו\", ולבסוף קראו \"תלמידו\".\u0004 כיצד? \u0003בתחלה קראו \"רבו\"\u0004 — שנאמר: \u0003\"ואתה אנוש כערכי אלופי ומידעי\"\u0004 (תהלים נה, יד), \"אלוף\" — רב הוא, המאלף תלמידו דעת, \u0003ולבסוף קראו \"חברו\"\u0004 שנאמר: \u0003\"אשר יחדו נמתיק סוד בבית אלהים נהלך ברגש\"\u0004 (תהלים נה, טו), \"יחדיו\" — משמע כחברים, \u0003ולבסוף קראו \"תלמידו\",\u0004 כאמור: \u0003\"גם איש שלומי אשר בטחתי בו\u0004"],["\u0003אוכל לחמי הגדיל עלי עקב\"\u0004 (תהלים מא, י), משמע שהוא מקבל ממנו, והוא תלמיד לדוד.","כיון שהוזכר אחיתופל, מסופר כל אותו מעשה כיצד השתלשלו הדברים שבא לידי מותו. \u0003אמר רב יהודה אמר רב: לעולם אל יביא אדם\u0004 את \u0003עצמו לידי נסיון, שהרי דוד מלך ישראל הביא עצמו לידי נסיון ונכשל. אמר לפניו: רבונו של עולם! מפני מה אומרים\u0004 בתפילה \u0003\"אלהי אברהם אלהי יצחק ואלהי יעקב\", ואין אומרים \"אלהי דוד\"? אמר\u0004 לו הקדוש ברוך הוא: \u0003אינהו מינסו לי, ואת לא מינסית לי\u0004 \u0005[הם היו מנוסים בפני, ואתה אינך מנוסה לפני].\u0006 \u0003אמר לפניו: רבונו של עולם בחנני ונסני,\u0004 \u0003שנאמר:\u0004 \u0003\"בחנני ה' ונסני\u0004 צרפה כליותי ולבי\u0003\"\u0004 (תהלים כו, ב),","\u0003אמר\u0004 לו הקדוש ברוך הוא: \u0003מינסנא לך\u0004 \u0005[אני אנסה אותך],\u0006 \u0003ועבידנא מילתא בהדך\u0004 \u0005[ועושה אני עוד דבר אחד],\u0006 \u0003דלדידהו\u0004 \u0005[שלהם,\u0006 לאבות\u0005],\u0006 \u0003לא הודעתינהו\u0004 \u0005[הודעתי\u0006 אותו \u0005להם]\u0006 במה אני עתיד לנסותם, \u0003ואילו\u0004 ביחס לך \u0003אנא קא מודענא\u0004 \u0005[אני מודיע]\u0006 \u0003לך דמנסינא לך\u0004 \u0005[שאני מנסה אותך]\u0006 \u0003בדבר ערוה. מיד \"ויהי לעת הערב ויקם דוד מעל משכבו\"\u0004 (שמואל ב' יא, ב),","\u0003אמר רב יהודה:\u0004 כיון ששמע דוד במה יהא נסיונו רצה לשמור עצמו מתאוה, ולכן \u0003הפך משכבו של לילה למשכבו של יום,\u0004 ששכב עם נשיו באותו יום כדי שלא יתאוה עוד, \u0003ונתעלמה ממנו הלכה: אבר קטן יש באדם,\u0004 זה ה\u0003משביעו\u0004 בתשמיש — הרי אברו \u0003רעב\u0004 ומשתוקק עוד, \u0003ו\u0004ה\u0003מרעיבו\u0004 — \u0003שבע\u0004 ולכן לא הועיל לו הדבר.","נאמר \u0003\"ויתהלך על גג בית המלך וירא אשה רחצת מעל הגג והאשה טובת מראה מאד\"\u0004 (שמואל ב' יא, ב), \u0003בת שבע הוה קא חייפא רישא תותי חלתא\u0004 \u0005[היתה חופפת\u0006 את \u0005ראשה מתחת,\u0006 מאחורי, \u0005כוורת]\u0006 והיתה מוסתרת מעיני הכל. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003שטן אידמי ליה כציפרתא\u0004 \u0005[נדמה לו\u0006 לדוד \u0005כציפור],\u0006 \u0003פתק ביה גירא\u0004 \u0005[ירה בו חץ],\u0006 \u0003פתקה לחלתא\u0004 \u0005[פגע\u0006 החץ \u0005בכוורת],\u0006 \u0003איגליה וחזייה\u0004 \u0005[גילה אותה,\u0006 את הכוורת, \u0005וראה אותה].\u0006","\u0003מיד: \"וישלח דוד וידרש לאשה ויאמר הלוא זאת בת שבע בת אליעם אשת אוריה החתי. וישלח דוד מלאכים ויקחה ותבוא אליו וישכב עמה והיא מתקדשת מטמאתה ותשב אל ביתה\"\u0004 (שמואל ב' יא, ג–ד), \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"בחנת לבי פקדת לילה צרפתני בל תמצא זמתי בל יעבר פי\"\u0004 (תהלים יז, ג), \u0003אמר: איכו זממא נפל בפומיה דמאן דסני לי\u0004 \u0005[ולוואי זמם,\u0006 רסן \u0005היה נופל בפיו של מי ששונא אותי,\u0006 כלומר, בפי\u0005],\u0006 \u0003ולא אמר כי הא מילתא\u0004 \u0005[הייתי אומר דבר כזה],\u0006 ולא הייתי נכשל בנסיון.","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"למנצח לדוד בה' חסיתי איך תאמרו לנפשי נודי הרכם צפר\"\u0004 (תהלים יא, א) — \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם! מחול לי על אותו עון\u0004 של בת שבע, \u0003שלא יאמרו\u0004 רשעים: \u0003הר שבכם,\u0004 גדול הדור, כדוד \u0003צפור נדדתו\u0004 והוציאה אותו מן העולם, שבשביל כך נכשל.","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"לך לבדך חטאתי והרע בעיניך עשיתי למען תצדק בדברך תזכה בשפטך\"\u0004 (תהלים נא, ו) — \u0003אמר דוד לפני הקדוש ברוך הוא: גליא וידיעא קמך דאי בעיא למכפייה\u0004 \u0005[שאילו הייתי רוצה לכפות]\u0006 את \u0003יצרי הוה כייפינא\u0004 \u0005[הייתי כופה]\u0006 אותו, \u0003אלא אמינא\u0004 \u0005[אמרתי]:\u0006 אחטא כדי ש\u0003לא לימרו עבדא זכי למריה\u0004 \u0005[העבד ניצח את אדוניו]\u0006 ועמד בנסיון, אף שה' אמר לו שלא יוכל לעמוד בו.","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"כי אני לצלע נכון ומכאובי נגדי תמיד\"\u0004 (תהלים לח, יח)? — \u0003ראויה היתה בת שבע בת אליעם לדוד מששת ימי בראשית,\u0004 שנאמר: \"כי אני לצלע (האשה) — נכון\", כלומר, מוכנה לו מראש, \u0003אלא שבאה אליו במכאוב. וכן תנא דבי\u0004 \u0005[שנה החכם בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: ראויה היתה לדוד בת שבע בת אליעם, אלא שאכלה פגה\u0004 (תאנת בוסר), כלומר, לפני הזמן. שראוי היה שימות אוריה קודם לכן, והיה דוד נושא אותה בהיתר.","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ובצלעי שמחו ונאספו נאספו עלי נכים ולא ידעתי קרעו ולא דמו\"\u0004 (תהלים לה, טו) — \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם, גלוי וידוע לפניך שאם היו קורעין בשרי לא היה דמי שותת,\u0004 (\"קרעו ולא דמו\"), שכחש בשרי ואבד דמי מרוב צומות שהתעניתי על עבירה זו,","\u0003ולא עוד אלא בשעה שהם\u0004 החכמים \u0003עוסקין ב\u0004הלכות \u0003ארבע מיתות בית דין, פוסקין\u0004 הם \u0003ממשנתן ואומרים לי,\u0004 כדי להזכירו ולביישו: \u0003דוד, הבא על אשת איש, מיתתו במה? אמרתי להם: הבא על אשת איש מיתתו בחנק,\u0004 אבל \u0003יש לו חלק לעולם הבא. אבל המלבין פני חבירו ברבים אין לו חלק לעולם הבא.\u0004","\u0003אמר רב יהודה אמר רב: אפילו בשעת חליו של דוד קיים שמנה עשרה עונות\u0004 לשמונה עשרה נשיו, שהיה צריך לבוא על כולן משום מצות עונה, \u0003שנאמר: \"יגעתי באנחתי אשחה בכל לילה מטתי בדמעתי ערשי אמסה\"\u0004 (תהלים ו, ז), שגם כשיגע ונאנח, עדיין \"אשחה... מיטתי\" (בלשון נקיה לתשמיש). \u0003ואמר רב יהודה אמר רב: בקש דוד לעבוד עבודה זרה\u0004 כאשר מרד בו אבשלום, \u0003שנאמר: \"ויהי דוד בא עד הראש אשר ישתחוה שם לאלהים\"\u0004 (שמואל ב' טו, לב), \u0003ואין\u0004 לשון \u0003\"ראש\" אלא\u0004 כינוי של \u0003עבודה זרה, שנאמר: \"והוא צלמא ראשה די דהב טב\"\u0004 \u0005[והוא הצלם ראשו של זהב טוב]\u0006 (דניאל ב, לב).","נאמר: \u0003\"והנה לקראתו חושי הארכי קרוע כתנתו ואדמה על ראשו\"\u0004 (שמואל ב' טו, לב), \u0003אמר לו\u0004 חושי \u0003לדוד, יאמרו: מלך שכמותך יעבוד עבודה זרה? אמר לו\u0004 דוד, ומה אם יאמרו: \u0003מלך שכמותי\u0004 שידעו בו שהוא צדיק \u0003יהרגנו בנו?! מוטב יעבוד עבודה זרה ואל יתחלל שם שמים בפרהסיא,\u0004 שמלך צדיק נהרג באופן זה. כי אם יעבוד עבודה זרה יאמרו הבריות שנענש דוד משום שעבד עבודה זרה.","\u0003אמר\u0004 לו חושי: \u0003מאי טעמא קנסיבת\u0004 \u0005[מה טעם נשאת]\u0006 לאשה \u0003יפת תואר,\u0004 אמו של אבשלום? \u0003אמר ליה\u0004 \u0005[לו]\u0006 דוד: \u0003יפת תואר רחמנא שרייה\u0004 \u0005[התורה התירה אותה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 חושי: ומדוע \u0003לא דרשת\u0004 את הכתובים ה\u0003סמוכין,\u0004 \u0003דסמיך ליה\u0004 \u0005[שסמוך לו]\u0006 למקרא המתיר נישואי יפת תואר נסמך הדין של \u0003\"כי יהיה לאיש בן סורר ומורה\"\u0004 (דברים כא, יח), ללמד: \u0003כל הנושא יפת תואר יש לו בן סורר ומורה.\u0004 ואם כן, מבינים הכל שבגלל טעם זה נולד לך בן רשע ומורד, שזה טבעו הרע, ואין עוד בכך חילול השם.","\u0003דרש ר' דוסתאי\u0004 ש\u0003מן\u0004 העיר \u0003בירי: למה דוד דומה?\u0004 — \u0003לסוחר כותי\u0004 שעומד על המקח ומוריד מן המחיר מעט מעט עד שמתרצה הקונה. כך \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם, \"שגיאות מי יבין\"\u0004 (תהלים יט, יב), שביקש מחילה על שגגות שעשה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ה': \u0003שביקי\u0004 \u0005[עזובים,\u0006 מחולים\u0005]\u0006 הם \u0003לך.\u0004 ביקש דוד עוד: \u0003\"ומנסתרות נקני\"\u0004 (תהלים יט, יב), כלומר, מחל לי על עבירות שעשיתי בסתר, אף שעשיתין במזיד, אמר לו ה': \u0003שביקי\u0004 \u0005[מחולים]\u0006 \u0003לך.\u0004 ביקש עוד \u0003\"גם מזדים חשך עבדך\"\u0004 (תהלים יט, יג), גם מדברים שבזדון מחול לי. אמר לו ה': \u0003שביקי\u0004 \u0005[עזובים,\u0006 מחולים\u0005]\u0006 הם \u0003לך.\u0004 ביקש דוד עוד: \u0003\"אל ימשלו בי אז איתם\"\u0004 (תהלים יט, יג), ש\u0003לא לישתעו\u0004 \u0005[ידברו]\u0006 \u0003בי רבנן\u0004 \u0005[חכמים]\u0006 ויספרו בגנותי. אמר לו ה': \u0003שביקי\u0004 \u0005[עזובים,\u0006 מחולים\u0005]\u0006 הם \u0003לך.\u0004","ביקש דוד \u0003\"ונקיתי מפשע רב\"\u0004 (תהלים יט, יג), \u0003שלא יכתב\u0004 כלל \u0003סרחוני,\u0004 אותו חטא, במקרא. \u0003אמר לו\u0004 ה': \u0003אי אפשר\u0004 לעשות כן, \u0003ומה\u0004 האות \u0003יו\"ד שנטלתי מ\u0004שמה של \u0003שרי\u0004 אשת אברהם כאשר ציויתי לקרוא שמה \"שרה\" \u0003עומד וצווח כמה שנים\u0004 מדוע הושמטה מן המקרא, \u0003עד שבא יהושע והוספתי לו\u0004 יו\"ד זו, \u0003שנאמר: \"ויקרא משה להושע בן נון יהושע\"\u0004 (במדבר יג, טז), \u0003כל הפרשה כולה\u0004 של חטאך שראוייה להיכתב במקרא, \u0003על אחת כמה וכמה\u0004 שאי אפשר להשמיטה.","נאמר שאמר דוד \u0003\"ונקיתי מפשע רב\"\u0004 (תהלים יט, יג), \u0003אמר לפניו: רבונו של עולם, מחול לי על אותו עון כולו! אמר\u0004 לו ה': \u0003כבר עתיד שלמה בנך לומר בחכמתו \"היחתה איש אש בחיקו ובגדיו לא תשרפנה. אם יהלך איש על הגחלים ורגליו לא תכוינה. כן הבא על אשת רעהו לא ינקה כל הנגע בה\"\u0004 (משלי ו, כז–כט). \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כל הכי נטרד ההוא גברא\u0004 \u0005[כך יטרד אותו האיש,\u0006 דוד\u0005]\u0006 עבור עוון זה, בלא תקנה כלל? \u0003אמר לו: קבל עליך יסורין\u0004 ויהיו אלה לך כפרה. \u0003קבל עליו.\u0004","\u0003אמר רב יהודה אמר רב: ששה חדשים נצטרע דוד, ונסתלקה הימנו\u0004 (ממנו) \u0003שכינה, ופירשו ממנו סנהדרין.\u0004 מנין ש\u0003נצטרע?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תחטאני באזוב ואטהר תכבסני ומשלג אלבין\"\u0004 (תהלים נא, ט), משמע שהוצרך לטהרה, כדין המצורע. \u0003נסתלקה הימנו שכינה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"השיבה לי ששון ישעך ורוח נדיבה תסמכני\"\u0004 (תהלים נא, יד). \u0003ופרשו ממנו סנהדרין\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ישובו לי יראיך\u0004 ויודעי עדותיך\u0003\"\u0004 (תהלים קיט, עט). שהיה זה \u0003ששה חדשים מנלן\u0004 \u0005[מנין לנו]?\u0006 — \u0003ד\u0004\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והימים אשר מלך דוד על ישראל ארבעים שנה\u0004"],["\u0003בחברון מלך שבע שנים ובירושלם מלך שלשים ושלש שנים\"\u0004 (מלכים א' ב, יא), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"בחברון מלך על יהודה שבע שנים וששה חדשים\u0004 ובירושלם מלך שלושים ושלוש שנה\u0003\"\u0004 (שמואל ב' ה, ה), \u0003והני\u0004 \u0005[ואותם]\u0006 \u0003ששה חדשים לא קחשיב\u0004 \u0005[אינו חושב]\u0006 בחשבון הכללי, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהיו ששה חדשים שלא נחשב בהם למלך משום ש\u0003נצטרע.\u0004","\u0003אמר לפניו\u0004 לאחר מכן: \u0003רבונו של עולם, מחול לי על אותו עון!\u0004 אמר לו ה': \u0003מחול לך.\u0004 וביקש דוד: אם כן \u0003\"עשה עמי אות לטובה ויראו שנאי ויבשו כי אתה ה' עזרתני ונחמתני\"\u0004 (תהלים פו, יז), שידעו הכל שנמחל עוון זה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בחייך איני מודיע, אבל אני מודיע בחיי שלמה בנך.\u0004","\u0003בשעה שבנה שלמה את בית המקדש ביקש להכניס ארון לבית קדשי הקדשים, דבקו שערים זה בזה\u0004 ולא היה יכול לפתחם. \u0003אמר עשרים וארבעה רננות\u0004 בתפילתו \u0003ולא נענה. אמר \"שאו שערים ראשיכם והנשאו פתחי עולם ויבוא מלך הכבוד. מי זה מלך הכבוד ה' עזוז וגבור ה' גבור מלחמה\"\u0004 (תהלים כד, ז–ח), \u0003ונאמר \"שאו שערים ראשיכם ושאו פתחי עולם ויבא מלך הכבוד\"\u0004 (תהלים כד, ט), \u0003ולא נענה.\u0004","\u0003כיון שאמר \"ה' אלהים אל תשב פני משיחך זכרה לחסדי דויד עבדך\"\u0004 (דברי הימים ב' ו, מב), \u0003מיד נענה\u0004 ונפתחו השערים. \u0003באותה שעה נהפכו פני שונאי דוד\u0004 שחורים מאכזבה \u0003כשולי\u0004 (תחתית של) \u0003קדירה, וידעו כל ישראל שמחל לו הקדוש ברוך הוא על אותו העו‍ן,\u0004 שהרי בזכותו נענה שלמה.","\u0003גחזי\u0004 שאין לו חלק לעולם הבא, מה עניינו? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וילך אלישע דמשק\"\u0004 (ראה מלכים ב' ח, ז), \u0003להיכא אזל\u0004 \u0005[להיכן הלך]?\u0006 ולשם מה הלך לשם? \u0003אמר ר' יוחנן: שהלך להחזיר\u0004 את \u0003גחזי בתשובה, ולא חזר. אמר לו\u0004 אלישע: \u0003חזור בך. אמר לו\u0004 גיחזי: \u0003כך מקובלני ממך: החוטא ומחטיא את הרבים אין מספיקין בידו לעשות תשובה.\u0004","\u0003מאי עבד\u0004 \u0005[מה עשה]\u0006 שהחטיא הוא את הרבים? \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אבן שואבת תלה לחטאת\u0004 (לעגל) \u0003ירבעם, והעמידה\u0004 על ידי כך \u0003בין שמים לארץ,\u0004 כדי שיחשבו הרואים שפורחת באויר בנס, ויהא זה חיזוק למאמינים בו. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 ש\u0003שם\u0004 קדוש \u0003חקק בפיה, והיתה מכרזת ואומרת\u0004 מכוח שם זה \u0003\"אנכי\" ו\"לא יהיה לך\",\u0004 והיו הבריות סבורים שהיא אלוה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 חטאו היה ש\u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003דחה מקמיה\u0004 \u0005[מלפניו],\u0006 שלא יבואו לאלישע ללמוד, \u0003שנאמר\u0004 לאחר מעשה גיחזי: \u0003\"ויאמרו בני הנביאים אל אלישע הנה נא המקום אשר אנחנו ישבים שם לפניך צר ממנו\"\u0004 (מלכים ב' ו, א), \u0003מכלל\u0004 הדבר אתה למד ש\u0003עד השתא\u0004 \u0005[עכשיו,\u0006 אז\u0005]\u0006 \u0003לא הוו פיישי\u0004 \u0005[היו מרובים]\u0006 ולא היה המקום \u0003צר\u0004 להם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לעולם תהא שמאל דוחה וימין מקרבת,\u0004 שלא לדחות לחלוטין את מי שחטא כדי שיוכל לחזור בו, \u0003לא כאלישע שדחפו לגחזי בשתי ידים\u0004 וגרם לו שיאבד את עולמו, \u0003ולא כיהושע בן פרחיא שדחפו לישו הנוצרי בשתי ידיו.\u0004","\u0003גחזי\u0004 מה עניינו? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר נעמן הואל קח ככרים ויפרץ בו ויצר ככרים כסף\u0004 בשני חרטים ושתי חליפות בגדים\u0003\"\u0004 (מלכים ב' ה, כג). \u0003\"ויאמר אליו אלישע מאין גחזי ויאמר לא הלך עבדך אנה ואנה. ויאמר אליו לא לבי הלך כאשר הפך איש מעל מרכבתו לקראתך העת לקחת את הכסף ולקחת בגדים וזיתים וכרמים וצאן ובקר ועבדים ושפחות\"\u0004 (מלכים ב' ה, כה —כו). אגב הבאת כתוב זה שואלים: \u0003ומי שקל כולי האי\u0004 \u0005[והאם לקח כל זה]?\u0006 הרי \u0003כסף ובגדים הוא דשקל\u0004 \u0005[שלקח]!\u0006","\u0003אמר ר' יצחק: באותה שעה היה אלישע יושב ודורש ב\u0004הלכות \u0003שמונה שרצים\u0004 המטמאים, וכך היה מעשה, \u0003נעמן שר צבא מלך ארם היה מצורע. אמרה ליה ההיא רביתא דאישתבאי מארעא ישראל\u0004 \u0005[אמרה לו נערה אחת שנשבתה מארץ ישראל]:\u0006 \u0003אי אזלת לגבי\u0004 \u0005[אם תלך אצל]\u0006 \u0003אלישע מסי לך\u0004 \u0005[ירפא אותך].\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אלישע: \u0003זיל\u0004 \u0005[לך]\u0006 \u0003טבול בירדן. אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003אחוכי קא מחייכת\u0004 \u0005[מצחק אתה]\u0006 \u0003בי\u0004 שמדבריך מובן שעל ידי כך אתרפא?! \u0003אמרי ליה הנהו דהוו בהדיה\u0004 \u0005[אמרו לו אלה שהיו עמו]:\u0006 \u0003מאי נפקא\u0004 \u0005[מה יוצא]\u0006 \u0003לך מינה\u0004 \u0005[מזה],\u0006 מה נפסד אתה בזה? \u0003זיל נסי\u0004 \u0005[לך ונסה].\u0006 \u0003אזל וטבל בירדנא, ואיתסי\u0004 \u0005[הלך וטבל בירדן, והתרפא].\u0006 \u0003אתא אייתי ליה\u0004 \u0005[בא והביא\u0006 \u0003לו]\u0004 לאלישע \u0003כל הני דנקיט\u0004 \u0005[אותם\u0006 דברים \u0005שלקח\u0006 עמו\u0005].\u0006 \u0003לא צבי לקבולי מיניה\u0004 \u0005[רצה לקבל ממנו].\u0006 \u0003גחזי איפטר מקמיה\u0004 \u0005[נפטר מלפני]\u0006 \u0003אלישע,\u0004 \u0003אזל שקל מאי דשקל ואפקיד\u0004 \u0005[לקח מה שלקח והפקיד].\u0006","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 גיחזי \u0003חזייה\u0004 \u0005[ראה]\u0006 \u0003אלישע לצרעת דהוה פרחה עלויה רישיה\u0004 \u0005[שהיתה פורחת על ראשו]\u0006 של גיחזי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אלישע: \u0003רשע! הגיע עת ליטול שכר שמנה שרצים,\u0004 שכיון שעסק בשמונה שרצים הזכיר שמונה מיני חפצים שרצה גיחזי לקנות בכסף זה שלקח, \u0003\"וצרעת נעמן תדבק בך ובזרעך לעולם ויצא מלפניו מצרע כשלג\"\u0004 (מלכים ב' ה, כז). נאמר \u0003\"וארבעה אנשים היו מצרעים פתח השער\"\u0004 (מלכים ב' ז, ג) בשומרון, \u0003אמר ר' יוחנן: גחזי ושלשה בניו\u0004 היו אלה, שהרי קילל אותו ואת זרעו.","ושואלים: והמעשה ב\u0003יהושע בן פרחיה מאי היא\u0004 \u0005[מה היה]?\u0006 ומספרים: \u0003כדקטלינהו\u0004 \u0005[כאשר הרגם]\u0006 \u0003ינאי מלכא לרבנן\u0004 \u0005[המלך את החכמים]\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 ברח \u0003יהושע בן פרחיה וישו\u0004 תלמידו \u0003לאלכסנדריא של מצרים. כי הוה שלמא\u0004 \u0005[כאשר נעשה שלום]\u0006 בין המלך ינאי וחכמים, \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003שמעון בן שטח\u0004 איגרת זו: \u0003מיני\u0004 \u0005[ממני]\u0006 \u0003ירושלים עיר הקדש ליכי\u0004 \u0005[לך]\u0006 \u0003אלכסנדריה של מצרים: אחותי, בעלי שרוי בתוכך ואנכי יושבת שוממה,\u0004 כלומר, ראש חכמי ישראל מצוי בניכר ואילו ירושלים זקוקה לו, הבין יהושע בן פרחיה,","\u0003קם אתא\u0004 \u0005[עמד ובא]\u0006 \u0003ואתרמי ליה ההוא אושפיזא\u0004 \u0005[ונזדמנה לו אכסניא אחת],\u0006 \u0003עבדו ליה יקרא טובא\u0004 \u0005[עשו לו\u0006 בה \u0005כבוד מרובה].\u0006 \u0003אמר\u0004 יהושע בן פרחיה: \u0003כמה יפה אכסניא זו! אמר ליה\u0004 \u0005[לו]\u0006 ישו: \u0003רבי,\u0004 אינה יפה כל כך, כי \u0003עיניה\u0004 של בעלת הבית \u0003טרוטות\u0004 (סגלגלות). \u0003אמר ליה\u0004 \u0005[לו]\u0006 יהושע בן פרחיה: \u0003רשע! בכך אתה עוסק?!\u0004 בהתבוננות בעיניה של אשת איש? \u0003אפיק ארבע מאה שיפורי ושמתיה\u0004 \u0005[הוציא ארבע מאות שופרות והחרימו].\u0006","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 ישו \u0005לפניו]\u0006 \u0003כמה זימנין\u0004 \u0005[פעמים],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קבלן\u0004 \u0005[קבלני\u0006 בתשובה\u0005]!\u0006 \u0003לא הוי קא משגח ביה\u0004 \u0005[היה\u0006 יהושע בן פרחיה \u0005משגיח בו]\u0006 לקבלו. \u0003יומא חד הוה קא קרי\u0004 \u0005[יום אחד היה\u0006 יהושע בן פרחיה \u0005קורא]\u0006 \u0003קריאת שמע, אתא לקמיה\u0004 \u0005[בא לפניו\u0006 ישו\u0005]\u0006 באותה בקשה, \u0003סבר לקבולי\u0004 \u0005[חשב לקבלו]\u0006 בפעם זו, \u0003אחוי ליה בידיה\u0004 \u0005[הראה לו בידו]\u0006 שימתין עד שיגמור להתפלל, \u0003הוא\u0004 ישו \u0003סבר\u0004 \u0005[חשב]:\u0006 \u0003מידחא קא דחי לי\u0004 \u0005[דוחה הוא אותי]\u0006 שוב, שלא הבין את הסימן שעשה לו. \u0003אזל זקף לבינתא\u0004 \u0005[הלך העמיד לבנה]\u0006 כסמל עבודה זרה \u0003והשתחוה לה. אמר ליה\u0004 \u0005[לו]\u0006 לאחר מכן יהושע בן פרחיה לישו: \u0003הדר\u0004 \u0005[חזור]\u0006 \u0003בך! אמר ליה\u0004 \u0005[לו]\u0006 ישו: \u0003כך מקובלני ממך: כל החוטא ומחטיא את הרבים אין מספיקין בידו לעשות תשובה. ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003ישו כישף והסית והדיח את ישראל\u0004 וכיון שהחטיא את הרבים אין לו דרך תשובה, ונמצא שאילולא הרחיקו יהושע בן פרחיה כל כך מתחילה, לא היה יוצא לתרבות רעה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן אלעזר: יצר\u0004 (תאוה) \u0003תינוק ואשה\u0004 — \u0003תהא שמאל דוחה וימין מקרבת,\u0004 שאין לקרבם מדי שלא יגיעו לחטא, ולא לרחקם מדי שמא יכשלו לגמרי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה חלאים חלה אלישע: אחד\u0004 כעונש על \u0003שגירה דובים בתינוקות\u0004 ואכלום (כמסופר במלכים ב' ב, כד–כה), \u0003ואחד\u0004 משום \u0003שדחפו לגחזי בשתי ידים\u0004 ולא נתן לו פתח תשובה, \u0003ואחד\u0004 החולי \u0003שמת בו, שנאמר: \"ואלישע חלה את חליו\u0004 אשר ימות בו\u0003\"\u0004 (מלכים ב' יג, יד), שמשמע שכבר היה חולה קודם לכן פעמים אחרות.","כיון שהוזכרה מיתתו של אלישע, מביאים מאמר זה: \u0003עד אברהם לא היה זקנה,\u0004 שלא ניכר מן הצעיר במראהו, \u0003כל דחזי\u0004 \u0005[\u0006מי \u0005שראה]\u0006 את \u0003אברהם אמר: האי\u0004 \u0005[זהו]\u0006 \u0003יצחק, כל דחזי\u0004 \u0005[\u0006מי \u0005שראה]\u0006 את \u0003יצחק אמר: האי\u0004 \u0005[זהו]\u0006 \u0003אברהם, בעא\u0004 \u0005[ביקש]\u0006 \u0003אברהם רחמי\u0004 \u0005[רחמים\u0006 התפלל\u0005]\u0006 \u0003דליהוי ליה\u0004 \u0005[שתהא לו]\u0006 \u0003זקנה, שנאמר: \"ואברהם זקן בא בימים\"\u0004 (בראשית כד, א), ולא נאמרה לשון זו קודם לכן. \u0003עד יעקב לא הוה\u0004 \u0005[היתה]\u0006 \u0003חולשא\u0004 של מחלה, \u0003בעא רחמי והוה\u0004 \u0005[ביקש\u0006 יעקב \u0005רחמים והיתה]\u0006 \u0003חולשא, שנאמר: \"ויאמר ליוסף הנה אביך חלה\"\u0004 (בראשית מח, א), ולא נזכרת קודם מחלה במקרא. \u0003עד אלישע לא הוה איניש חליש דמיתפח\u0004 \u0005[היה אדם חולה שמתרפא],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003אלישע ובעא רחמי ואיתפח\u0004 \u0005[וביקש רחמים והתרפא],\u0006 \u0003שנאמר: \"ואלישע חלה את חליו אשר ימות בו\"\u0004 (מלכים ב' יג, יד), והוא מקרה ראשון של אדם שנזכר בו מחלה, ולא מת בחוליו.","ועוד בענין העולם הבא. \u0003דור המבול אין להם חלק לעולם הבא, ואין עומדין בדין\u0004 לעתיד לבוא, \u0003שנאמר: \"לא ידון רוחי באדם לעלם\"\u0004 (בראשית ו, ג) — \u0003לא דין ו\u0004אף \u0003לא\u0004 תשוב להם ה\u0003רוח. דור הפלגה\u0004 שבנו את מגדל בבל \u0003אין להם חלק לעולם הבא, שנאמר: \"ויפץ ה' אתם משם על פני כל הארץ\"\u0004 (שם יא, ח), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ומשם הפיצם\u0004 ה' על פני כל הארץ\u0003\"\u0004 (בראשית יא, ט). וכך נפרש: \u0003\"ויפץ ה' אתם\"\u0004 — \u0003בעולם הזה, \"ומשם הפיצם ה' \"\u0004— \u0003לעולם הבא,\u0004 שגם משם נטרדו. \u0003אנשי סדום אין להם חלק לעולם הבא, שנאמר: \"ואנשי סדם רעים וחטאים לה' מאד\"\u0004 (בראשית יג, יג). ומפרשים: \u0003\"רעים\"\u0004 — \u0003בעולם הזה, \"וחטאים\"\u0004 — \u0003לעולם הבא, אבל עומדין בדין\u0004 ונידונים לדראון עולם.","\u0003ר' נחמיה אומר: אלו ואלו\u0004 גם אנשי סדום וגם אנשי המבול \u0003אין עומדין\u0004 \u0003בדין, שנאמר: \"על כן לא יקמו\u0004"],["\u0003רשעים במשפט וחטאים בעדת צדיקים\"\u0004 (תהלים א, ה). ומסבירים: \u0003\"על כן לא יקומו רשעים במשפט\"\u0004 — \u0003זה דור המבול\u0004 שנאמר בהם \"כי רבה רעת האדם\", \u0003\"וחטאים בעדת צדיקים\"\u0004 — \u0003אלו אנשי סדום,\u0004 שנאמר בהם \"רעים וחטאים\". \u0003אמרו לו\u0004 חכמים: אמנם \u0003אינם עומדין\u0004 לתחיה \u0003בעדת צדיקים, אבל עומדין בעדת רשעים\u0004 ונידונים כראוי להם.","\u0003מרגלים\u0004 שהוציאו את דיבת הארץ רעה \u0003אין להם חלק לעולם הבא, שנאמר: \"וימתו האנשים מוצאי דבת הארץ רעה במגפה לפני ה' \"\u0004(במדבר יד, לז). ומפרשים: \u0003\"וימתו\"\u0004 — \u0003בעולם הזה, \"במגפה\"\u0004 — \u0003לעולם הבא.\u0004","\u0003דור המדבר אין להם חלק לעולם הבא, ואין עומדין בדין, שנאמר: \"במדבר הזה יתמו ושם ימתו\"\u0004 (במדבר יד, לה), \"יתמו\" — בעולם הזה, \"ימותו\" — לעולם הבא, אלו \u0003דברי ר' עקיבא. ר' אליעזר אומר:\u0004 דור המדבר בעיקרם צדיקים היו, ו\u0003עליהם הוא אומר \"אספו לי חסידי כרתי בריתי עלי זבח\"\u0004 (תהלים נ, ה), שהם הם שכרתו ברית עם ה' לראשונה, ובודאי יהא להם שכר לעתיד.","\u0003עדת קרח אינה עתידה לעלות\u0004 אף בתחיית המתים, \u0003שנאמר: \"ותכס עליהם הארץ\"\u0004 (במדבר טז, לג) — לרמז למיתתם \u0003בעולם הזה, \"ויאבדו מתוך הקהל\"\u0004 (במדבר טז, לג) — \u0003לעולם הבא,\u0004 אלו \u0003דברי ר' עקיבא. ר' אליעזר אומר: עליהם הוא אומר \"ה' ממית ומחיה מוריד שאול ויעל\"\u0004 (שמואל א' ב, ו), ללמדנו שיש להם חלק לעולם הבא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003דור המבול אין להם חלק לעולם הבא, שנאמר: \"וימח את כל היקום אשר על פני האדמה\u0004 מאדם עד בהמה עד רמש ועד עוף השמים וימחו מן הארץ\u0003\"\u0004 (בראשית ז, כג). \u0003\"וימח את כל היקום\"\u0004 — \u0003בעולם הזה, \"וימחו מן הארץ\"\u0004 — \u0003לעולם הבא,\u0004 אלו \u0003דברי ר' עקיבא. ר' יהודה בן בתירא אומר:\u0004 בני דור המבול \u0003לא חיין ולא נדונין, שנאמר: \"לא ידון רוחי באדם לעלם\"\u0004 (בראשית ו, ג) — \u0003לא דין ולא רוח\u0004 תשוב בהם. \u0003דבר אחר: \"לא ידון רוחי\"\u0004 — \u0003שלא תהא נשמתן\u0004 (רוחי) \u0003חוזרת לנדנה\u0004 הוא הגוף.","\u0003ר' מנחם בר יוסף אומר: אפילו בשעה שהקדוש ברוך הוא מחזיר נשמות לפגרים מתים, נשמתן קשה\u0004 ומציקה \u0003להם בגיהנם, שנאמר: \"תהרו חשש תלדו קש רוחכם אש תאכלכם\"\u0004 (ישעיה לג, יא), שרוחכם (נשמתכם) היא תשרוף אתכם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003דור המבול לא נתגאו\u0004 וחטאו \u0003אלא בשביל טובה\u0004 מרובה \u0003שהשפיע להם הקדוש ברוך הוא, ומה כתיב\u0004 \u0005[נאמר]\u0006 \u0003בהם\u0004 להוכיח כי אך טוב היה חלקם — \u0003\"בתיהם שלום מפחד ולא שבט אלוה עליהם\"\u0004 (איוב כא, ט), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"שורו עבר ולא יגעל תפלט פרתו ולא תשכל\"\u0004 (איוב כא, י), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ישלחו כצאן עויליהם וילדיהם ירקדון\"\u0004 (איוב כא, יא), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"ישאו בתף וכנור וישמחו לקול עוגב\"\u0004 (איוב כא, יב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"יכלו ימיהם בטוב ושנותם בנעימים\"\u0004 (איוב לו, יא), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"וברגע שאול יחתו\"\u0004 (איוב כא, יג),","\u0003והיא,\u0004 אותה הצלחה, \u0003גרמה\u0004 להם \u0003שאמרו \"לאל סור ממנו ודעת דרכיך לא חפצנו. מה שדי כי נעבדנו ומה נועיל כי נפגע בו\"\u0004 (איוב כא, יד–טו). \u0003אמרו\u0004 בני דור המבול: \u0003כלום צריכין אנו לו אלא לטיפה של גשמים\u0004 שהוא מוריד משמים? ואולם הרי \u0003יש לנו נהרות ומעינות שאנו מסתפקין מהן\u0004 ואיננו יראים מפניו. \u0003אמר הקדוש ברוך הוא: בטובה\u0004 באותם מים רבים \u0003שהשפעתי להן, בה מכעיסין אותי? ו\u0004לכן \u0003בה אני דן אותם, שנאמר: \"ואני הנני מביא את המבול מים\"\u0004 (בראשית ו, יז).","\u0003ר' יוסי אמר: דור המבול לא נתגאו אלא בשביל גלגל העין שדומה למים,\u0004 שנשאו עיניהם וראו דברים שאינם שלהם ונטלום, \u0003שנאמר: \"\u0004ויראו בני האלהים את בנות האדם כי טובות הנה \u0003ויקחו להם נשים מכל אשר בחרו\"\u0004 (בראשית ו, ב), \u0003לפיכך דן אותן במים, שדומה לגלגל העין, שנאמר: \"נבקעו כל מעינות תהום רבה וארבות השמים נפתחו\"\u0004 (בראשית ז, יא), \"מעינות\" — לשון עיניים.","\u0003אמר ר' יוחנן: דור המבול ב\"רבה\" קלקלו\u0004 (חטאו) \u0003וב\"רבה\" נידונו,\u0004 כיצד? \u0003ב\"רבה\" קלקלו, שנאמר: \"וירא ה' כי רבה רעת האדם\"\u0004 (בראשית ו, ה), \u0003וב\"רבה\" נידונו, שנאמר: \"כל מעינות תהום רבה\"\u0004 (בראשית ז, יא). \u0003אמר ר' יוחנן: שלשה נשתיירו מהם\u0004 ממעינות התהום שנפתחו במבול והם נובעים עדיין מים רותחים כמי המבול, והם: \u0003בלועה דגדר, וחמי טבריא, ועיניא רבתי\u0004 \u0005[והמעין הגדול]\u0006 שב\u0003בירם.\u0004","על הנאמר \u0003\"כי השחית כל בשר את דרכו על הארץ\"\u0004 (בראשית ו, יב), \u0003אמר ר' יוחנן: מלמד שהרביעו\u0004 בני דור המבול \u0003בהמה על חיה, וחיה על בהמה, והכל על אדם, ואדם על הכל.\u0004 \u0003אמר ר' אבא בר כהנא: וכולם,\u0004 כל בעלי החיים, \u0003חזרו\u0004 בהם ואינם נזקקים אלא למינם \u0003חוץ מ\u0004העוף הקרוי \u0003תושלמי\u0004 שעדיין נרבע לשאינו מינו.","על הנאמר \u0003\"ויאמר\u0004 \u0003ה' לנח קץ כל בשר בא לפני\u0004 כי מלאה הארץ חמס מפניהם והנני משחיתם את הארץ\u0003\"\u0004 (בראשית ו, יג) \u0003אמר ר' יוחנן: בא וראה כמה גדול כחה\u0004 (עונשו) \u0003של חמס, שהרי דור המבול עברו על הכל,\u0004 על כל העבירות, \u0003ולא נחתם עליהם גזר דינם\u0004 להשמדה \u0003עד שפשטו ידיהם בגזל, שנאמר:\u0004 \u0003\"כי מלאה הארץ חמס מפניהם והנני משחיתם את הארץ\"\u0004 (בראשית ו, יג), \u0003וכתיב\u0004 \u0005[ו\u0006כן \u0005נאמר]\u0006 כיוצא בזה: \u0003\"החמס קם למטה רשע לא מהם ולא מהמונם ולא מהמהם ולא נה בהם\"\u0004 (יחזקאל ז, יא), ועל כך","\u0003אמר ר' אלעזר: מלמד שזקף עצמו\u0004 החמס \u0003כמקל\u0004 (\"החמס קם\") \u0003ועמד לפני הקדוש ברוך הוא ואמר לפניו: רבונו של עולם: לא מהם ולא מהמונם ולא מהמהם\u0004 (המתפרש: בני בניהם) \u0003ולא נה בהם,\u0004 שכל אלה אינם ראוים להתקיים.","\u0003ואף על נח נחתם גזר דין\u0004 לכלות עם בני דורו, \u0003שנאמר: \"ולא נח בהם\"\u0004 (וקורא \"נוח\" כמו \"נה\"). \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 \u0003אף על נח נחתך גזר דין, אלא שמצא חן בעיני ה'\u0004 ונתן לו נפשו בחסד, \u0003שנאמר: \"נחמתי כי עשיתם. ונח מצא חן בעיני ה' \"\u0004(בראשית ו' ז-ח).","נאמר \u0003\"וינחם ה' כי עשה את האדם בארץ\"\u0004 (בראשית ו', ו). \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר,\u0004 כך יש לפרש: \u0003אמר הקדוש ברוך הוא: יפה עשיתי שתקנתי להם קברות בארץ,\u0004 שכשם שנוצרו כך תהא להם מיתה וקבורה לכלותם. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003משמע?\u0004 כיצד משמע מן הכתובים דרשה זו? ומשיבים: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"וינחם ה' \", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"וינחם אותם וידבר על לבם\"\u0004 (בראשית נ, כא) משמע ש\"נחמה\" זו לשון נחת היא.","\u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]\u0006 שכך היתה הדרשה: \u0003לא יפה עשיתי שתקנתי להם קברות בארץ\u0004 שלא ראוי היה להם להיברא על מנת להשמד, וענין הדרשה — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"וינחם\", וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"וינחם ה' על הרעה אשר דבר לעשות לעמו\"\u0004 (שמות לב, יד), משמע ש\"נחמה\" זו לשון חרטה היא.","על הנאמר \u0003\"אלה תולדת נח נח איש צדיק תמים היה בדרתיו\"\u0004 (בראשית ו, ט), \u0003אמר ר' יוחנן: בדורותיו\u0004 היה צדיק לעומת אנשי דורו הרשעים, \u0003ולא בדורות אחרים. וריש לקיש אמר:\u0004 אם \u0003בדורותיו\u0004 למרות כל בני דורו היה צדיק, \u0003כל שכן\u0004 שהיה נחשב כצדיק אף \u0003בדורות אחרים.\u0004","\u0003אמר ר' חנינא: משל\u0004 לדברי \u0003ר' יוחנן למה הדבר דומה\u0004 — \u0003לחבית של יין שהיתה מונחת במרתף של חומץ, במקומה ריחה נודף,\u0004 שניכר ריחה היטב מריח החומץ, \u0003שלא במקומה\u0004 — \u0003אין ריחה נודף\u0004 שאיננה עריבה כל כך. \u0003אמר ר' אושעיא: משל דריש לקיש למה הדבר דומה\u0004 — \u0003לצלוחית של פלייטון\u0004 (בושם) \u0003שהיתה מונחת במקום הטנופת,\u0004 אם \u0003במקומה ריחה נודף,\u0004 למרות הריח הרע, \u0003וכל שכן במקום הבוסם.\u0004","נאמר \u0003\"וימח את כל היקום אשר על פני האדמה\u0004 מאדם עד בהמה עד רמש ועד עוף השמים\u0003\"\u0004 (בראשית ז, כג). ותמהים: \u0003אם אדם חטא, בהמה מה חטאה\u0004 שתאבד מן העולם?","ומשיבים: \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003משום\u0004 (בשם) \u0003ר' יהושע בן קרחה: משל לאדם שעשה חופה לבנו, והתקין כל מיני סעודה\u0004 לצורך החופה. \u0003לימים מת בנו\u0004 לפני החופה. מה עשה? — \u0003עמד ופזר את חופתו, אמר: כלום עשיתי\u0004 כל זאת \u0003אלא בשביל בני, עכשיו שמת\u0004 בני \u0003חופה למה לי? אף הקדוש ברוך הוא אמר: כלום בראתי בהמה וחיה אלא בשביל אדם, עכשיו שאדם חוטא\u0004 ודינו לאבדון, \u0003בהמה וחיה למה לי?\u0004","נאמר \u0003\"מכל אשר בחרבה מתו\"\u0004 (בראשית ז, כב), ויש לדייק מכאן: \u0003ולא דגים שבים,\u0004 שהם אינם בחרבה.","\u0003דרש ר' יוסי\u0004 ש\u0003מן\u0004 העיר \u0003קסרי: מאי דכתיב\u0004 \u0005[מה שנאמר]\u0006 \u0003\"קל הוא על פני מים תקלל חלקתם בארץ\u0004 לא יפנה דרך כרמים\u0003\"\u0004 (איוב כד, יח) \u0003מלמד שהיה נח הצדיק מוכיח בהם ואומר להם: עשו תשובה, ואם לאו\u0004 \u0005[לא]\u0006 תעשו תשובה \u0003הקדוש ברוך הוא מביא עליכם את המבול, ומקפה\u0004 (ומציף) \u0003נבלתכם על המים כזיקין\u0004 (כנאדות) מלאים רוח הצפים על המים, \u0003שנאמר: \"קל הוא על פני מים\", ולא עוד אלא שלוקחין מהם קללה לכל באי עולם,\u0004 שבלשון קללה אומרים: יהיו אלה כדור המבול, \u0003שנאמר: \"תקלל חלקתם בארץ\".\u0004","ומה שנאמר: \u0003\"לא יפנה דרך כרמים\"\u0004 (איוב כד, יח) הרי זה \u0003מלמד שהיו מפנים דרך כרמים,\u0004 כלומר, הולכים בדרכים רעות שלא במקום הראוי, \u0003אמרו לו\u0004 לנח: \u0003ומי מעכב\u0004 שיבוא המבול? \u0003אמר להם: פרידה אחת\u0004 עוד אחד \u0003יש לי להוציא מכם,\u0004 הוא מתושלח, שימות בזמנו ולא יראה את קללת המבול."],["אמרו לו: \u0003אם כן לא נפנה דרך כרמים\u0004 ויכולים אנו להמשיך ברשעותינו.","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"לפיד בוז לעשתות שאנן נכון למועדי רגל\"\u0004 (איוב יב, ה) — \u0003מלמד שהיה נח הצדיק מוכיח אותם, ואמר להם דברים שהם קשים\u0004 ובוערים \u0003כלפידים, והיו\u0004 הם \u0003מבזין אותו. אמרו לו: זקן, תיבה זו למה? אמר להם: הקדוש ברוך הוא מביא עליכם את המבול. אמרו\u0004 לו: \u0003מבול של מה? אם מבול של אש\u0004 — \u0003יש לנו דבר אחר ועליתה שמה\u0004 שעומד בפני האש. \u0003ואם\u0004 מבול \u0003של מים הוא מביא, אם מן הארץ הוא מביא\u0004 — \u0003יש לנו עששיות\u0004 (פחים) \u0003של ברזל שאנו מחפין בהם את הארץ\u0004 ואין המים יוצאים, \u0003ואם מן השמים הוא מביא, יש לנו דבר ועקב שמו, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003עקש שמו\u0004 שבו נספוג את המים.","\u0003אמר להם:\u0004 אם ירצה \u0003הוא מביא\u0004 מבול \u0003מבין עקבי רגליכם, שנאמר: \"נכון למועדי רגל\"\u0004 (איוב יב, ה), שמן הרגלים עצמן יוכל להוציא מבול, ואין דבר שיוכל לעמוד נגדם. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003מימי המבול קשים\u0004 היו וסמיכים \u0003כשכבת זרע, שנאמר: \"נכון למועדי רגל\"\u0004 (איוב יב, ה), ו\"רגל\" לשון נקיה הוא. \u0003אמר רב חסדא: ברותחין קלקלו בעבירה,\u0004 שהרי חטאו בהוצאת שכבת זרע שהיא חמה, \u0003וברותחין נידונו.\u0004 ורמז לדבר — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בסוף המבול: \u0003\"וישכו המים\"\u0004 (בראשית ח, א), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"וחמת המלך שככה\"\u0004 (אסתר ז, י), ונלמד שאף \"שככה\" שבמבול היתה שככה שלאחר חום.","נאמר: \u0003\"ויהי לשבעת הימים ומי המבול היו על הארץ\"\u0004 (בראשית ז, י). ושואלים: \u0003מה טיבם של שבעת הימים\u0004 הנוספים הללו?","\u0003אמר רב: אלו ימי אבילות של מתושלח\u0004 שמת אז, \u0003ללמדך שהספדן של צדיקים מעכבין את הפורענות לבא. דבר אחר: \"לשבעת\u0004 הימים \u0003\"\u0004— \u0003ש\u0004באותם הימים \u0003שינה עליהם הקדוש ברוך הוא סדר בראשית,\u0004 סדרו של עולם שנברא לשבעה ימים, \u0003שהיתה חמה יוצאת ממערב ושוקעת במזרח. דבר אחר: שקבע להם הקדוש ברוך הוא זמן גדול\u0004 של מאה ועשרים שנה לתשובה, \u0003ואחר כך\u0004 קבע \u0003זמן קטן\u0004 של שבעה ימים נוספים. \u0003דבר אחר: \"לשבעת הימים\"\u0004 — \u0003שהטעימם\u0004 באותם שבעת הימים עונג \u0003מעין העולם הבא\u0004 שהוא היום השביעי מאלפי שנות העולם \u0003כדי שידעו מה טובה מנעו מהן\u0004 על ידי חטאיהם.","נאמר שם: \u0003\"מכל הבהמה הטהורה תקח לך שבעה שבעה איש ואשתו\"\u0004 (בראשית ז ב). ושואלים: וכי \u0003אישות לבהמה מי אית\u0004 \u0005[האם יש]\u0006 \u0003לה?\u0004 ומה לשון \"אשתו\" בבהמה, וכי יש להם נשואין? \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מאותם שלא נעבדה בהם עבירה\u0004 של הרבעה בשאינו מינו, ולכן מודגש שכאן היה זה זוג.","ושואלים: \u0003מנא\u0004 \u0005[מניין]\u0006 \u0003ידע\u0004 נח מי הם בעלי החיים שלא נעבדה בהם עבירה? \u0003אמר רב חסדא: שהעבירן לפני התיבה, כל שהתיבה קולטתו\u0004 — \u0003בידוע שלא נעבדה בהם עבירה, וכל שאין התיבה קולטתו\u0004 — \u0003בידוע שנעבדה בה עבירה. ר' אבהו אמר:\u0004 נטל \u0003מאותן הבאין מאיליהן,\u0004 שנראה שמידי שמים נשלחו אליו, ובוודאי כשרים הם.","נאמר: \u0003\"עשה לך תבת עצי גפר\"\u0004 (בראשית ו, יד). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003גופר\u0004 זה? \u0003אמר רב אדא, אמרי\u0004 \u0005[אומרים]\u0006 \u0003דבי\u0004 \u0005[\u0006החכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא:\u0004 זה העץ הקרויה \u0003\"מבליגה\". ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהוא העץ הקרוי \u0003\"גולמיש\".\u0004","ולפרש את הכתוב \u0003\"צהר תעשה לתבה\"\u0004 (בראשית ו, טז), \u0003אמר ר' יוחנן, אמר לו הקדוש ברוך הוא לנח: קבע בה אבנים טובות ומרגליות כדי שיהיו מאירות לכם כצהרים.\u0004","נאמר: \u0003\"ואל אמה תכלנה מלמעלה\"\u0004 (בראשית ו, טז), ומסבירים את טעם הדבר: \u0003דבהכי\u0004 \u0005[שבכך]\u0006 \u0003הוא\u0004 האופן \u0003דקיימא\u0004 \u0005[שתעמוד]\u0006 ולא תיהפך במים, כאשר תהיה רחבה מלמטה וצרה מלמעלה.","ועל הכתוב \u0003\"תחתים שנים ושלשים תעשה\"\u0004 (בראשית ו, טז), \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003תחתיים לזבל, אמצעיים לבהמה, עליונים לאדם.\u0004","ועל הנאמר \u0003\"וישלח את הערב\u0004 ויצא יצוא ושוב עד יבושת המים מעל הארץ\u0003\"\u0004 (בראשית ח, ז), \u0003אמר ריש לקיש: תשובה ניצחת השיבו\u0004 ה\u0003עורב לנח,\u0004 שכשלא רצה לעזוב את התיבה \u0003אמר לו: רבך\u0004 הקדוש ברוך הוא \u0003שונאני, ואתה שנאתני,\u0004 והראיה ש\u0003רבך שונאני\u0004 — שצוה לקחת \u0003מן הטהורין שבעה\u0004 ואילו \u0003מן הטמאים\u0004 רק \u0003שנים, ואתה שנאתני\u0004 — \u0003שאתה מניח ממין שבעה\u0004 הטהורים ואינך שולח, \u0003ושולח ממין שנים, אם פוגע בי שר חמה או שר צנה\u0004 וממיתני וכי \u0003לא נמצא עולם חסר בריה אחת,\u0004 שהרי מין העורבים הוא רק זוג אחד. \u0003או שמא לאשתי אתה צריך\u0004 לתשמיש ולכן אתה משלח אותי מן התיבה.","\u0003אמר לו\u0004 נח: \u0003רשע! במותר לי,\u0004 באשתי שלי, \u0003נאסר לי, בנאסר לי\u0004 בבהמות וחיות \u0003לא כל שכן.\u0004","ושואלים: \u0003ומנלן\u0004 ש\u0003נאסרו\u0004 באי התיבה לבוא על נשיהם? ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובאת אל התבה אתה ובניך ואשתך ונשי בניך אתך\"\u0004 (בראשית ו, יח), שמבדיל בין גברים ונשים ללמד שאסורים בתשמיש, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"צא מן התבה אתה ואשתך ובניך ונשי בניך אתך\"\u0004 (בראשית ח, טז), שביציאתם מן התיבה רואים שהם מצורפים איש ואשתו יחד. \u0003ואמר ר' יוחנן: מיכן\u0004 (מכאן) \u0003אמרו שנאסרו בתשמיש המטה\u0004 בהיותם בתיבה והותרו ביציאתם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה\u0004 עברו ו\u0003שמשו\u0004 מיטתם \u0003בתיבה, וכולם לקו\u0004 בשל כך, והיו אלה \u0003כלב ועורב וחם\u0004 בן נח. \u0003כלב\u0004 ענשו ש\u0003נקשר\u0004 לבת זוגו לאחר תשמיש. \u0003עורב רק\u0004 (יורק), \u0003וחם לקה בעורו\u0004 ונהיה שחור.","על הנאמר: \u0003\"וישלח את היונה מאתו לראות הקלו המים\"\u0004 (בראשית ח, ח), \u0003אמר ר' ירמיה: מכאן שדירתן של עופות טהורים\u0004 בתיבה היתה \u0003עם הצדיקים,\u0004 שנאמר ששלחה מאתו — ממקומו שלו.","ועל הנאמר \u0003\"והנה עלה זית טרף בפיה\"\u0004 (בראשית ח, יא), \u0003אמר ר' אלעזר:\u0004 רמז הוא ש\u0003אמרה\u0004 ה\u0003יונה לפני הקדוש ברוך הוא: רבונו של עולם! יהיו מזונותי מרורים כזית ומסורים בידך, ואל יהיו מתוקים כדבש ומסורים ביד בשר ודם.\u0004 ושואלים: \u0003מאי משמע דהאי\u0004 \u0005[מה המשמעות,\u0006 מהיכן נובע \u0005ש\u0006לשון \u0005זה]\u0006 של \u0003\"טרף\" לישנא דמזוני\u0004 \u0005[לשון מזונות]\u0006 \u0003הוא?\u0004 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"הטריפני לחם חקי\"\u0004 (משלי ל, ח).","ועל הנאמר \u0003\"למשפחותיהם יצאו מן התבה\"\u0004 (בראשית ח, יט), \u0003אמר ר' יוחנן: למשפחותם ולא הם,\u0004 כי מקצת מבעלי החיים שנכנסו מתו במשך השנה וצאצאיהם הם שיצאו.","מסופר ש\u0003אמר רב חנא בר ביזנא: אמר ליה\u0004 \u0005[לו]\u0006 \u0003אליעזר\u0004 עבד אברהם \u0003לשם רבא\u0004 \u0005[הגדול]\u0006 בן נח: \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"למשפחתיהם יצאו מן התבה\" אתון היכן הויתון\u0004 \u0005[אתם היכן הייתם]\u0006 ובמה עסקתם? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003צער גדול היה לנו בתיבה\u0004 לטפל בכל בעלי החיים, \u0003בריה שדרכה להאכילה ביום\u0004 — \u0003האכלנוה ביום, שדרכה להאכילה בלילה\u0004 — \u0003האכלנוה בלילה. האי זקיתא\u0004 \u0005[זיקית זו]\u0006 \u0003לא הוה ידע\u0004 \u0005[היה יודע]\u0006 \u0003אבא מה\u0004 היא \u0003אכלה\u0004 \u0005[אוכלת].\u0006 \u0003יומא חד הוה יתיב וקא פאלי רמונא\u0004 \u0005[יום אחד היה יושב\u0006 אבא \u0005וקולף רמון],\u0006 \u0003נפל תולעתא מינה\u0004 \u0005[תולעת ממנה]\u0006 ו\u0003אכלה\u0004 אותה הזיקית. \u0003מיכן ואילך הוה גביל\u0004 \u0005[היה לש]\u0006 \u0003לה חיזרא, כי מתלע אכלה\u0004 \u0005[מיני עשבים,\u0006 ו\u0005כאשר היו מתליעים, היתה אוכלת].\u0006","\u0003אריא\u0004 \u0005[האריה]\u0006 — \u0003אישתא זינתיה\u0004 \u0005[הקדחת זנה אותו],\u0006 שהיה לו חום ולא הוצרך לאכול אז. ש\u0003אמר רב: לא בציר משיתא\u0004 \u0005[פחות משישה]\u0006 ימים \u0003ולא טפי מתריסר\u0004 \u0005[יותר משנים עשר]\u0006 יום \u0003זינא אישתא\u0004 \u0005[זנה הקדחת],\u0006 שאין אדם נזקק לאוכל וניזון מהשומן של עצמו. מסופר: העוף הקרוי \u0003אורשינה אשכחיניה\u0004 \u0005[מצאו]\u0006 \u0003אבא דגני בספנא דתיבותא\u0004 \u0005[ש\u0006הוא \u0005שוכב בצד התיבה]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא בעית מזוני\u0004 \u0005[רוצה אתה מזון]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזיתיך דהות טרידא\u0004 \u0005[ראיתיך שאתה טרוד],\u0006 ולכך \u0003אמינא\u0004 \u0005[אמרתי]\u0006 \u0003לא אצערך,\u0004 שאבקש גם אני אוכל. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יהא רעוא\u0004 \u0005[יהי רצון]\u0006 ש\u0003לא תמות.\u0004 וכך נתקיים בו מה \u0003שנאמר: \"ואמר עם קני אגוע וכחול ארבה ימים\"\u0004 (איוב כט, יח), והחול הנזכר במקרא הוא העוף הקרוי \"אורשינה\".","\u0003אמר רב חנה בר לואי, אמר שם רבא\u0004 \u0005[הגדול]\u0006 בן נח \u0003לאליעזר\u0004 עבד אברהם: \u0003כי אתו עלייכו\u0004 \u0005[כאשר באו עליכם]\u0006 \u0003מלכי מזרח ומערב,\u0004 ארבעת המלכים הגדולים שבהם נלחם אברהם, \u0003אתון היכי עבידיתו\u0004 \u0005[אתם מה עשיתם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אייתי\u0004 \u0005[הביא]\u0006 \u0003הקדוש ברוך הוא\u0004 את \u0003אברהם ואותביה מימיניה\u0004 \u0005[והושיבו מימנו],\u0006 \u0003והוה שדינן עפרא והוו חרבי, גילי והוי גירי\u0004 \u0005[היינו זורקים עפר והוא\u0006 נעשה \u0005חרבות,\u0006 משליכים \u0005קש והוא\u0006 נעשה \u0005חיצים],\u0006 \u0003שנאמר: \"לדוד מזמור נאם ה' לאדני שב לימיני עד אשית איביך הדם לרגליך\"\u0004 (תהלים קי, א), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"מי העיר ממזרח צדק יקראהו לרגלו יתן לפניו גוים ומלכים ירד יתן כעפר חרבו כקש נדף קשתו\"\u0004 (ישעיה מא, ב).","אגב מעשה זה מסופר: \u0003נחום איש גם זו הוה\u0004 \u0005[היה]\u0006 \u0003רגיל\u0004 ש\u0003כל\u0004 מה \u0003דהוה סלקא ליה אמר\u0004 \u0005[שהיה עולה בו,\u0006 קורה לו, היה \u0005אומר]\u0006 \u0003\"גם זו לטובה\". יומא חד בעו\u0004 \u0005[יום אחד היו צריכים]\u0006 \u0003ישראל לשדורי דורון\u0004 \u0005[לשלוח מתנה]\u0006 \u0003לקיסר, אמרי\u0004 \u0005[אמרו]:\u0006 \u0003בהדי\u0004 \u0005[בידי]\u0006"],["\u0003מאן נשדר\u0004 \u0005[מי נשלח\u0006 את הדורון\u0005],\u0006 והחליטו \u0003נשדר בהדי\u0004 \u0005[נשלח בידי]\u0006 \u0003נחום איש גם זו\u0004 לפי ש\u0003מלומד\u0004 (רגיל) \u0003בנסים הוא,\u0004 שמתרחשים לו ניסים רבים.","\u0003כי מטא לההוא דיורא, בעא למיבת\u0004 \u0005[כאשר בא לבית אחד, רצה ללון].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 בעלי הבית: \u0003מאי איכא בהדך\u0004 \u0005[מה יש אתך]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003קא מובילנא כרגא\u0004 \u0005[אני מוביל\u0006 את \u0005המס]\u0006 \u0003לקיסר.\u0004 \u0003קמו בליליא, שרינהו לסיפטיה, ושקלו\u0004 \u0005[עמדו בלילה, פתחו את ארגזו, והוציאו]\u0006 את \u0003כל דהוה גביה ומלנהו עפרא\u0004 \u0005[שהיה בתוכו ומלאו אותו בעפר].\u0006 \u0003כי מטא להתם, אישתכח עפרא\u0004 \u0005[כאשר הגיע לשם,\u0006 לקיסר, \u0005נמצא\u0006 שיש בידו \u0005עפר],\u0006 \u0003אמר\u0004 הקיסר: \u0003אחוכי קא מחייכי\u0004 \u0005[צוחקים]\u0006 \u0003בי יהודאי\u0004 \u0005[היהודים]\u0006 לתת לי מתנה כזו, \u0003אפקוהו למקטליה\u0004 \u0005[הוציאוהו ליהרג],\u0006 \u0003אמר\u0004 נחום: \u0003\"גם זו לטובה\". אתא\u0004 \u0005[בא]\u0006 \u0003אליהו\u0004 הנביא \u0003ואידמי להו כחד מינייהו\u0004 \u0005[ונדמה להם כאחד מהם],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דילמא האי עפרא מעפרא\u0004 \u0005[שמא עפר זה מעפרו]\u0006 של \u0003אברהם אבינו הוא דהוה שדי עפרא הוו חרבי, גילי הוו גירי\u0004 \u0005[שהיה זורק עפר, נהיה חרבות, קש נהיה חיצים].\u0006 \u0003בדוק ואשכחו הכי\u0004 \u0005[בדקו ומצאו שכך הוא]\u0006.","\u0003הוה מחוזא\u0004 \u0005[היה מחוז]\u0006 ש\u0003לא הוו קא יכלי ליה למיכבשיה\u0004 \u0005[היו יכולים לכבוש אותו],\u0006 \u0003שדו מההוא עפרא עליה וכבשוה\u0004 \u0005[זרקו מאותו עפר עליו וכבשוהו].\u0006 כיון שראו כך שמחו במתנתו של נחום איש גם זו, וכאות תודה \u0003עיילוהו לבי גנזא\u0004 \u0005[הכניסוהו לבית האוצר],\u0006 \u0003אמרי\u0004 \u0005[\u0006ו\u0005אמרו]\u0006 לו: \u0003שקול דניחא\u0004 \u0005[קח\u0006 מה \u0005שנוח]\u0006 \u0003לך.\u0004 \u0003מלייה לסיפטא דהבא\u0004 \u0005[מילא את ארגזו זהב].\u0006 \u0003כי הדר אתא\u0004 \u0005[כאשר חזר\u0006 ו\u0005בא]\u0006 \u0003אמרו ליה הנך דיורי\u0004 \u0005[לו אותם דיירים]:\u0006 \u0003מאי אמטית לבי מלכא\u0004 \u0005[מה הבאת לבית המלך]?\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאי דשקלי מהכא אמטאי להתם\u0004 \u0005[מה שלקחתי מכאן הבאתי לשם].\u0006 חשבו הם שעפר ביתם יש בו סגולה מיוחדת. \u0003שקלי אינהו אמטו להתם, קטלינהו להנך דיורי\u0004 \u0005[לקחו הם\u0006 מן העפר \u0005הביאו לשם\u0006 לקיסר, ומצאו שאין הוא מועיל \u0005והרגו את הדיירים ההם].\u0006","שנינו במשנה ש\u0003דור הפלגה אין להם חלק לעולם הבא.\u0004 ושואלים: \u0003מאי עבוד\u0004 \u0005[מה\u0006 חטא \u0005עשו]?\u0006 שהרי לא נתפרש עוונם בתורה. \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 בני \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא,\u0004 כך אמרו בוני המגדל: \u0003נבנה מגדל, ונעלה לרקיע, ונכה אותו בקרדומות כדי שיזובו מימיו. מחכו עלה במערבא\u0004 \u0005[היו צוחקים על כך בארץ ישראל]\u0006 שלא קבלו הסבר זה: \u0003אם כן ליבנו אחד בטורא\u0004 \u0005[שיבנו\u0006 מגדל \u0005אחד בהר]\u0006 במקום גבוה, ומדוע בנוהו בבקעה דווקא?","\u0003אלא אמר ר' ירמיה בר אלעזר: נחלקו לשלש כיתות, אחת אומרת: נעלה ונשב שם, ואחת אומרת: נעלה ונעבוד\u0004 שם \u0003עבודה זרה, ואחת אומרת: נעלה ונעשה מלחמה. זו שאומרת \"נעלה ונשב שם\"\u0004 — \u0003הפיצם ה', וזו שאומרת \"נעלה ונעשה מלחמה\"\u0004 — \u0003נעשו קופים ורוחות ושידים ולילין\u0004 (מיני שדים), \u0003וזו שאומרת \"נעלה ונעבוד עבודה זרה\"\u0004 — בהם נתקיים \u0003\"כי שם בלל ה' שפת כל הארץ\"\u0004 (בראשית יא, ט).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' נתן אומר: כולם,\u0004 כל בוני המגדל בכתות השונות, \u0003לשם עבודה זרה נתכוונו,\u0004 ומנין אתה למד זאת — \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"\u0004ו\u0003נעשה לנו שם\"\u0004 (בראשית יא, ד), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ושם אלהים אחרים לא תזכירו\"\u0004 (שמות כג, יג) \u0003מה להלן\u0004 \"שם אלהים אחרים\" — \u0003עבודה זרה\u0004 הוא, \u0003אף כאן\u0004 \"שם\" — \u0003עבודה זרה.\u0004","\u0003אמר ר' יוחנן: מגדל\u0004 זה \u0003שליש\u0004 העליון \u0003נשרף, שליש\u0004 ממנו \u0003נבלע\u0004 באדמה, ו\u0003שליש\u0004 האמצעי \u0003קיים. אמר רב: אויר מגדל משכח,\u0004 שכל השוהה שם שוכח תלמודו, לפי שבגללו באה שכחה לעולם. \u0003אמר רב יוסף: בבל ובורסיף\u0004 הסמוכה לה \u0003סימן רע לתורה.\u0004 ושואלים: מה טעם השם \u0003\"בורסיף\"? אמר רב אסי: בור שאפי\u0004 \u0005[בור ריק]\u0006 שאין בו עוד כל תוכן.","שנינו במשנה ש\u0003אנשי סדום אין להם חלק לעולם הבא וכו'. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אנשי סדום אין להם חלק לעולם הבא, שנאמר: \"ואנשי סדם רעים וחטאים לה' מאד\"\u0004 (בראשית יג, יג) \u0003\"רעים\"\u0004 — \u0003בעולם הזה, \"וחטאים\"\u0004 — \u0003לעולם הבא.\u0004","\u0003אמר רב יהודה: \"רעים\"\u0004 — משמע שעושים עבירות \u0003בגופן, \"וחטאים\"\u0004 — \u0003בממונם.\u0004 וראיה לדבר ש\u0003\"רעים\"\u0004 פירושו \u0003בגופן\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדבר יוסף אל אשת פוטיפר: \u0003\"ואיך אעשה הרעה הגדלה הזאת וחטאתי לאלהים\"\u0004 (בראשית לט, ט). \u0003\"וחטאים\"\u0004 משמעו \u0003בממונם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ורעה עינך באחיך האביון ולא תתן לו... \u0003והיה בך חטא\"\u0004 (דברים טו, ט), \u0003\"לה' \"\u0004— \u0003זו ברכת\u0004 (קללה, בלשון נקיה) \u0003השם, \"מאד\"\u0004 — \u0003שמתכוונים וחוטאים\u0004 ואינם עושים בשגגה או מפני התאוה.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנו]:\u0006 \u0003\"רעים\"\u0004 — \u0003בממונם, \"וחטאים\"\u0004 — \u0003בגופן, \"רעים\"\u0004 — \u0003בממונם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ורעה עינך באחיך האביון\"\u0004 (בראשית לט, ט), \u0003\"וחטאים\"\u0004 — \u0003בגופן, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וחטאתי לאלהים\"\u0004 (בראשית לט, ט). \u0003\"לה' \"\u0004— \u0003זו ברכת השם, \"מאד\"\u0004 — \u0003זו שפיכות דמים, שנאמר: \"וגם דם נקי שפך מנשה הרבה מאד\"\u0004 (מלכים ב' כא, טז).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אנשי סדום לא נתגאו\u0004 בעצמם וחטאו \u0003אלא בשביל טובה\u0004 יתירה \u0003שהשפיע להם הקדוש ברוך הוא, ומה כתיב\u0004 \u0005[נאמר]\u0006 \u0003בהם\u0004 — \u0003\"ארץ ממנה יצא לחם ותחתיה נהפך כמו אש. מקום ספיר אבניה ועפרת זהב לו. נתיב לא ידעו עיט ולא שזפתו עין איה. לא הדריכוהו בני שחץ לא עדה עליו שחל\"\u0004 (איוב כח, ה-ח). ומדובר שם בסדום, כאמור: \"בחלמיש שלח ידו הפך משורש הרים\" (איוב כח, ט).","\u0003אמרו\u0004 אנשי סדום: \u0003וכי מאחר שארץ ממנה יצא לחם ועפרת זהב לו\u0004 הלא יש לנו כל צרכינו ויותר, \u0003למה לנו עוברי דרכים? שאין באים אלינו אלא לחסרינו מממוננו. בואו ונשכח תורת רגל מארצנו\u0004 שלא יבוא איש אלינו, \u0003שנאמר: \"פרץ נחל מעם גר הנשכחים מני רגל דלו מאנוש נעו\"\u0004 (איוב כח, ד).","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"עד אנה תהותתו על איש תרצחו כלכם כקיר נטוי גדר הדחויה\"\u0004 (תהלים סב, ד) — \u0003מלמד שהיו\u0004 אנשי סדום \u0003נותנין עיניהן בבעלי ממון, ומושיבין אותו אצל קיר נטוי\u0004 (עומד ליפול) \u0003ודוחין\u0004 (דוחפים ומפילים) \u0003אותו עליו,\u0004 ונהרג, \u0003ובאים ונוטלין את ממונו.\u0004","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"חתר בחשך בתים יומם חתמו למו לא ידעו אור\"\u0004 (איוב כד, טז) — \u0003מלמד שהיו נותנים עיניהם בבעלי ממון,\u0004 והיו \u0003מפקידים אצלו אפרסמון\u0004 שריחו נודף ביותר \u0003ומניחים אותו\u0004 בעלי הבתים \u0003בבית גנזיהם, לערב\u0004 היו \u0003באים\u0004 המפקידים \u0003ומריחין אותו\u0004 (את האפרסמון)\u0003.\u0004 \u0003ככלב\u0004 היכן הוא טמון, \u0003שנאמר: \"ישובו לערב יהמו ככלב ויסובבו עיר\"\u0004 (תהלים נט, ז), \u0003ובאים וחותרים שם,\u0004 שהרי נודע להם על ידי כך היכן בית גנזיו של העשיר, \u0003ונוטלין אותו ממון.\u0004","ונאמר שם \u0003\"ערום ילינו מבלי לבוש ואין כסות בקרה\"\u0004 (איוב כד, ז), וכן \u0003\"חמור יתומים ינהגו יחבלו שור אלמנה\"\u0004 (איוב כד, ג), וכן \u0003\"גבלות ישיגו עדר גזלו וירעו\"\u0004 (איוב כד, ב), וכן \u0003\"והוא לקברות יובל ועל גדיש ישקוד\"\u0004 (איוב כא, לב).","\u0003דרש ר' יוסי בציפורי\u0004 וסיפר בתוך דבריו כיצד היו גונבים בסדום. \u0003אחתרין ההיא ליליא תלת דמאה מחתרתא\u0004 \u0005[נחפרו באותו לילה שלש מאות מחתרות]\u0006 \u0003בציפורי\u0004 על פי עצות אלו. \u0003אתו וקא מצערי ליה\u0004 \u0005[באו\u0006 בעלי הבתים \u0005וצערו אותו],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003יהבית אורחיה לגנבי\u0004 \u0005[נתת דרך לגנבים]\u0006 לגנוב! \u0003אמר להו: מי הוה ידענא דאתו גנבי\u0004 \u0005[וכי ידעתי שאתם גנבים]\u0006 שכך תהא התוצאה של דרשתי. בדרך אגב מסופר: \u0003כי קא נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' יוסי שפעי\u0004 \u0005[שפעו]\u0006 \u0003מרזבי\u0004 העיר \u0003ציפורי דמא\u0004 \u0005[דם]\u0006 מתוך צער העולם עליו.","ולענין סדום מה רעות עשו, \u0003אמרי\u0004 \u0005[אמרו]\u0006 בני סדום: \u0003דאית ליה חד תורא\u0004 \u0005[\u0006מי שיש \u0005לו שור אחד]\u0006 \u0003—\u0004 \u0003מרעי חד יומא\u0004 \u0005[ירעה\u0006 את עדרי העיר \u0005יום אחד],\u0006 \u0003דלית ליה\u0004 \u0005[\u0006מי \u0005שאין לו]\u0006 — \u0003לירעי תרי יומי\u0004 \u0005[ירעה\u0006 את עדרי העיר \u0005שני ימים].\u0006 וסיפרו: \u0003ההוא יתמא בר ארמלתא הבו ליה תורי למרעיה, אזל שקלינהו וקטלינהו\u0004 \u0005[יתום אחד בן אלמנה נתנו לו שוורים לרעות, הלך לקח אותם והרג אותם]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 היתום לבני סדום:"],["\u0003דאית ליה תורא\u0004 \u0005[\u0006מי \u0005שיש לו שור]\u0006 — \u0003נשקול חד משכא\u0004 \u0005[יטול עור אחד],\u0006 \u0003דלית ליה תורא\u0004 \u0005[\u0006מי \u0005שאין לו שור]\u0006 — \u0003נשקול תרי משכי\u0004 \u0005[יטול שני עורות].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 בני סדום ליתום: \u0003מאי האי\u0004 \u0005[מה זה]\u0006 מה טעם בדברים אלה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003סוף דינא\u0004 \u0005[הדין]\u0006 \u0003כתחילת דינא\u0004 \u0005[הדין];\u0006 \u0003מה תחילת דינא\u0004 \u0005[דין],\u0006 \u0003דאית ליה תורא\u0004 \u0005[\u0006מי \u0005שיש לו שור\u0006 אחד\u0005]\u0006 \u0003—\u0004 \u0003מרעי חד יומא\u0004 \u0005[ירעה\u0006 את עדרי העיר \u0005יום אחד],\u0006 \u0003דלית ליה תורא\u0004 \u0005[\u0006מי \u0005שאין לו שור]\u0006 — \u0003לירעי תרי יומי\u0004 \u0005[ירעה\u0006 את עדרי העיר \u0005שני ימים].\u0006 \u0003אף סוף דינא\u0004 \u0005[הדין],\u0006 \u0003דאית ליה חד תורא\u0004 \u0005[\u0006מי \u0005שיש לו שור אחד]\u0006 — \u0003לשקול חד\u0004 \u0005[יטול אחד],\u0006 \u0003דלית ליה תורא\u0004 \u0005[\u0006מי \u0005שאין לו שור]\u0006 — \u0003לשקול תרי\u0004 \u0005[יטול שנים].\u0006","ועוד גזרו בסדום: מי ש\u0003עבר במברא\u0004 \u0005[במעבורת]\u0006 — \u0003ניתיב חד זוזא\u0004 \u0005[יתן,\u0006 ישלם \u0005זוז אחד],\u0006 מי ש\u0003לא עבר במברא\u0004 \u0005[במעבורת],\u0006 אלא בתוך הנהר — \u0003ניתיב תרי\u0004 \u0005[שיתן שנים].\u0006 \u0003דהוה ליה תורא דלבני, אתי כל חד וחד שקיל חדא\u0004 \u0005[\u0006מי \u0005שהיתה לו שורת אבנים,\u0006 היה \u0005בא כל אחד ואחד ולוקח אחת]\u0006 מהן, \u0003אמר ליה\u0004 \u0005[\u0006ו\u0005אומר לו]:\u0006 \u0003אנא חדא דשקלי\u0004 \u0005[אני אחת\u0006 בלבד \u0005לקחתי],\u0006 עד שנטלו הכל. \u0003דהוה שדי תומי\u0004 \u0005[\u0006מי \u0005שהיה מניח שומים]\u0006 \u0003או שמכי\u0004 \u0005[בצלים]\u0006 ליבשם, \u0003אתו\u0004 \u0005[היו באים],\u0006 \u0003כל חד וחד שקיל חדא אמר ליה\u0004 \u0005[אחד ואחד לוקח אחד\u0006 ו\u0005אומר לו]:\u0006 \u0003אנא חדא דשקלי\u0004 \u0005[אני\u0006 רק שום \u0005אחד לקחתי],\u0006 ובוודאי לא תקפיד על דבר קטן כל כך.","\u0003ארבע דייני\u0004 \u0005[דיינים]\u0006 \u0003היו בסדום\u0004 ושמותיהם לפי מעשיהם: \u0003שקראי\u0004 \u0005[שקרן]\u0006 \u0003ושקרוראי\u0004 \u0005[שקרני]\u0006 \u0003זייפי\u0004 \u0005[זייפן]\u0006 \u0003ומצלי דינא\u0004 \u0005[מטה דין].\u0006 ואלה תקנות שתיקנו: \u0003דמחי ליה לאיתתא דחבריה ומפלא ליה\u0004 \u0005[המכה את אשת חבירו והיתה מפילה\u0006 את עוברה\u0005]\u0006 \u0003אמרי ליה\u0004 \u0005[היו אומרים לו]\u0006 לבעל האשה: \u0003יהבה ניהליה דניעברה ניהליך\u0004 \u0005[תן\u0006 את האשה \u0005לו,\u0006 למכה, \u0005שיעבר אותה בשבילך\u0006 שנית\u0005].\u0006 \u0003דפסיק ליה לאודנא דחמרא דחבריה\u0004 \u0005[\u0006מי \u0005שחתך את אוזן חמורו של חבירו],\u0006 \u0003אמרו ליה\u0004 \u0005[היו אומרים לו]:\u0006 \u0003הבה ניהליה\u0004 \u0005[תן לו]\u0006 \u0003עד דקדחא\u0004 \u0005[שתצמח\u0006 האוזן\u0005].\u0006 \u0003דפדע ליה לחבריה, אמרי ליה\u0004 \u0005[\u0006מי \u0005שהיה פוצע את חבירו, היו אומרים לו]\u0006 למוכה: \u0003הב ליה אגרא, דשקל לך דמא\u0004 \u0005[תן לו\u0006 לפוצע \u0005שכר, שהקיז ממך דם]\u0006 ומגיע לו שכר מלאכה זו.","מי ש\u0003עבר במברא\u0004 \u0005[במעבורת]\u0006 — \u0003יהיב\u0004 \u0005[נותן]\u0006 \u0003ארבעה זוזי\u0004 \u0005[זוזים],\u0006 ומי ש\u0003עבר במיא\u0004 \u0005[במים]\u0006 \u0003יהיב תמני זוזי\u0004 \u0005[נותן שמונה זוזים].\u0006 \u0003זימנא חדא אתא ההוא כובס, איקלע להתם\u0004 \u0005[פעם אחת בא כובס אחד, הזדמן לשם],\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003ארבע זוזי\u0004 \u0005[זוזים]\u0006 שכר מעבורת! \u0003אמר להו: אנא במיא עברי\u0004 \u0005[אני במים עברתי]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אם כן הב תמניא\u0004 \u0005[תן שמונה]\u0006 לפי ש\u0003עברת במיא\u0004 \u0005[במים].\u0006 \u0003לא יהיב\u0004 \u0005[נתן].\u0006 \u0003פדיוהו\u0004 \u0005[\u0006הכוהו \u0005ופצעוהו].\u0006 \u0003אתא לקמיה דדיינא\u0004 \u0005[בא לפני הדיין]\u0006 לתבוע פיצויים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הדיין: \u0003הב ליה אגרא דשקיל\u0004 \u0005[תן לו שכר\u0006 על \u0005שנטל,\u0006 הקיז\u0005]\u0006 \u0003לך דמא\u0004 \u0005[דם],\u0006 \u0003ותמניא זוזי\u0004 \u0005[\u0006ועוד \u0005שמונה זוזים]\u0006 על ש\u0003עברת במיא\u0004 \u0005[במים].\u0006","\u0003אליעזר עבד אברהם איתרמי התם, פדיוהו\u0004 \u0005[הזדמן לשם,\u0006 ו\u0005פצעוהו].\u0006 \u0003אתא לקמיה דיינא\u0004 \u0005[בא לפני הדיין]\u0006 לתבוע פיצויים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הדיין: \u0003הב ליה אגרא דשקל\u0004 \u0005[תן לו שכר\u0006 על \u0005שנטל,\u0006 הקיז\u0005]\u0006 \u0003לך דמא\u0004 \u0005[דם].\u0006 \u0003שקל גללא, פדיוהי איהו לדיינא\u0004 \u0005[לקח אבן,\u0006 ו\u0005פצע הוא את הדיין].\u0006 \u0003אמר\u0004 הדיין: \u0003מאי האי\u0004 \u0005[מה זה]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליעזר: \u0003אגרא דנפק\u0004 \u0005[\u0006את \u0005השכר שיצא,\u0006 מגיע\u0005]\u0006 \u0003לי מינך\u0004 \u0005[ממך],\u0006 \u0003הב ניהליה להאי\u0004 \u0005[תן לו לזה],\u0006 \u0003וזוזי דידי כדקיימי קיימי\u0004 \u0005[והכסף שלי כמו שנמצא נמצא].\u0006","ועוד ממנהגי אנשי סדום: \u0003הויא להו פורייתא דהוו מגני עלה אורחין\u0004 \u0005[היתה להם מטה שהיו משכיבים עליה\u0006 את \u0005האורחים],\u0006 \u0003כי מאריך\u0004 \u0005[כאשר היה\u0006 האורח \u0005ארוך]\u0006 — \u0003גייזי ליה\u0004 \u0005[היו מקצצים אותו],\u0006 \u0003כי\u0004 \u0005[\u0006ו\u0005כאשר]\u0006 דהיה \u0003גוץ,\u0004 וקצר היה מן המיטה — \u0003מתחין ליה\u0004 \u0005[היו מותחים אותו].\u0006 \u0003אליעזר עבד אברהם אקלע להתם\u0004 \u0005[הזדמן לשם]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003קום גני אפוריא\u0004 \u0005[בוא\u0006 ו\u0005שכב על המטה],\u0006 \u0003אמר להון\u0004 \u0005[להם]:\u0006 \u0003נדרא נדרי, מן יומא דמיתת אמא לא גנינא אפוריא\u0004 \u0005[נדר נדרתי, מיום שמתה אמי איני שוכב על מטה].\u0006","ועוד נהגו: \u0003כי הוה מתרמי להו עניא, יהבו ליה כל חד וחד דינרא וכתיב שמיה עליה\u0004 \u0005[כאשר היה מזדמן להם עני, היו נותנים לו כל אחד ואחד דינר וכתוב שמו\u0006 של הנותן \u0005על\u0006 הדינר\u0005],\u0006 \u0003וריפתא\u0004 \u0005[ולחם]\u0006 \u0003לא הוו ממטי ליה\u0004 \u0005[היו נותנים,\u0006 או מוכרים, \u0005לו]\u0006 כדי שלא יוכל להוציא את דינריו, וימות ברעב. \u0003כי הוה מית, אתי\u0004 \u0005[כאשר היה מת,\u0006 היה \u0005בא]\u0006 \u0003כל חד וחד שקיל דידיה\u0004 \u0005[אחד ואחד\u0006 ו\u0005לוקח את\u0006 דינרו \u0005שלו].\u0006","\u0003הכי אתני בינייהו\u0004 \u0005[כך התנו ביניהם]:\u0006 \u0003 כל מאן דמזמין גברא לבי הילולא, לשלח גלימא\u0004 \u0005[מי שמזמין אורח לחתונה, יורידו\u0006 את \u0005גלימתו].\u0006 \u0003הוי האי הילולא\u0004 \u0005[היתה חתונה אחת],\u0006 \u0003אקלע\u0004 \u0005[הזדמן]\u0006 \u0003אליעזר\u0004 עבד אברהם \u0003להתם\u0004 \u0005[לשם]\u0006 \u0003ולא יהבו ליה נהמא\u0004 \u0005[נתנו לו לחם].\u0006 \u0003כי בעי למסעד, אתא\u0004 \u0005[כאשר רצה לסעוד, בא]\u0006 \u0003אליעזר ויתיב לסיפא דכולהו\u0004 \u0005[וישב לסוף כולם]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מאן אזמנך להכא\u0004 \u0005[מי הזמינך לכאן]?\u0006 \u0003אמר ליה לההוא דיתיב\u0004 \u0005[לו לזה שישב]\u0006 לצידו: \u0003אתה זמנתן\u0004 \u0005[הזמנתני].\u0006 \u0003אמר\u0004 אותו אדם בלבו: \u0003דילמא שמעי בי דאנא אזמינתיה ומשלחי ליה מאניה דהאי גברא\u0004 \u0005[שמא ישמעו עלי שאני הזמנתי אותו ויפשיטו את בגדיו של אותו איש,\u0006 כלומר, שלי\u0005].\u0006 \u0003שקל גלימיה\u0004 \u0005[לקח\u0006 את \u0005גלימתו]\u0006 \u0003ההוא דיתיב גביה\u0004 \u0005[שישב אצלו,\u0006 לידו\u0005]\u0006 \u0003ורהט לברא\u0004 \u0005[וברח החוצה].\u0006 \u0003וכן עבד לכולהו\u0004 \u0005[עשה\u0006 אליעזר \u0005לכולם]\u0006 \u0003עד דנפקי כולהו ואכלא איהו לסעודתא\u0004 \u0005[שיצאו כולם, ואכל הוא את הסעודה].\u0006","\u0003הויא ההיא רביתא דהות קא מפקא ריפתא לעניא בחצבא\u0004 \u0005[היתה\u0006 שם \u0005נערה אחת שהיתה מוציאה לחם לעניים ב\u0006תוך \u0005כד]\u0006 שלא יראוה בני המקום, \u0003איגלאי מלתא, שפיוה דובשא, ואוקמוה\u0004 \u0005[נתגלה הדבר, משחוה\u0006 ב\u0005דבש, והעמידוה]\u0006 \u0003על איגר שורא\u0004 \u0005[גג חומת\u0006 העיר\u0005],\u0006 \u0003אתא זיבורי ואכלוה\u0004 \u0005[\u0006\u0005באו הצרעות ואכלוה].\u0006 \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"ויאמר ה' זעקת סדם ועמרה כי רבה\"\u0004 (בראשית יח, כ), \u0003ואמר רב יהודה אמר רב:\u0004 המלה \"רבה\" מרמזת \u0003על עיסקי ריבה\u0004 (נערה) זו שהמיתוה על שעשתה חסד. ועל עוון זה נחתם גזר דינם.","שנינו במשנה שה\u0003מרגלים אין להם חלק לעולם הבא, שנאמר: \"וימתו האנשים מוצאי דבת הארץ רעה במגפה\u0004 לפני ה' \" (במדבר יד, לז), \u0003\"וימתו\"\u0004 — \u0003בעולם הזה, \"במגפה\"\u0004 — \u0003לעולם הבא.\u0004","\u0003עדת קרח אין להם חלק לעולם הבא, שנאמר: \"ותכס עליהם הארץ\"\u0004 (במדבר טז, לג) — \u0003בעולם הזה, \"ויאבדו מתוך הקהל\"\u0004 (במדבר טז, לג) — \u0003לעולם הבא,\u0004 אלו \u0003דברי ר' עקיבא. ר' אליעזר אומר: עליהם אמר הכתוב \"ה' ממית ומחיה מוריד שאול ויעל\"\u0004 (שמואל א' ב, ו) ויש להם תקומה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בתוספתא\u0005]:\u0006 \u0003עדת קרח אין להם חלק לעולם הבא, שנאמר: \"ותכס עליהם הארץ\"\u0004 — משמע שאבדו \u0003בעולם הזה, \"ויאבדו מתוך הקהל\"\u0004 — \u0003לעולם הבא,\u0004 אלו \u0003דברי ר' עקיבא. ר' יהודה בן בתירא אומר:\u0004 אף שנאמר שאבדו, \u0003הרי הן כאבידה המתבקשת\u0004 שמחפשים אותה וגואלים אותה לבסוף, \u0003שנאמר: \"תעיתי כשה אבד בקש עבדך כי מצותיך לא שכחתי\"\u0004 (תהלים קיט, קעו). כיון שהוזכר קרח, דורשים מה שנאמר בו.","על הנאמר \u0003\"ויקח קרח\u0004 בן יצהר בן קהת בן לוי\u0003\"\u0004 (במדבר טז, א), \u0003אמר ריש לקיש: שלקח מקח רע לעצמו,\u0004 שעל ידי מעשיו אבד עצמו מן העולם. \u0003\"קרח\"\u0004 — רמז \u0003שנעשה קרחה בישראל. \"בן יצהר\"\u0004 — \u0003בן שהרתיח\u0004 (הכעיס) \u0003עליו את כל העולם כצהרים\u0004 (\"יצהר\"). \u0003\"בן קהת\"\u0004 — \u0003בן שהקהה שיני מולידיו, \"בן לוי\"\u0004 — \u0003בן שנעשה לויה בגיהנם.\u0004","ושואלים: אם יחוסו של קרח כולו נדרש לגנאי \u0003וליחשוב נמי\u0004 \u0005[שיחשבו גם כן]\u0006 ברשימה \u0003\"בן יעקב\"\u0004 ונדרשנו: \u0003בן שעקב\u0004 (עיקם) \u0003עצמו\u0004 עד שהגיע \u0003לגיהנם! אמר רב שמואל בר רב יצחק: יעקב ביקש רחמים על עצמו\u0004 שלא ימנה בתוך יחוס זה, והוא \u0003שנאמר: \"בסדם אל תבא נפשי בקהלם אל תחד כבדי\"\u0004 (בראשית מט, ו), וכך פירושו של כתוב זה: \u0003\"בסדם אל תבא נפשי\"\u0004 — \u0003אלו מרגלים\u0004 שלא יזכר שמו של יעקב ביחוסם, \u0003\"בקהלם אל תחד כבדי\"\u0004 — \u0003זה עדת קרח.\u0004","ועוד דורשים את שאר שמות מנהיגי החבורה: \u0003\"דתן\"\u0004 נדרש: \u0003שעבר על דת אל. \"אבירם\"\u0004 — \u0003שאיבר\u0004 (חיזק) \u0003עצמו מעשות תשובה. \"ואון\"\u0004 — \u0003שישב באנינות\u0004 (כאבל על חטא שחטא, שהוא חזר בו ונשאר קיים). \u0003\"פלת\"\u0004 — \u0003שנעשו לו פלאות, \"בן ראובן\"\u0004 — \u0003בן שראה והבין\u0004 טיבם של דברים שעשה וחזר בו.","\u0003אמר רב: און בן פלת\u0004 לא מכח עצמו עשה תשובה, אלא \u0003אשתו הצילתו, אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003מאי נפקא\u0004 \u0005[מה יצא]\u0006 \u0003לך מינה\u0004 \u0005[מ\u0006קטטה \u0005זו]?\u0006 \u0003אי מר רבה\u0004 \u0005[אם זה,\u0006 משה, הוא \u0005הרב]\u0006 — תהיה \u0003אנת תלמידא\u0004 \u0005[אתה התלמיד],\u0006 \u0003ואי מר רבה\u0004 \u0005[אם זה,\u0006 קרח, הוא \u0005הרב]\u0006 — תהיה \u0003אנת תלמידא\u0004 \u0005[אתה התלמיד],\u0006 ולשם מה לך לריב? \u0003אמר לה: מאי אעביד\u0004 \u0005[מה אעשה]?\u0006 \u0003הואי\u0004 \u0005[הייתי]\u0006 \u0003בעצה ואשתבעי לי בהדייהו\u0004 \u0005[ונשבעתי עמם]\u0006 שאהיה עמם בכל דבר. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003ידענא דכולה כנישתא קדישתא נינהו\u0004 \u0005[יודעת אני שכל העדה קדושה היא],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי כל העדה כלם קדשים\"\u0004 (במדבר, טז, ג), ונזהרים הם בצניעות. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003תוב, דאנא מצילנא לך\u0004 \u0005[שב, שאני מצילה אותך].\u0006 \u0003אשקיתיה חמרא וארויתיה, ואגניתיה גואי\u0004 \u0005[השקתו יין ושכרתו, והשכיבה אותו בפנים].\u0006 \u0003אותבה\u0004 \u0005[התיישבה]\u0006 \u0003על בבא\u0004 \u0005[שער\u0006 פתח הבית\u0005],\u0006"]]};
